window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["天气"]=[{"uid":"8d95a8c6-e757-4b75-8c96-a3506d6c7c6f","title":"西山三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彝界荒山顶，蕃州积雪边。","筑城依白帝，转粟上青天。","蜀将分旗鼓，羌兵助井泉。","西戎背和好，杀气日相缠。"],"theme":"山水田园","theme2":["边塞征战"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写雪"]},"theme_conf":0.571},{"uid":"a0d7cfef-2d17-4f6b-983f-ed65c3dff9a2","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹赤白，尽是阻军行。","若是（京本作「似」）虹桥栏着路，且须盘泊犒（京本作「靠」）军兵，不久却回程。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"cp9d526676093b5f","title":"绿意・疏影","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧圆自洁。","向浅洲远渚，亭亭清绝。","犹有遗簪，不展秋心，能卷几多炎热。","鸳鸯密语同倾盖，且莫与、浣纱人说。","恐怨歌、忽断花风，碎却翠云千叠。","回首当年汉舞，怕飞去、谩皱留仙裙折。","恋恋青衫，犹染枯香，还叹鬓丝飘雪。","盘心清露如铅水，又一夜、西风吹折。","喜静看、匹练秋光，倒泻半湖明月。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","恬淡"],"scene":["江","秋","月"],"cats":{"抒情":["爱情"],"四季":["秋天"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"22ec1415-85ee-4aa1-8838-62aa3c9b66dd","title":"醉时歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["诸公衮衮登台省，广文先生官独冷。","甲第纷纷厌粱肉，广文先生饭不足。","先生有道出羲皇，先生有才过屈宋。","德尊一代常𫐘轲，名垂万古知何用。","杜陵野客人更嗤，被褐短窄鬓如丝。","日籴太仓五升米，时赴郑老同襟期。","得钱即相觅，沽酒不复疑。","忘形到尔汝，痛饮真吾师。","清夜沈沈动春酌，灯前细雨檐花落。","但觉高歌有鬼神，焉知饿死填沟壑。","相如逸才亲涤器，子云识字终投阁。","先生早赋归去来，石田茅屋荒苍苔。","儒术于我何有哉，孔丘盗跖俱尘埃。","不须闻此意惨怆，生前相遇且衔杯。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"幽峭","style2":["雄浑","豪放"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["孤独"],"天气":["写雨"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"a0bee52e-3b61-475b-9f5b-120e056e24da","title":"中秋与空上人同宿华严寺","author":"冷朝阳","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["埽榻相逢宿，论诗旧梵宫。","磬声迎鼓尽，月色过山穷。","庭簇安禅草，窗飞带火虫。","一宵何惜别，回首隔秋风。"],"theme":"山水田园","theme2":["节令风俗"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"19a60c13-e4f4-4653-8262-70e474cc636a","title":"景龙四年正月五日移仗蓬莱宫御大明殿会吐蕃骑马之戏因重为柏梁体联句","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["大明御宇临万方，顾慙内政翊陶唐。","鸾鸣凤舞向平阳，秦楼鲁馆沐恩光。","无心为子辄求郎，雄才七步谢陈王。","当熊让辇媿前芳，再司铨筦恩可忘。","文江学海思济航，万邦考绩臣所详。","著作不休出中肠，权豪屏迹肃严霜。","铸鼎开岳造明堂，玉醴由来献寿觞。"],"theme":"游仙梦幻","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["月","酒"],"cats":{"天气":["月亮"],"动物":["写马"]},"theme_conf":1.0},{"uid":"b2d89260-e3b7-4077-aaaa-0a67db01d5b6","title":"酬窦拾遗秋日见呈","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["孤城永巷时相见，衰柳闲门日半斜。","欲送近臣朝魏阙，犹怜残菊在陶家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.93},{"uid":"40a92675-3a77-4ce1-9242-17eb287a246a","title":"渡江秋怨二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渡秋江兮渺然，望秋月兮婵娟。","色如练，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遥夜兮伤心。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"6b65b2f9-0c0d-4b94-92ad-af22334582cf","title":"九日酬颜少府","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["簷前白日应可惜，篱下黄花为谁有。","行子迎霜未授衣，主人得钱始沽酒。","苏秦顦顇人多厌，蔡泽栖迟世看丑。","纵使登高只断肠，不如独坐空搔首。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"402d45dc-7d64-4a0a-b731-79551c95ba91","title":"詶裴云客","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["自厌久荒浪，于时无所任。","耕钓以为事，来家樊水阴。","甚醉或漫歌，甚闲亦漫吟。","不知愚僻意，称得云客心。","云客方持斧，与人正相临。","符印随坐起，守位常森森。","纵能有相招，岂暇来山林。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.449},{"uid":"fea6e004-d905-4fa0-9f6c-c813af7862e6","title":"对雨书怀走邀许十一簿公","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东岳云峰起，溶溶满太虚。","震雷飜幕燕，骤雨落河鱼。","座对贤人酒，门听长者车。","相邀媿泥泞，骑马到阶除。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":1.0},{"uid":"ac2ec0ba-10b1-4ae3-8859-1e7752625331","title":"哥舒歌","author":"西鄙人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["北斗七星高，哥舒夜带刀。","至今窥牧马，不敢过临洮。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"天气":["星星"]},"theme_conf":1.0},{"uid":"e56e4c5d-9552-4ec9-a4c5-a86e08e1ef6f","title":"相和歌辞 春江花月夜二首 一","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["林花发岸口，气色动江新。","此夜江中月，流光花上春。","分明石潭里，宜照浣纱人。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","夜","月","江","花"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.91},{"uid":"bdeeaa87-d383-44e2-8245-d18fcffb107f","title":"柟树为风雨所拔叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["倚江柟树草堂前，故老相传二百年。","诛茅卜居总为此，五月髣髴闻寒蝉。","东南飘风动地至，江翻石走流云气。","干排雷雨犹力争，根断泉源岂天意。","沧波老树性所爱，浦上童童一青盖。","野客频留惧雪霜，行人不过听竽籁。","虎倒龙颠委榛棘，泪痕血点垂胷臆。","我有新诗何处吟，草堂自此无颜色。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感"],"天气":["写风","写雨"]},"theme_conf":1.0},{"uid":"292c14cd-151f-4321-a94c-46fc86693eb3","title":"秋日赴阙题潼关驿楼","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红叶晚萧萧，长亭酒一瓢。","残云归太华，疎雨过中条。","树色随山迥，河声入海遥。","帝乡明日到，犹自梦渔樵。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["楼","秋"],"cats":{"抒情":["离别","思乡"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.78},{"uid":"7136e8b6-cec9-423f-89e9-a260eeb32481","title":"春日登陕州城楼俯眺原野回丹碧缀烟霞密翠斑红芳菲花柳即目川岫聊以命篇","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧原开雾隰，绮岭峻霞城。","烟峰高下翠，日浪浅深明。","斑红粧橤树，圆青压溜荆。","迹岩劳傅想，窥野访莘情。","巨川何以济，舟楫伫时英。"],"theme":"山水田园","theme2":["咏史怀古","山水田园"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","花"],"cats":{"抒情":["怀古"],"四季":["春天"],"天气":["太阳"],"植物":["柳树"]},"theme_conf":0.82},{"uid":"2fe129d5-d149-4ff3-acb0-8f50048d8e89","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 五","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹入井，尽是败军情。","或有（京本作「似」）鼠形营上现，忽然交战血成坑，防（京本作「勿」）撃保城营。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp1acc2f34cdbd10","title":"东风第一枝","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["巧沁兰心，偷黏草甲，东风欲障新暖。","谩凝碧瓦难留，信知暮寒轻浅。","行天入镜，做弄出、轻松纤软。","料故园、不卷重帘，误了乍来双燕。","青未了、柳回白眼。","红欲断、杏开素面。","旧游忆著山阴，厚盟遂妨上苑。","寒炉重暖，便放慢春衫针线。","恐凤靴、挑菜归来，万一灞桥相见。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"7ec1676f-cc0c-4065-bffc-26fbe3124c8d","title":"铁笔歌（今按：疑为后人所作，录附参考。）","author":"张巡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["皇天生我兮男子，君王用我兮熊罴。","力拔山兮势雄，气贯日兮虹霓。","月正明兮磨鎗砺剑，星未落兮击鼓掀旗。","捣贼室兮焚寨，脔贼肉兮充饥。","食马革兮计尽，杀妻妾兮心悲。","为厉鬼兮身被铁甲，为明神兮手执金锤。","亦莫指我为张毅，亦莫指我为张飞。","我乃唐之张巡，与许远兮同时。","在东岳兮押案，都统使兮阴司。","事蓬莱兮殿直，任酆都兮狱推。","景祐真君兮阳间封爵，忠烈大夫兮天上官资。","漫濡毫而为翰，俾世人而皆知。","（《古今图书集成·职方典》三九九《归德府部》）（〖1〗康熙《商邱县志》卷十八收此诗，注：「公降乩所作。","」）。"],"theme":"游仙梦幻","theme2":["民生疾苦"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["彩虹"]},"theme_conf":0.519},{"uid":"ee8b870e-a2de-45e4-8fa6-a805e3ae1f7c","title":"相和歌辞 江南曲","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["为爱江南雪，涉江聊采苹。","水深烟浩浩，空对双车轮。","车轮明月团，车盖浮云盘。","云月徒自好，水中行路难。","遥遥洛阳道，夹岸生春草。","寄语櫂船郎，莫夸风浪好。"],"theme":"山水田园","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"天气":["月亮"]},"theme_conf":0.56},{"uid":"0ba4d426-8dd5-4a77-9566-98d96222417f","title":"相和歌辞 江南曲","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["美人何荡漾，湖上风月长。","玉手欲有赠，裴回双鸣珰。","歌声随渌水，怨色起朝阳。","日暮还家望，云波横洞房。"],"theme":"爱情相思","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"天气":["太阳"],"人物":["女子"]},"theme_conf":0.85},{"uid":"a4c287ae-d6f5-414a-a05b-f69d7baff4a0","title":"水阁朝霁奉简严云安","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城抱春岑，江阁邻石面。","崔嵬晨云白，朝旭射芳甸。","雨槛卧花丛，风床展书卷。","钩帘宿鹭起，丸药流莺啭。","呼婢取酒壶，绩儿诵文选。","晚交严明府，矧此数相见。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","酒"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["读书"]},"theme_conf":0.9},{"uid":"bb8bcabd-0823-4dea-bf90-a3a59aec3f22","title":"宿云门上方","author":"秦系","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禅室遥看峰顶头，白云东去水长流。","松间傥许幽人住，不更将钱买沃州。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"],"人生":["哲理"]},"theme_conf":0.626},{"uid":"3205a2f2-b86f-4f86-9003-dc338f8f839d","title":"和卢赞府游纪国道场","author":"慧净","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日光通汉室，星彩晦周朝。","法城从此构，香阁本岧峣。","株盘仰承露，刹凤俯摩霄。","落照侵虚牖，长虹拖跨桥。","高才暂骋目，云藻随飘飖。","欲追千里骥，终是谢连镳。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"683085c0-248c-4545-998b-a04be7b8fd48","title":"江边星月二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骤雨清秋夜，金波耿玉绳。","天河元自白，江浦向来澄。","映物连珠断，缘空一镜升。","余光隐更漏，况乃露华凝。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["江","夜","月"],"cats":{"山水":["江河"],"天气":["写雨","月亮","星星"]},"theme_conf":0.65},{"uid":"629687ee-7e6f-4b7a-8c3d-2034d5e752da","title":"远游联句","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别肠车轮转，一日一万周。","离思春冰泮，澜漫不可收。","驰光忽以迫，飞辔谁能留。","取之讵灼灼，此去信悠悠。","楚客宿江上，夜魂栖浪头。","晓日生远岸，水芳缀孤舟。","村饮泊好木，野蔬拾新柔。","独含凄凄别，中结郁郁愁。","人忆旧行乐，鸟吟新得俦。","灵瑟时窅窅，霠猨夜啾啾。","愤涛气尚盛，恨竹泪空幽。","长怀绝无已，多感良自尤。","即路涉献岁，归期眇凉秋。","两欢日牢落，孤悲坐绸缪。","观怪忽荡漾，叩奇独冥搜。","海鲸吞明月，浪岛没大沤。","我有一寸钩，欲钓千丈流。","良知忽然远，壮志郁无抽。","魍魅暂出没，蛟螭互蟠蟉。","昌言拜舜禹，举颿凌斗牛。","怀糈餽贤屈，乘桴追圣丘。","飘然天外步，岂肯区中囚。","楚些待谁吊，贾辞缄恨投。","翳明弗可晓，秘魂安所求。","气毒放逐域，蓼杂芳菲畴。","当春忽凄凉，不枯亦飕飗。","貉谣众猥款，巴语相咿嚘。","默誓去外俗，嘉愿还中州。","江生行既乐，躬辇自相勠。","饮醇趣明代，味腥谢荒陬。","驰深鼓利檝，趋险惊蜚𬨎。","系石沈靳尚，开弓射𫛝吺。","路暗执屏翳，波惊戮阳侯。","广泛信缥缈，高行恣浮游。","外患萧萧去，中悒稍稍瘳。","振衣造云阙，跪坐陈清猷。","德风变谗巧，仁气销戈矛。","名声照西海，淑问无时休。","归哉孟夫子，归去无夷犹。"],"theme":"送别","theme2":["边塞征战","羁旅思乡","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"愁怨","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.83},{"uid":"bb93206b-92a8-4440-aeb5-4cc3bbe596ea","title":"送僧方及南谒柳员外","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔事庐山远，精舍虎溪东。","朝阳照瀑水，楼阁虹霓中。","骋望羡游云，振衣若秋蓬。","旧房闭松月，远思吟江风。","古寺历头陀，奇峰扳祝融。","南登小桂岭，却望归塞鸿。","衣裓贮文章，自言学雕虫。","抢榆念陵厉，覆篑图穹崇。","远郡多暇日，有诗访禅宫。","石门耸峭绝，竹院含空蒙。","幽响滴岩溜，晴芳飘野丛。","海云悬飓母，山果属狙公。","忽忆吴兴郡，白苹正葱茏。","愿言挹风采，邈若窥华嵩。","桂水夏澜急，火山宵焰红。","三衣濡菌露，一锡飞烟空。","勿谓翻译徒，不为文雅雄。","古来赏音者，燋爨得孤桐。"],"theme":"送别","theme2":["哲理悟道","送别"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"山水":["庐山"],"天气":["彩虹","太阳"],"人生":["哲理"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"d5ac076b-9170-4aa1-b6a4-c67a96445b79","title":"洛滨病卧户部李侍郎见惠药物谑以文星之句斐然仰谢","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隐几支颐对落晖，故人书信到柴扉。","周南留滞商山老，星象如今属少微。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["友情","感恩"],"天气":["星星"]},"theme_conf":0.95},{"uid":"bcf88d70-488c-40a7-b7bf-febc7ab7c797","title":"同王员外雨后登开元寺南楼因寄西岩警上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["过雨开楼看晚虹，白云相逐水相通。","寒蝉噪暮野无日，古树伤秋天有风。","数穗远烟凝垅上，一枝繁果忆山中。","何言暂别东林友，惆怅人间事不同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","楼","山","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.87},{"uid":"86d084a1-6ccd-49a1-8757-cebc29ef13e8","title":"陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日放船好，轻风生浪迟。","竹深留客处，荷净纳凉时。","公子调冰水，佳人雪藕丝。","片云头上黑，应是雨催诗。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"7dccdf60-ec93-4a4d-be1c-4d725b92cb8e","title":"秋雨叹三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雨中百草秋烂死，阶下决明颜色鲜。","著叶满枝翠羽盖，开花无树黄金钱。","凉风萧萧吹汝急，恐汝后时难独立。","堂上书生空白头，临风三齅馨香泣。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["秋","雨"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.8},{"uid":"9ca5eb72-69e6-47f0-a27d-06034645217d","title":"酬裴员外以诗代书","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少时方浩荡，遇物犹尘埃。","脱略身外事，交游天下才。","单车入燕赵，独立心悠哉。","宁知戎马间，忽展平生怀。","且欣清论高，岂顾夕阳颓。","题诗碣石馆，纵酒燕王台。","北望沙漠垂，漫天雪皑皑。","临边无策略，览古空裴回。","乐毅吾所怜，拔齐翻见猜。","荆卿吾所悲，适秦不复廻。","然诺多死地，公忠成祸胎。","与君从此辞，每恐流年催。","如何俱老大，始复忘形骸。","兄弟真二陆，声名连八裴。","乙未将星变，贼臣候天灾。","胡骑犯龙山，乘舆经马嵬。","千官无倚着，万姓徒悲哀。","诛吕鬼神动，安刘天地开。","奔波走风尘，倏忽值云雷。","拥旄出淮甸，入幕征楚材。","誓当剪鲸鲵，永以竭驽骀。","小人胡不仁，谗我成死灰。","赖得日月明，照耀无不该。","留司洛阳宫，詹府唯蒿莱。","是时扫氛祲，尚未歼渠魁。","背河列长围，师老将亦乖。","归军剧风火，散卒争椎埋。","一夕瀍洛空，生灵悲曝腮。","衣冠投草莽，予欲驰江淮。","登顿宛叶下，栖遑襄邓隈。","城池何萧条，邑屋更崩摧。","纵横荆棘丛，但见瓦砾堆。","行人无血色，战骨多青苔。","遂除彭门守，因得朝玉阶。","激昂仰鹓鹭，献替欣盐梅。","驱传及远蕃，忧思郁难排。","罢人纷争讼，赋税如山崖。","所思在畿甸，曾是鲁宓侪。","自从拜郎官，列宿焕天街。","那能访遐僻，还复寄琼瓌。","金玉本高价，埙箎终易谐。","朗咏临清秋，凉风下庭槐。","何意寇盗间，独称名义偕。","辛酸陈侯诔，叹息季鹰杯。","白日屡分手，青春不再来。","卧看中散论，愁忆太常斋。","酬赠徒为尔，长歌还自咍。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨","豪放"],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["酒","雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"人生":["青春","时光","战争"]},"theme_conf":0.94},{"uid":"5ec67bba-ece4-49ff-81b0-455d662a0be2","title":"荣华乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["鸢肩公子二十余，齿编贝，唇激朱。","气如虹霓，饮如建瓴。","走马夜归呌严更，径穿复道游椒房。","龙裘金玦杂花光，玉堂调笑金楼子。","台下戏学邯郸倡，口吟舌话称女郎。","锦祛绣面汉帝旁，得明珠十斛。","白璧一双，新诏垂金曳紫光煌煌。","马如飞，人如水。","九卿六官皆望履，将回日月先反掌。","欲作江河唯画地，峨峨虎冠上切云。","竦劒晨趋凌紫氛，绣段千寻贻皂隶。","黄金百镒贶家臣，十二门前张大宅。","晴春烟起连天碧，金铺缀日杂红光。","铜龙啮环似争力，瑶姬凝醉卧芳席。","海素笼窗空下隔，丹穴取凤充行庖。","貜貜如拳那足食，金蟾呀呀兰烛香。","军装武妓声琅珰，谁知花雨夜来过。","但见池台春草长，嘈嘈弦吹匝天开。","洪厓箫声遶天来，天长一矢贯双虎。","云弝绝骋聒旱雷，乱袖交竿管儿舞。","吴音绿鸟学言语，能教刻石平紫金。","解送刻毛寄新兔，三皇皇后七贵人。","五十校尉二将军，当时飞去逐彩云，化作今日京华春。"],"theme":"讽喻刺世","theme2":["送别","边塞征战"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","月","楼","夜","春"],"cats":{"四季":["春天"],"天气":["写云","彩虹"]},"theme_conf":0.86},{"uid":"e1f2edef-a6a6-40bd-97e1-c5dedb7976b2","title":"题桐叶","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["去年桐落故溪上，把笔偶题归燕诗。","江楼今日送归燕，正是去年题叶时。","叶落燕归真可惜，东流玄髪且无期。","笑筵歌席反惆怅，明月清风怆别离。","庄叟彭殇同在梦，陶潜身世两相遗。","一丸五色成虚语，石烂松薪更莫疑。","哆侈不劳文似锦，进趋何必利如锥。","钱神任尔知无敌，酒圣于吾亦庶几。","江畔秋光蟾阁镜，槛前山翠茂陵眉。","樽香轻泛数枝菊，簷影斜侵半局棋。","休指宦游论巧拙，秪将愚直祷神祇。","三吴烟水平生念，宁向闲人道所之。"],"theme":"咏怀抒感","theme2":["闲适隐逸","咏物"],"style":"旷达","style2":["婉约","绮丽"],"mood":"惆怅","mood2":[],"scene":["月","酒","楼"],"cats":{"抒情":["离别"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.85},{"uid":"e7c246f6-8c50-43a0-b4ad-6a42a6cf6d7e","title":"云梦故城秋望","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故国遗墟在，登临想旧游。","一朝人事变，千载水空流。","梦渚鸿声晚，荆门树色秋。","片云凝不散，遥挂望乡愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.479},{"uid":"cpe95478f7a37a64","title":"薄幸","author":"吕渭老","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青楼春晚。","昼寂寂、梳匀又懒。","乍听得、鸦啼莺弄，惹起新愁无限。","记年时、偷掷春心，花间隔雾遥相见。","便角枕题诗，宝钗贳酒，共醉青苔深院。","怎忘得、回廊下，携手处、花明月满。","如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。","却谁拘管。","尽无言、闲品秦筝，泪满参差雁。","腰支渐小，心与杨花共远。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","春","月","酒","园林"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.62},{"uid":"91019fe2-b58e-4320-a986-6a323847e944","title":"相和歌辞 春江花月夜","author":"张若虚","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["春江潮水连海平，海上明月共潮生。","滟滟随波千万里，何处春江无月明？","江流宛转遶芳甸，月照花林皆似霰。","空里流霜不觉飞，汀上白沙看不见。","江天一色无纤尘，皎皎空中孤月轮。","江畔何人初见月？江月何年初照人？","人生代代无穷已，江月年年望相似。","不知江月待何人，但见长江送流水。","白云一片去悠悠，青枫浦上不胜愁。","谁家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，应照离人妆镜台。","玉户帘中卷不去，捣衣砧上拂还来。","此时相望不相闻，愿逐月华流照君。","鸿雁长飞光不度，鱼龙潜跃水成文。","昨夜闲潭梦落花，可怜春半不还家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海雾，碣石潇湘无限路。","不知乘月几人归，落月摇情满江树。"],"theme":"爱情相思","theme2":["送别","羁旅思乡"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","月","春"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"山水":["江河","长江"],"天气":["月亮"]},"theme_conf":0.75},{"uid":"a8d2011c-dc24-4e9a-a795-92e7473c7ad1","title":"春夜过长孙绎别业","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期难再得，清夜此云林。","带竹新泉冷，穿花片月深。","含毫凝逸思，酌水话幽心。","不觉星河转，山枝惊曙禽。"],"theme":"山水田园","theme2":["送别","闲适隐逸","咏史怀古"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","春"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"天气":["星星"]},"theme_conf":0.74},{"uid":"5a76b6ea-07ee-44b6-ac20-a87d18203810","title":"答侯少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常日好读书，晚年学垂纶。","漆园多乔木，睢水清粼粼。","诏书下柴门，天命敢逡巡。","赫赫三伏时，十日到咸秦。","褐衣不得见，黄绶翻在身。","吏道顿羁束，生涯难重陈。","北使经大寒，关山饶苦辛。","边兵若刍狗，战骨成埃尘。","行矣勿复言，归欤伤我神。","如何燕赵陲，忽遇平生亲。","开馆纳征骑，弹弦娱远宾。","飘飖天地间，一别方兹晨。","东道有佳作，南朝无此人。","性灵出万象，风骨超常伦。","吾党谢王粲，群贤推郄诜。","明时取秀才，落日过蒲津。","节苦名已富，禄微家转贫。","相逢愧薄游，抚己荷陶钧。","心事正堪尽，离居宁太频。","两河归路遥，二月芳草新。","柳接滹沱暗，莺连渤海春。","谁谓行路难，猥当希代珍。","提握每终日，相思犹比邻。","江海有扁舟，丘园有角巾。","君意定何适，我怀知所遵。","浮沈各异宜，老大贵全真。","莫作云霄计，遑遑随缙绅。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":["旷达"],"mood":"相思","mood2":[],"scene":["舟","春","鸟"],"cats":{"抒情":["离别","思念","思乡"],"四季":["春天"],"天气":["太阳"],"人生":["读书","战争"]},"theme_conf":0.96},{"uid":"f3bc86a7-d987-48d2-9f94-5df3bdc2934c","title":"郊庙歌辞 享太庙乐章 文舞","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["圣謩九德，真言五千。","庆集昌胄，符开帝先。","高文杖钺，克配彼天。","三宗握镜，六合涣然。","帝其承祀，率礼罔愆。","图书雾出，日月清悬。","舞形德类，咏谂功传。","黄龙蜿蟺，彩云蹁跹。","五行气顺，八佾风宣。","介此百禄，于皇万年。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"天气":["写云"]},"theme_conf":0.65},{"uid":"702741c8-6f14-4f92-9e2c-195ede060535","title":"蓝田溪杂咏二十二首 远山钟","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["风送出山钟，云霞度水浅。","欲知声尽处，鸟灭寥天远。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":0.46},{"uid":"20dea002-e0ee-453b-89a0-f54b746aa435","title":"天星送杨凝郎中贺正","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天星牢落鸡喔咿，仆夫起餐车载脂。","正当穷冬寒未已，借问君子行安之。","会朝元正无不至，受命上宰须及期。","侍从近臣有虚位，公今此去归何时。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["星星"]},"theme_conf":0.745},{"uid":"cpa864df177f8250","title":"暗香","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["旧时月色。","算几番照我，梅边吹笛。","唤起玉人，不管清寒与攀摘。","何逊而今渐老，都忘却、春风词笔。","但怪得、竹外疏花，香冷入瑶席。","江国。","正寂寂。","叹寄与路遥，夜雪初积。","翠尊易泣。","红萼无言耿相忆。","长记曾携手处，千树压、西湖寒碧。","又片片、吹尽也，几时见得。"],"theme":"爱情相思","theme2":["送别"],"style":"幽峭","style2":["绮丽","婉约"],"mood":"孤寂","mood2":["悲怆"],"scene":["花","月"],"cats":{"山水":["西湖"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":0.604},{"uid":"4e89e730-74b8-4924-ae06-0d2f259c03be","title":"赠罗浮易炼师","author":"杨衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海上多仙峤，灵人信长生。","荣卫冰雪姿，咽嚼日月精。","默书绛符遍，晦步斗文成。","翠发披肩长，金盖凌风轻。","晓籁息尘响，天鸡叱幽声。","碧树来户阴，丹霞照窗明。","焚香叩虚寂，稽首回太清。","鸾鹭振羽仪，飞翻拂斾旌。","左挹玉泉液，右搴云芝英。","念得参龙驾，攀天度赤城。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","雪","月"],"cats":{"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.88},{"uid":"6d7b4fc4-62ae-48e7-a486-a8ff73caaf7d","title":"送日本国聘贺使晁巨卿东归","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上才生下国，东海是西邻。","九译蕃君使，千年圣主臣。","野情偏得礼，木性本含真。","锦帆乘风转，金装照地新。","孤城开蜃阁，晓日上朱轮。","早识来朝岁，涂山玉帛均。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","楼","山"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":0.745},{"uid":"f699ef22-319a-481b-8575-103300613ab9","title":"仆射来示有三春向晚四者难幷之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多过隙，新宴且寻盟。","鹦鹉林须乐，麒麟阁未成。","分阴当爱惜，迟景好逢迎。","林野熏风起，楼台谷雨晴。","墙低山半出，池广水初平。","桥转长虹曲，舟回小鹢轻。","残花犹布绣，密竹自闻笙。","欲过芳菲节，难忘宴慰情。","月轮行似箭，时物始如倾。","见雁随兄去，听莺求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虚丝管清。","峰峦侵碧落，草木近朱明。","与点非沂水，陪膺是洛城。","拨醅争绿醑，卧酪待朱樱。","几处能留客，何人唤解酲。","旧仪尊右揆，新命宠春卿。","有喜鹊频语，无机鸥不惊。","青林思小隐，白雪仰芳名。","访旧殊千里，登高赖九城。","酂侯司管钥，疏傅傲簪缨。","纶綍曾同掌，烟霄即上征。","册庭尝接武，书殿忝连衡。","兰室春弥馥，松心晚更贞。","琴招翠羽下，钩掣紫鳞呈。","只愿回乌景，谁能避兕觥。","方知醉兀兀，应是走营营。","凤阁鸾台路，从他年少争。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"2c152693-c25f-45ce-8ef2-cbedce1a62bc","title":"望月怀远","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["海上生明月，天涯共此时。","情人怨遥夜，竟夕起相思。","灭烛怜光满，披衣觉露滋。","不堪盈手赠，还寝梦佳期。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["爱情","思念","思乡"],"天气":["月亮"]},"theme_conf":0.377},{"uid":"cpd98ebb7b2c6b91","title":"蓦山溪","author":"曹组","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洗妆真态，不作铅华御。","竹外一枝斜，想佳人、天寒日暮。","黄昏小院，无处著清香，风细细，雪垂垂，何况江头路。","月边疏影，梦到消魂处。","结子欲黄时，又须著、廉纤细雨。","孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨","花","山","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"56f4eb52-4489-494d-a140-817d264544c8","title":"竹","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青林何森然，沈沈独曙前。","出墙同淅沥，开户满婵娟。","箨卷初呈粉，苔侵乱上钱。","疎中思水过，深处若山连。","叠夜常栖露，清朝乍有蝉。","砌阴迎缓策，簷翠对欹眠。","迸笋双分箭，繁梢一向偏。","月过惊散雪，风动极闻泉。","幽谷添诗谱，高人欲制篇。","萧萧意何恨，不独往湘川。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","雪","夜","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.757},{"uid":"b5afe65e-41f6-4c7a-8bc7-ff3f024937cb","title":"九日曲江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["缀席茱萸好，浮舟菡萏衰。","季秋时欲半，九日意兼悲。","江水清源曲，荆门此路疑。","晚来高兴尽，摇荡菊花期。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"0e2cf65b-d757-4698-97a0-31aedb02f4a3","title":"寒雨朝行视园树","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["柴门杂树向千株，丹橘黄甘此地无。","江上今朝寒雨歇，篱中秀色画屏纡。","桃蹊李径年虽故，栀子红椒艳复殊。","鏁石藤稍元自落，倚天松骨见来枯。","林香出实垂将尽，叶蔕辞枝不重苏。","爱日恩光蒙借贷，清霜杀气得忧虞。","衰颜更觅藜床坐，缓步仍须竹杖扶。","散骑未知云阁处，啼猨僻在楚山隅。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨","园林"],"cats":{"天气":["写雨"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"cp37eda4b1261602","title":"虞美人","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["曲阑干外天如水。","昨夜还曾倚。","初将明月比佳期。","长向月圆时候、望人归。","罗衣著破前香在。","旧意谁教改。","一春离恨懒调弦。","犹有两行闲泪、宝筝前。"],"theme":"爱情相思","theme2":["送别","闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.375},{"uid":"afa11a8c-8bce-408c-a688-2af0cc6632b5","title":"琴曲歌辞 胡笳十八拍 第八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔私家恣娇小，远取珍禽学驯扰。","如今沦弃念故乡，悔不当初放林表。","朔风萧萧寒日暮，星河寥落胡天晓。","旦夕思归不得归，愁心想似笼中鸟。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["冬"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["冬天"],"天气":["写风","星星"]},"theme_conf":0.446},{"uid":"7af5f435-0357-4ff6-ab62-97417d87a31a","title":"相和歌辞 日出行","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白日下崐崘，发光如舒丝。","徒照葵藿心，不照游子悲。","折折黄河曲，日从中央转。","旸谷耳曾闻，若木眼不见。","奈何铄石，胡为销人。","羿弯弓属矢那不中，足令久不得奔，讵教晨光夕昏。"],"theme":"边塞征战","theme2":["亲情"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":["江","夏"],"cats":{"抒情":["伤感"],"山水":["黄河"],"天气":["太阳"]},"theme_conf":0.6},{"uid":"b700208d-d859-4e36-96bf-883c81d4df0f","title":"谷口书斋寄杨补阙","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["泉壑带茅茨，云霞生薜帷。","竹怜新雨后，山爱夕阳时。","闲鹭栖常早，秋花落更迟。","家童扫萝迳，昨与故人期。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["山","秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.9},{"uid":"91e5ec11-b403-4ede-9d5b-c1854706739b","title":"山中横云","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["湘水风日满，楚山朝夕空。","连峰虽已见，犹念长云中。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":1.0},{"uid":"0b722208-9e02-4dac-9ec5-979859eea818","title":"正月三日归溪上有作简院内诸公","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野外堂依竹，篱边水向城。","蚁浮仍腊味，鸥泛已春声。","药许隣人㔉，书从稚子擎。","白头趋幕府，深觉负平生。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","园林","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.772},{"uid":"bb4a1d16-2a2e-4a68-9732-77e2bfafde5e","title":"奉酬北海李太守丈人夏日平阴亭","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天子股肱守，丈人山岳灵。","出身侍丹墀，举翮凌青冥。","当昔皇运否，人神俱未宁。","谏官莫敢议，酷吏方专刑。","谷永独言事，匡衡多引经。","两朝纳深衷，万乘无不听。","盛烈播南史，雄词豁东溟。","谁谓整隼旟，翻然忆柴扃。","寄书汶阳客，廻首平阴亭。","开封见千里，结念存百龄。","隐轸江山丽，氛氲兰茝馨。","自怜遇时休，漂泊随流萍。","春野变木德，夏天临火星。","一生徒羡鱼，四十犹聚萤。","从此日闲放，焉能怀拾青。"],"theme":"寄赠酬答","theme2":[],"style":"旷达","style2":["豪放"],"mood":"相思","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["思念","孤独"],"四季":["夏天"],"天气":["太阳"]},"theme_conf":0.76},{"uid":"df4bd05c-a0a4-4c19-8e8d-ada2db3ccbf2","title":"临邑舍弟书至苦雨黄河泛溢隄防之患簿领所忧因寄此诗用宽其意","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二仪积风雨，百谷漏波涛。","闻道洪何坼，遥连沧海高。","职思忧悄悄，郡国诉嗷嗷。","舍弟卑栖邑，防川领簿曹。","尺书前日至，版筑不时操。","难假鼋鼍力，空瞻乌鹊毛。","燕南吹畎亩，济上没蓬蒿。","螺蚌满近郭，蛟螭乘九臯。","徐关深水府，碣石小秋毫。","白屋留孤树，清天矢万艘。","吾衰同泛梗，利涉想蟠桃。","倚赖天涯钓，犹能掣巨鼇。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江"],"cats":{"山水":["黄河"],"天气":["写雨"]},"theme_conf":0.53},{"uid":"e5a97aba-72cd-4663-81fe-1f0af4375e15","title":"青云干吕","author":"林藻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["应节偏干吕，亭亭在紫氛。","缀空初布影，捧日已成文。","结盖祥光迥，为楼翠色分。","还同起封上，更似出横汾。","作瑞来藩国，呈形表圣君。","裴回如有托，谁道比闲云。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.58},{"uid":"a8133806-1aeb-44d9-8b5e-6309fe6bd8cb","title":"同吕员外酬田著作幕门军西宿盘山秋夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碛路天早秋，边城夜应永。","遥传戎旅作，已报关山冷。","上将顿盘阪，诸军徧泉井。","绸缪阃外书，慷慨幕中请。","能使勋业高，动令氛雾屏。","远途能自致，短步终难骋。","羽翮时一看，穷愁始三省。","人生感然诺，何啻若形影。","白发知苦心，阳春见佳境。","星河连塞络，刁斗兼山静。","忆君霜露时，使我空引领。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","夜","山","塞外"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.428},{"uid":"4d17d86c-b052-4a60-be76-3015ea8d1e8b","title":"怀素上人草书歌","author":"王𩔪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["衡阳双峡插天峻，青壁巉巉万余仞。","此中灵秀众所知，草书独有怀素奇。","怀素身长五尺四，嚼汤诵呪吁可畏。","铜瓶锡杖倚闲庭，斑管秋毫多逸意。","或粉壁，或彩牋，蒲葵绢素何相鲜。","忽作风驰如电掣，更点飞花兼散雪。","寒猨饮水撼枯藤，壮士拔山伸劲铁。","君不见张芝昔日称独贤，君不见近日张旭为老颠。","二公绝艺人所惜，怀素传之得真迹。","峥嵘蹙出海上山，突兀状成湖畔石。","一纵又一横，一欹又一倾。","临江不羡飞帆势，下笔长为骤雨声。","我牧此州喜相识，又见草书多慧力。","怀素怀素不可得，开卷临池转相忆。"],"theme":"题画咏艺","theme2":["爱情相思"],"style":"冲淡","style2":["幽峭"],"mood":"相思","mood2":["孤寂","慷慨"],"scene":["雪"],"cats":{"抒情":["思念","孤独"],"天气":["写雨"]},"theme_conf":0.98},{"uid":"cp34c072b90f0fae","title":"苏幕遮","author":"范仲淹","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧云天，黄叶地。","秋色连波，波上寒烟翠。","山映斜阳天接水。","芳草无情，更在斜阳外。","黯乡魂，追旅思。","夜夜除非，好梦留人睡。","明月楼高休独倚。","酒入愁肠，化作相思泪。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"沉郁","style2":["婉约"],"mood":"相思","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"天气":["月亮"]},"theme_conf":0.639},{"uid":"f540f519-e3c4-41c2-b299-f1d255977705","title":"宿府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清秋幕府井梧寒，独宿江城蜡炬残。","永夜角声悲自语，中天月色好谁看。","风尘荏苒音书绝，关塞萧条行路难。","已忍伶俜十年事，强移栖息一枝安。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["月","塞外"],"cats":{"抒情":["孤独"],"天气":["月亮"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"c5f83ccf-1f85-4b43-87e5-b24df8131f39","title":"横吹曲辞 白鼻䯄","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["银鞍白鼻䯄，绿地障泥锦。","细雨春风花落时，挥鞭且就胡姬饮。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":0.523},{"uid":"d06f921a-9125-4a21-aad1-f98a429e4727","title":"扬旗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江雨飒长夏，府中有余清。","我公会宾客，肃肃有异声。","初筵阅军装，罗列照广庭。","庭空六马入，𫘟騀扬旗旌。","回回偃飞盖，熠熠迸流星。","来缠风飙急，去擘山岳倾。","材归俯身尽，妙取略地平。","虹霓就掌握，舒卷随人轻。","三州陷犬戎，但见西岭青。","公来练猛士，欲夺天边城。","此堂不易升，庸蜀日已宁。","吾徒且加餐，休适蛮与荆。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":[],"mood":"相思","mood2":[],"scene":["山","夏","园林"],"cats":{"抒情":["思乡"],"四季":["夏天"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"93dc913e-1b3a-4406-90a7-d9f4149bc1ef","title":"端午日伏蒙内侍赐晨服","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩缕纤仍丽，凌风卷复开。","方应五日至，应自九天来。","在笥清光发，当轩暑气回。","遥知及时节，刀尺火云催。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.86},{"uid":"d12edd29-d467-4b19-b3f5-533fa5c8d56a","title":"秋夕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"7bdd44ad-6a7e-4c17-802a-c88127770ca2","title":"秋日台中寄怀简诸僚","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["宪府日多事，秋光照碧林。","干云岩翠合，布石地苔深。","忧悔耿遐抱，尘埃缁素襟。","物情牵跼促，友道旷招寻。","颓节风霜变，流年芳景侵。","池荷足幽气，烟竹又繁阴。","簪组赤墀恋，池鱼沧海心。","涤烦滞幽赏，永度瑶华音。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.9},{"uid":"fc1ccfae-5091-4e0a-9b84-2e2cdecd6f78","title":"虹藏不见","author":"徐敞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迎冬小雪至，应节晚虹藏。","玉气徒成象，星精不散光。","美人初比色，飞鸟罢呈祥。","石涧收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎残阳。","舒卷应时令，因知圣历长。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["雨","冬","雪"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.96},{"uid":"aac265f0-080e-4861-8308-80d102a6c63d","title":"承沈八丈东美除膳部员外阻雨未遂驰贺奉寄此诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今日西京掾，多除内省郎。","通家惟沈氏，谒帝似冯唐。","诗律群公问，儒门旧史长。","清秋便寓直，列宿顿辉光。","未暇申宴慰，含情空激扬。","司存何所比，膳部默凄伤。","贫贱人事略，经过霖潦妨。","礼同诸父长，恩岂布衣忘。","天路牵骐骥，云台引栋梁。","徒怀贡公喜，飒飒鬓毛苍。"],"theme":"应制干谒","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":0.95},{"uid":"b15a6f1f-1730-49e2-8f50-a0a5f7e51e26","title":"松滋江北阻风","author":"阎宽","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江风久未歇，山雨复相仍。","巨浪天涯起，余寒川上凝。","忧人劳夕惕，乡事惫晨兴。","远听知音骇，诚哉不可陵。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["友情","思乡"],"山水":["江河"],"天气":["写风"]},"theme_conf":0.534},{"uid":"fe939b59-a6d6-4460-b5d6-aa2f66de38c1","title":"登白云亭","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["出门见南山，喜逐松径行。","穷高欲极远，始到白云亭。","长山绕井邑，登望宜新晴。","州渚曲湘水，萦回随郡城。","九疑千万峰，嵺嵺天外青。","烟云无远近，皆傍林岭生。","俯视松竹间，石水何幽清。","涵映满轩户，娟娟如镜明。","何人病惛浓，积醉且未醒。","与我一登临，为君安性情。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["山","楼"],"cats":{"天气":["写云"]},"theme_conf":0.587},{"uid":"cp841ff9b4d78bde","title":"湘春夜月","author":"黄孝迈","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近清明。","翠禽枝上消魂。","可惜一片清歌，都付与黄昏。","欲共柳花低诉，怕柳花轻薄，不解伤春。","念楚乡旅宿，柔情别绪，谁与温存。","空樽夜泣，青山不语，残月当门。","翠玉楼前，惟是有、一波湘水，摇荡湘云。","天长梦短，问甚时、重见桃根。","这次第，算人间没个并刀，翦断心上愁痕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["悲怆","相思"],"scene":["夜","春","月"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.477},{"uid":"194a53e4-d7f8-49a6-92eb-3e36d41fd32c","title":"汨罗遇风","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["南来不作楚臣悲，重入修门自有期。","为报春风汨罗道，莫将波浪枉明时。"],"theme":"羁旅思乡","theme2":["民生疾苦"],"style":"悲慨","style2":["绮丽"],"mood":"慷慨","mood2":["悲怆"],"scene":["端午"],"cats":{"抒情":["思乡","伤感"],"天气":["写风"],"节日":["端午节"]},"theme_conf":0.588},{"uid":"80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd","title":"和武相公中秋锦楼玩月 二","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四时皆有月，一夜独当秋。","照耀初含露，裴回正满楼。","遥连雪山净，逈入锦江流。","愿以清光末，年年许从游。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"theme":"咏史怀古","theme2":["哲理悟道","边塞征战","羁旅思乡"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["秋","江"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.242},{"uid":"3e4849dc-c411-49fa-8664-20a58b0493fd","title":"题郎士元半日吴村别业兼呈李长官","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["半日吴村带晚霞，闲门高柳乱飞鵶。","横云岭外千重树，流水声中一两家。","愁人昨夜相思苦，闰月今年春意赊。","自叹梅生头似雪，却怜潘令县如花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思念","伤感"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.373},{"uid":"a7f9cfd6-7f54-4737-9d0d-ada81cb18e68","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白虹见，昼（川本作「尽」）见地侵（辛本、川本作「青」）天。","其地一方皆主乱，众人喧闹有灾缠，年内应其占。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"1d7c2618-c8d8-4ff5-a7b6-88ffb05263fe","title":"雨中寒食","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["令节逢烟雨，园亭但掩关。","佳人宿妆薄，芳树彩绳闲。","归思偏消酒，春寒为近山。","花枝不可见，别恨灞陵间。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["清明","雨"],"cats":{"天气":["写雨"],"人物":["女子"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"4941ee70-92db-47bc-87d7-ba11b212025f","title":"苦雪四首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["惠连发清兴，袁安念高卧。","余故非斯人，为性兼懒惰。","赖兹尊中酒，终日聊自过。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"]},"theme_conf":0.65},{"uid":"333b66bc-2738-4424-aaf9-c8834be7fabe","title":"琴曲歌辞 风入松歌","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西岭松声落日秋，千枝万叶风飕飗。","美人援琴弄成曲，写得松间声断续。","声断续，清我魂，流波坏陵安足论。","美人夜坐月明里，含少商兮照清征。","风何凄兮飘飉，搅寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["夜","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.565},{"uid":"246d388f-1a6f-4b5d-a153-617a64578503","title":"和李中丞詶万年房署少府过汾州景云观因以寄上房与李早年同居此观","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["显晦澹无迹，贤哉常晏如。","如何警孤鹤，忽乃传双鱼。","叙以泉石旧，怅然风景余。","低回青油幕，梦寐白云居。","玉洞桂香满，雪坛松影疎。","沈思瞩仙侣，纾组正军书。","积学早成道，感恩难遂初。","梅生谅多感，归止岂吾庐。"],"theme":"寄赠酬答","theme2":["山水田园","应制干谒","咏史怀古"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","孤寂"],"scene":["冬","雪"],"cats":{"抒情":["孤独","怀古","感恩"],"天气":["写云"]},"theme_conf":0.88},{"uid":"757a180d-55eb-4931-9f10-c71649f6a06d","title":"秋日过鸿举法师寺院便送归江陵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["看画长廊遍，寻僧一径幽。","小池兼鹤净，古木带蝉秋。","客至茶烟起，禽归讲席收。","浮杯明日去，相望水悠悠。"],"theme":"送别","theme2":["咏史怀古","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"动物":["写鸟"]},"theme_conf":0.28},{"uid":"f8c0f02f-21d3-4bce-acb9-eff80ce4f0c0","title":"新楼诗二十首","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿波春水湖光满，丹槛连楹碧嶂遥。","兰鹢对飞渔棹急，彩虹翻影海旗摇。","鬬疑斑虎归三岛，散作游龙上九霄。","鼍鼓若雷争胜负，柳堤花岸万人招。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春"],"cats":{"四季":["春天"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"cp1ed0c38b00fc04","title":"声声慢","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寻寻觅觅，冷冷清清，凄凄惨惨戚戚。","乍暖还寒时候，最难将息。","三杯两盏淡酒，怎敌他、晚来风急。","雁过也，正伤心，却是旧时相识。","满地黄花堆积。","憔悴损，如今有谁摘。","守著窗儿，独自怎生得黑。","梧桐更兼细雨，到黄昏、点点滴滴。","这次第，怎一个、愁字了得。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","酒","夜"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.62},{"uid":"9c725632-fe02-4fc7-b443-9410da36c7e5","title":"秋雨叹三首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安布衣谁比数，反鏁衡门守环堵。","老夫不出长蓬蒿，穉子无忧走（一作「奏」）风雨。","雨声飕飕催早寒，胡雁翅湿高飞难。","秋来未曾（一作「省」）见白日，埿污后（一作「厚」）土何时干？"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","秋"],"cats":{"四季":["秋天"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"6c18667b-708f-4a2a-9c20-d4a104e36904","title":"春雪题兴善寺广宣上人竹院","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎洁青莲客，焚香对雪朝。","竹风催淅沥，花雨让飘飖。","触石和云积，萦池拂水消。","只应将日月，颜色不相饶。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","园林","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["竹子"]},"theme_conf":0.535},{"uid":"6629f32a-e163-4400-8684-a459c3b6bb52","title":"送崔秀才赴上元兼省叔父","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒塘敛暮雪，腊鼓迎春早。","匹马五城人，重裘千里道。","淮山轻露湿，江树狂风扫。","楚县久酝𬪩，扬州百花好。","练湖东望接云阳，女市西游入建康。","行乐远夸红布旆，风流近赌紫香囊。","诗家行辈如君少，极目苦心怀谢朓。","烟开日上板桥南，吴岫青青出林表。"],"theme":"送别","theme2":["节令风俗"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","山"],"cats":{"天气":["写风"],"人物":["父亲"],"生活":["写桥"],"节日":["元宵节"]},"theme_conf":0.49},{"uid":"529cf938-bb80-4453-b73f-7425d18396e4","title":"杂曲歌辞 长干行二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["忆妾深闺里，烟尘不曾识。","嫁与长干人，沙头候风色。","五月南风兴，思君在巴陵。","八月西风起，想君发扬子。","去来悲如何，见少别离多。","湘潭几日到，妾梦越风波。","昨夜狂风度，吹折江头树。","淼淼暗无边，行人在何处？","北客真王公，朱衣满江中。","日暮来投宿，数朝不肎东。","好乘浮云骢，佳期兰渚东。","鸳鸯绿浦上，翡翠锦屏中。","自怜十五余，颜色桃李红。","那作商人妇，愁水复愁风。"],"theme":"闺情宫怨","theme2":["送别","爱情相思","羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":["愁怨","悲怆"],"scene":["江","月"],"cats":{"抒情":["爱情","离别","思念","思乡","伤感","闺怨"],"天气":["写风"]},"theme_conf":0.85},{"uid":"c4d9440e-b2d8-4c43-930b-ba0c5dd68548","title":"将晓二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石城除击柝，铁锁欲开关。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使动无还。","垂老孤帆色，飘飘犯百蛮。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["沉郁","悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["塞外","舟","山"],"cats":{"抒情":["伤感","孤独"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.683},{"uid":"17c35064-6bb1-4b91-a555-c2ae3768ec7c","title":"雨二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青山澹无姿，白露谁能数。","片片水上云，萧萧沙中雨。","殊俗状巢居，曾台俯风渚。","佳客适万里，沈思情延伫。","挂帆远色外，惊浪满吴楚。","久阴蛟螭出，寇盗复几许。"],"theme":"羁旅思乡","theme2":["羁旅思乡","山水田园"],"style":"冲淡","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"]},"theme_conf":0.63},{"uid":"cb55e33f-ee4d-4b88-a23f-280fd0cfd271","title":"杂曲歌辞 春日行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["深宫高楼入紫清，金作蛟龙盘绣楹。","佳人当窗弄白日，弦将手语弹鸣筝。","春风吹落君王耳，此曲乃是升天行。","因出天池泛蓬瀛，楼船蹙沓波浪惊。","三千双蛾献歌笑，挝钟考鼓宫殿倾。","万姓聚舞歌太平，我无为，人自宁。","三十六帝欲相迎，仙人飘翩下云𫐌。","帝不去，留镐京。","安能为轩辕，独往入窅冥。","小臣拜献南山寿，陛下万古垂鸿名。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["太阳"],"人物":["女子"]},"theme_conf":0.65},{"uid":"2049c49c-8641-4e79-9342-992de31f2a5e","title":"酬普选二上人期相会见寄","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["本意宿东林，因听子贱琴。","遥知大小朗，已断去来心。","夜静溪声近，庭寒月色深。","宁知尘外意，定后便成吟。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"山水":["庐山"],"天气":["月亮"]},"theme_conf":0.85},{"uid":"f45104c8-145d-4f09-ac5d-1b9ac85dad65","title":"人日两篇 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["元日到人日，未有不阴时。","冰雪莺难至，春寒花较迟。","云随白水落，风振紫山悲。","蓬鬓稀疎久，无劳比素丝。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","雪","冬"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.58},{"uid":"1f2a429b-3f66-4400-91f6-52321af3e9ae","title":"吟元郎中白须诗兼饮雪水茶因题壁上","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["吟咏霜毛句，闲尝雪水茶。","城中展眉处，只是有元家。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"],"食物":["写茶"]},"theme_conf":0.64},{"uid":"2e2f3d54-351b-455a-8dbb-c4aada51996b","title":"日暮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日落风亦起，城头鸟尾讹。","黄云高未动，白水已扬波。","羌妇语还哭，胡儿行且歌。","将军别换马，夜出拥雕戈。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"天气":["太阳"]},"theme_conf":0.8},{"uid":"8b5741ba-0a9b-4a04-9ea8-fed55e797055","title":"和令狐相公九日对黄白二菊花见怀","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["素萼迎寒秀，金英带露香。","繁华照旄钺，荣盛对银黄。","琮璧交辉映，衣裳杂彩章。","晴云遥盖覆，秋蝶近悠扬。","空想逢九日，何由陪一觞。","满丛佳色在，未肯委严霜。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":[],"scene":["重阳","花"],"cats":{"四季":["秋天"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"80b59d90-c62e-4269-8883-3b625cd91ba7","title":"至日遣兴奉寄北省旧阁老两院故人二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昨逍遥供奉班，去年今日侍龙颜。","麒麟不动炉烟上，孔雀徐开扇影还。","玉几由来天北极，朱衣只在殿中间。","孤城此日堪肠断，愁对寒云雪满山。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["楼","园林","冬","雪"],"cats":{"抒情":["友情","伤感","孤独"],"天气":["太阳"]},"theme_conf":0.94},{"uid":"fe6b1d10-773b-41cc-ba18-6cf545884231","title":"对雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北雪犯长沙，胡云冷万家。","随风且间叶，带雨不成花。","金错囊从罄，银壶酒易赊。","无人竭浮蚁，有待至昏鸦。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"da0befbd-3655-4d16-8413-0d699c88e75c","title":"雨二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["空山中宵阴，微冷先枕席。","回风起清曙，万象萋已碧。","落落出岫云，浑浑倚天石。","日假何道行，雨含长江白。","连樯荆州船，有士荷矛戟。","南防草镇惨，沾湿赴远役。","群盗下辟山，总戎备强敌。","水深云光廓，鸣橹各有适。","渔艇息悠悠，夷歌负樵客。","留滞一老翁，书时记朝夕。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新","幽峭"],"mood":"恬淡","mood2":[],"scene":["江","雨","山","舟"],"cats":{"山水":["长江"],"天气":["写雨"]},"theme_conf":0.675},{"uid":"6382d668-2787-4a30-b0f2-c58a3b3b9f25","title":"相和歌辞 从军行","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["向夕临大荒，朔风轸归虑。","平沙万里余，飞鸟宿何处？","虏骑猎长原，翩翩傍河去。","边声摇白草，海气生黄雾。","百战苦风尘，十年履霜露。","虽投定远笔，未坐将军树。","早知行路难，悔不理章句。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["写风"],"人生":["战争"]},"theme_conf":0.854},{"uid":"d66f1624-d12b-41ca-b51d-b90d430bf734","title":"滕王亭子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞春山路，君王不复行。","古墙犹竹色，虚阁自松声。","鸟雀荒村暮，云霞过客情。","尚思歌吹入，千骑把霓旌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":1.0},{"uid":"46013ebf-55a5-421e-a8fb-c1d55a3c67b3","title":"壮游","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往昔十四五，出游翰墨场。","斯文崔魏徒，以我似班扬。","七龄思即壮，开口咏凤皇。","九龄书大字，有作成一囊。","性豪业嗜酒，嫉恶怀刚肠。","脱略小时辈，结交皆老苍。","饮酣视八极，俗物都茫茫。","东下姑苏台，已具浮海航。","到今有遗恨，不得穷扶桑。","王谢风流远，阖庐丘墓荒。","劒池石壁仄，长洲荷芰香。","嵯峨阊门北，清庙映回塘。","每趋吴太伯，抚事泪浪浪。","枕戈忆句践，渡浙想秦皇。","蒸鱼闻匕首，除道哂要章。","越女天下白，鉴湖五月凉。","剡溪蕴秀异，欲罢不能忘。","归帆拂天姥，中岁贡旧乡。","气劘屈贾垒，目短曹刘墙。","忤下考功第，独辞京尹堂。","放荡齐赵间，裘马颇清狂。","春歌丛台上，冬猎青丘旁。","呼鹰皂枥林，逐兽云雪冈。","射飞曾纵鞚，引臂落鹙鸧。","苏侯据鞍喜，忽如携葛强。","快意八九年，西归到咸阳。","许与必词伯，赏游实贤王。","曳裾置醴地，奏赋入明光。","天子废食召，群公会轩裳。","脱身无所爱，痛饮信行藏。","黑貂不免敝，斑鬓兀称觞。","杜曲晚耆旧，四郊多白杨。","坐深乡党敬，日觉死生忙。","朱门任倾夺，赤族迭罹殃。","国马竭粟豆，官鸡输稻粱。","举隅见烦费，引古惜兴亡。","河朔风尘起，岷山行幸长。","两宫各警跸，万里遥相望。","崆峒杀气黑，少海旌旗黄。","禹功亦命子，涿鹿亲戎行。","翠华拥英岳，螭虎噉豺狼。","爪牙一不中，胡兵更陆梁。","大军载草草，凋瘵满膏肓。","备员窃补衮，忧愤心飞扬。","上感九庙焚，下悯万民疮。","斯时伏青蒲，延争守御床。","君辱敢爱死，赫怒幸无伤。","圣哲体仁恕，宇县复小康。","哭庙灰烬中，鼻酸朝未央。","小臣议论绝，老病客殊方。","郁郁苦不展，羽翮困低昂。","秋风动哀壑，碧蕙捐微芳。","之推避赏从，渔父濯沧浪。","荣华敌勋业，岁暮有严霜。","吾观鸱夷子，才格出寻常。","群凶逆未定，侧伫英俊翔。"],"theme":"咏怀抒感","theme2":["咏史怀古","边塞征战","悼亡挽歌"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["悲怆","慷慨"],"scene":["冬","江南","酒","山","秋"],"cats":{"抒情":["伤感","悼亡","怀古"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.85},{"uid":"c620865d-0ff1-4861-9847-114e33be2f18","title":"青云干吕 一","author":"彭伉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["祥辉上干吕，郁郁又纷纷。","远示无为化，将明至道君。","势凝千里静，色向九霄分。","已见从龙意，宁知触石文。","状烟殊散漫，捧日更氛氲。","自使来宾国，西瞻仰瑞云。"],"theme":"应制干谒","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":[],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"8522b687-c845-4d15-9e44-b60c3df77707","title":"元日喜闻大礼寄上翰林四学士中书六舍人二十韵","author":"窦牟","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有事郊坛毕，无私日月临。","岁华春更早，天瑞雪犹深。","玉辇回时令，金门降德音。","翰飞鸳别侣，藂植桂为林。","粉泽资鸿笔，薰和本素琴。","礼成戎器下，恩彻鬼方沈。","麟爵来称纪，官师退绝箴。","道风黄阁静，祥景紫垣阴。","寿酒朝时献，农书夜直寻。","国香煴翠幄，庭燎赩红衾。","汉魏文章盛，尧汤雨露霃。","密辞投水石，精义出沙金。","宸扆亲唯敬，钧衡近匪侵。","疾驱千里骏，清唳九霄禽。","庆赐迎新服，斋庄弃旧簪。","忽思班女怨，遥听越人吟。","末路甘贫病，流年苦滞淫。","梦中青琐闼，归处碧山岑。","窃抃闻韶濩，观光想韎任。","大哉环海晏，不笇子牟心。"],"theme":"应制干谒","theme2":["送别","山水田园"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"愁怨","mood2":["欢愉","相思"],"scene":["雪","月","夜","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.86},{"uid":"0a9b2767-706e-40b9-a423-2097e5f97d10","title":"避暑摩诃池上作","author":"后蜀嗣主孟昶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["冰肌玉骨清无汗，水殿风来暗香暖。","帘开明月独窥人，敧枕钗横云鬓乱。","起来琼户寂无声，时见疎星渡河汉。","屈指西风几时来，只恐流年暗中换。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月","园林"],"cats":{"抒情":["孤独","闺怨"],"四季":["夏天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":1.0},{"uid":"beee5922-6237-4c9a-af25-43a4cb4274e6","title":"送从弟永任饶州录事参军","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一官万里向千溪，水宿山行鱼浦西。","日晚长烟高岸近，天寒积雪远峰低。","芦花渚里鸿相呌，苦竹丛边猨暗啼。","闻道慈亲倚门待，到时兰叶正萋萋。"],"theme":"送别","theme2":["边塞征战","山水田园"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山","雪"],"cats":{"天气":["写雪"],"人物":["母亲"]},"theme_conf":0.403},{"uid":"80a539fd-75f1-4590-83b2-5c7bf5c0c34c","title":"使青夷军入居庸三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古镇青山口，寒风落日时。","岩峦鸟不过，冰雪马堪迟。","出塞应无策，还家赖有期。","东山足松桂，归去结茅茨。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山","冬","塞外","雪"],"cats":{"天气":["写雪"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"ad472842-1792-451c-826d-311acb8d8b21","title":"和宋中丞夏日游福贤观天长寺寺即陈左相宅所施之作","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["已相殷王国，空余尚父谿。","钓矶开月殿，筑道出云梯。","积水浮香象，深山鸣白鸡。","虚空陈伎乐，衣服制虹霓。","墨点三千界，丹飞六一泥。","桃源勿遽返，再访恐君迷。"],"theme":"山水田园","theme2":["哲理悟道","应制干谒"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["彩虹"]},"theme_conf":0.447},{"uid":"098ed74c-c5fa-4944-9078-b76bd958fbba","title":"春日忆家","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自觉劳乡梦，无人见客心。","空余庭草色，日日伴愁襟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感","孤独"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"12f2af31-9401-4281-a410-55843039d6b1","title":"八月十五日夜桃源玩月","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["尘中见月心亦闲，况是清秋仙府间。","凝光悠悠寒露坠，此时立在最高山。","碧虚无云风不起，山上长松山下水。","群动翛然一顾中，天高地平千万里。","少君引我升玉坛，礼空遥请真仙官。","云𫐌欲下星斗动，天乐一声肌骨寒。","金霞昕昕渐东上，轮欹影促犹频望。","绝景良时难再幷，他年此日应惆怅。"],"theme":"山水田园","theme2":["节令风俗","游仙梦幻"],"style":"绮丽","style2":["豪放","清新"],"mood":"惆怅","mood2":["孤寂","恬淡"],"scene":["月","中秋","夜"],"cats":{"天气":["太阳","月亮"],"节日":["中秋节"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"3db87bc4-ae57-42bb-8741-bb8c8a8499ee","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 二","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兵行次，虹贯日（京本作「路」）边傍。","御（京本作「预」）备伏兵前有阻，且须审细自（京本作「更」）商量，移寨避灾殃（辛本、川本、京本作「终不得开疆」）。","。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"c5b30b4f-a9d1-4c84-8cd9-fdf6a29b7e86","title":"雪谤后书事上皇甫大夫","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["盛德总群英，高标仰国桢。","独安巡狩日，曾掩赵张名。","业就难辞宠，朝回更授兵。","晓川分牧马，夜雪覆连营。","长策威殊俗，嘉谋翊圣明。","画图规阵势，梦笔纪山行。","绶拂池中影，珂摇竹外声。","赐欢征妓乐，陪醉问公卿。","却忆经前事，翻疑得此生。","分深存没感，恩在子孙荣。","览镜愁将老，扪心喜复惊。","岂言沈族重，但觉杀身轻。","有泪沾坟典，无家集弟兄。","东西遭世难，流浪识交情。","阅古宗文举，推才慕正平。","应怜守贫贱，又欲事躬耕。"],"theme":"讽喻刺世","theme2":["山水田园","悼亡挽歌"],"style":"沉郁","style2":["婉约","豪放"],"mood":"欢愉","mood2":["愁怨"],"scene":["雪"],"cats":{"抒情":["伤感","悼亡","感恩"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.436},{"uid":"a05bf553-aa6e-49b8-8988-a104d0207473","title":"杂歌谣辞 古歌","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["落叶流风向玉台，夜寒秋思洞房开。","水精帘外金波下，云母窗前银汉回。","玉阶阴阴苔藓色，君王履綦难再得。","璇闺窈窕秋夜长，绣户徘徊秋月光。","燕姬彩帐芙蓉色，秦子金炉兰麝香。","北斗七星横夜半，清歌一曲断君肠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"8981911c-da27-4a25-bffb-a8cc1aa7cdfa","title":"舞曲歌辞 独漉篇","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["独漉水中泥，水浊不见月。","不见月尚可，水深行人没。","越鸟从南来，胡鹰亦北度。","我欲弯弓向天射，惜其中道失归路。","落叶别树，飘零随风。","客无所托，悲与此同。","罗帷舒卷，似有人开。","明月直入，无心可猜。","雄劒挂壁，时时龙鸣。","不断犀象，绣涩苔生。","国耻未雪，何由成名。","神鹰梦泽，不顾鸱鸢。","为君一击，抟鹏九天。"],"theme":"边塞征战","theme2":["羁旅思乡","送别"],"style":"悲慨","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"d1c092e6-cdc6-43e3-a7cd-54397c4f31dd","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["峡云行清晓，烟雾相裴回。","风吹苍江树，雨洒石壁来。","凄凄生余寒，殷殷兼出雷。","白谷变气候，朱炎安在哉？","高鸟湿不下，居人门未开。","楚宫久已灭，幽佩为谁哀。","侍臣书王梦，赋有冠古才。","冥冥翠龙驾，多自巫山台。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"]},"theme_conf":0.553},{"uid":"c51ebd5d-f16d-4042-963f-b1ff984d8689","title":"忆长安 七月","author":"陈元初","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，七月时，槐花点散罘罳。","七夕针楼竞出，中元香供初移。","绣毂金鞍无限，游人处处归迟。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","七夕"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"5197293d-6d7e-48f7-9387-f992e9c3a2ee","title":"七月十五日题章敬寺","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["招提迩皇邑，复道连重城。","法筵会早秋，驾言访禅扃。","尝闻大仙教，清净宗无生。","七物匪吾宝，万行先求成。","名相既双寂，繁华奚所荣。","金风扇微凉，远烟凝翠晶。","松院静苔色，竹房深磬声。","境幽真虑恬，道胜外物轻。","意适本非说，含毫空复情。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"1c0d2513-d896-4ce1-a06d-8810f696e545","title":"雨过山村","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雨里鸡鸣一两家，竹溪村路板桥斜。","妇姑相唤浴蚕去，闲看中庭栀子花。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["乡村","写桥"]},"theme_conf":0.615},{"uid":"b19965c5-9574-43ff-9158-2f61b6a3fde7","title":"酬王季友题半日村别业兼呈李明府","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["村映寒原日已斜，烟生密竹早归鸦。","长溪南路当群岫，半景东隣照数家。","门通小径连芳草，马饮春泉踏浅沙。","欲待主人林上月，还思潘岳县中花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","花"],"cats":{"抒情":["友情","离别"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.49},{"uid":"00f12a19-bb96-4980-a4f5-11a1b9d604dd","title":"山居秋暝","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["空山新雨后，天气晚来秋。","明月松间照，清泉石上流。","竹喧归浣女，莲动下渔舟。","随意春芳歇，王孙自可留。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"3a06af16-eafc-421a-b261-97245ef0dbf5","title":"九日蓝田崔氏庄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["老去悲秋强自宽，兴来今日尽君欢。","羞将短发还吹帽，笑倩旁人为正冠。","蓝水远从千涧落，玉山高并两峰寒。","明年此会知谁健，醉把茱萸子细看。"],"theme":"节令风俗","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"82821220-44e6-465e-ae73-68f04886604a","title":"琴曲歌辞 白雪歌","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["列鼎佩金章，泪眼看风枝。","却思食藜藿，身作屠沽儿。","负米无远近，所希升斗归。","为人无贵贱，莫学鸡狗肥。","斯言如不忘，别更无光辉。","斯言如或忘，即安用人为。"],"theme":"讽喻刺世","theme2":["送别"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.72},{"uid":"3bb3897a-7460-40d1-9ec3-b4738e3f20b4","title":"忆春日太液池亭候对","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宫莺报晓瑞烟开，三岛灵禽拂水回。","桥转彩虹当绮殿，舰浮花鹢近蓬莱。","草承香辇王孙长，桃艳仙颜阿母栽。","簪笔此时方侍从，却思金马笑邹枚。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["彩虹"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"a2db743e-ffb6-4ad8-8afe-87d0b5a79633","title":"元日早朝呈故省诸公","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万戟凌霜布，森森瑞气间。","垂衣当晓日，上寿对南山。","济济延多士，跹跹舞百蛮。","小臣无事谏，空愧伴鸣环。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.95},{"uid":"59c7eaa9-3c05-4857-8cff-10376706ccb9","title":"月夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今夜鄜州月，闺中只独看。","遥怜小儿女，未解忆长安。","香雾云鬟湿，清辉玉臂寒。","何时倚虚幌，双照泪痕干。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月"],"cats":{"抒情":["思念","孤独","闺怨"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.705},{"uid":"cp7622937b715c55","title":"渡江云三犯・渡江云","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["羞红颦浅恨，晚风为落，片绣点重茵。","旧堤分燕尾，桂棹轻鸥，宝勒倚残云。","千丝怨碧，渐路入、仙坞迷津。","肠漫回，隔花时见，背面楚腰身。","逡巡。","题门惆怅，堕履牵萦，数幽期难准。","还始觉、留情缘眼，宽带因春。","明朝事与孤烟冷，做满湖、风雨愁人。","山黛暝，尘波澹绿无痕。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","雨"],"cats":{"抒情":["伤感","闺怨"],"天气":["写云"]},"theme_conf":0.522},{"uid":"cpbf70c4f59e5765","title":"雨霖铃","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寒蝉凄切。","对长亭晚，骤雨初歇。","都门帐饮无绪，留恋处、兰舟催发。","执手相看泪眼，竟无语凝噎。","念去去、千里烟波，暮霭沈沈楚天阔。","多情自古伤离别。","更那堪、冷落清秋节。","今宵酒醒何处，杨柳岸、晓风残月。","此去经年，应是良辰、好景虚设。","便纵有、千种风情，更与何人说。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","清新"],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["离别","伤感"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"8f179f71-6bfa-4329-9340-2aa81745b2c6","title":"月晦","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晦魄移中律，凝暄起丽城。","罩云朝盖上，穿露晓珠呈。","笑树花分色，啼枝鸟合声。","披襟欢眺望，极目畅春情。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["月","春"],"cats":{"四季":["春天"],"天气":["月亮"]},"theme_conf":0.72},{"uid":"883fcd05-a7b4-40f8-8cbe-5d93d4fad76c","title":"冬日洛城北谒玄元皇帝庙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["配极玄都閟，凭虚禁御长。","守祧严具礼，掌节镇非常。","碧瓦初寒外，金茎一气旁。","山河扶绣户，日月近雕梁。","仙李盘根大，猗兰奕叶光。","世家遗旧史，道德付今王。","画手看前辈，吴生远擅场。","森罗移地轴，妙绝动宫墙。","五圣联龙衮，千官列雁行。","冕旒俱秀发，旌斾尽飞扬。","翠柏深留景，红棃迥得霜。","风筝吹玉柱，露井冻银床。","身退卑周室，经传拱汉皇。","谷神如不死，养拙更何乡。"],"theme":"佛道禅颂","theme2":["咏史怀古","民生疾苦","应制干谒"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["怀古"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.9},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"8aa34b2b-7216-41a4-8453-892834425b91","title":"登秦岭作时陷贼归国","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝出猛兽林，躨跜登高峰。","僮仆履云雾，随我行太空。","羲和舒灵晖，倏忽西极通。","回首望泾渭，隐隐如长虹。","九逵合苍芜，五陵遥瞳蒙。","鹿游大明殿，雾湿华清宫。","网罗蠛蠓时，顾齿熊罴锋。","失途走江汉，不能有其功。","气逐招遥星，魂随阊阖风。","惟言宇宙清，复使车书同。","林木被繁霜，合沓连山红。","鹏鹗励羽翼，俯视荆棘丛。","誓将食鸧鸮，然后归崆峒。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"天气":["彩虹"]},"theme_conf":0.466},{"uid":"cp63eba452c87667","title":"风入松","author":"俞国宝","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一春长费买花钱。","日日醉花边。","玉骢惯识西湖路，骄嘶过、沽酒垆前。","红杏香中箫鼓，绿杨影里秋千。","暖风十里丽人天。","花压髻云偏。","画船载取春归去，馀情寄、湖水湖烟。","明日重扶残醉，来寻陌上花钿。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","花","春","江南"],"cats":{"四季":["春天"],"山水":["西湖"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.393},{"uid":"8d210949-8fc9-490f-b130-12b2cbeb3243","title":"题嵩阳焦道士石壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["三峰花畔碧堂悬，锦里真人此得仙。","玉体才飞西蜀雨，霓裳欲向大罗天。","彩云不散烧丹灶，白鹿时藏种玉田。","幸入桃源因去世，方期丹诀一延年。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","山"],"cats":{"天气":["写云"]},"theme_conf":1.0},{"uid":"98cf143d-0917-47aa-8a24-ce3db79ce765","title":"赋得春雪映早梅","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞舞先春雪，因依上番梅。","一枝方渐秀，六出已同开。","积素光逾密，真花节暗催。","抟风飘不散，见𬀪忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝两成咏，翻挟昔人才。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["雪","冬","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.796},{"uid":"cpffa9ae8e43982f","title":"法曲献仙音","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["层绿峨峨，纤琼皎皎，倒压波痕清浅。","过眼年华，动人幽意，相逢几番春换。","记唤酒寻芳处，盈盈褪妆晚。","已销黯。","况凄凉、近来离思，应忘却、明月夜深归辇。","荏苒一枝春，恨东风、人似天远。","纵有残花，洒征衣、铅泪都满。","但殷勤折取，自遣一襟幽怨。"],"theme":"咏物","theme2":["游仙梦幻"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["春","月","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.8},{"uid":"4b20b87c-18e6-4769-b07e-72665771fd11","title":"相和歌辞 饮马长城窟行","author":"袁朗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动秋草，清跸长安道。","长城连不穷，所以隔华戎。","规模惟圣作，荷负晓成功。","鸟庭已向内，龙荒更凿空。","玉关尘卷静，金微路已通。","汤征随北怨，舜咏起南风。","画野功初立，绥边事云集。","朝服践狼居，凯歌旋马邑。","山响传凤吹，霜华藻琼钑。","属国拥节归，单于款关入。","日落寒云起，惊沙被原隰。","零落叶已寒，河流清且急。","四时徭役尽，千载干戈戢。","太平今若斯，汗马竟无施。","惟当事笔研，归去草封禅。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.522},{"uid":"918eefe5-fd66-441d-ac06-01ad799fb485","title":"绛州过夏留献郑尚书","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝朝沈醉引金船，不觉西风满树蝉。","光景暗消银烛下，梦魂长寄玉轮边。","因循每被时流诮，奋发须由国士怜。","明月客肠何处断，绿槐风里独扬鞭。"],"theme":"应制干谒","theme2":["应制干谒","送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月"],"cats":{"抒情":["思乡","孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["励志"]},"theme_conf":0.95},{"uid":"a3ed689f-6083-4041-b4d2-8f294506ee0c","title":"送冷朝阳还上元","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青丝䋏引木兰船，名遂身归拜庆年。","落日澄江乌榜外，秋风疎柳白门前。","桥通小市家林近，山带平湖野寺连。","别后依依寒食里，共君携手在东田。"],"theme":"送别","theme2":["节令风俗"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"生活":["写桥"],"节日":["元宵节","寒食节"]},"theme_conf":0.524},{"uid":"26812d7f-e7f0-4936-be69-3dc2cf0bc0c8","title":"和武相公中秋锦楼玩月 一","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清景同千里，寒光尽一年。","竟天多鴈过，通夕少人眠。","照别江楼上，添愁野帐前。","隋侯恩未报，犹有夜珠圆。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","楼","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"e961ac8e-2de7-4ba1-a5a4-e1b810809edf","title":"片玉篇","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至宝未为代所奇，韫灵示[璞]荆山陲。","独使虹光天子识，不将清韵世人知。","世人所贵惟燕石，美玉对之成瓦砾。","空山埋照凡几年，古色苍痕宛自然。","重溪幂幂暗云树，一片荧荧光石泉。","美人之鉴明且彻，玉指提携叹奇绝。","试劳香袖拂莓苔，不觉清心皎冰雪。","连城美价幸逢时，命代良工岂见遗。","试作珪璋礼天地，何如瓀𤨟在堦墀。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":[],"scene":["冬","雪","山"],"cats":{"抒情":["孤独"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"9d8d3ee1-81f4-4938-8797-5dcd5be1f720","title":"李云南征蛮诗","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["圣人赫斯怒，诏伐西南戎。","肃穆庙堂上，深沈节制雄。","遂令感激士，得建非常功。","料死不料敌，顾恩宁顾终。","鼓行天海外，转战蛮夷中。","梯𪩘近高鸟，穿林经毒虫。","鬼门无归客，北户多南风。","蜂虿隔万里，云雷随九攻。","长驱大浪破，急击群山空。","饷道忽已远，悬军垂欲穷。","精诚动白日，愤薄连苍穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地弥西东。","临事耻苟免，履危能饬躬。","将星独照耀，边色何溟蒙。","泸水夜可涉，交州今始通。","归来长安道，召见甘泉宫。","廉蔺若未死，孙吴知暗同。","相逢论意气，慷慨谢深衷。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨","悲怆"],"scene":[],"cats":{"抒情":["孤独"],"天气":["写云"],"人生":["战争"]},"theme_conf":0.589},{"uid":"b423f06b-4c05-4892-a409-7933ccf2edf8","title":"横吹曲辞 陇头吟","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陇水潺湲陇树黄，征人陇上尽思乡。","马嘶斜日朔风急，雁过寒云边思长。","残月出林明劒戟，平沙隔水见牛羊。","横行俱足封侯者，谁斩楼兰献未央。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","楼","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["冬天"],"天气":["写风"],"生活":["边塞"]},"theme_conf":0.645},{"uid":"57259261-28ad-4dde-a63f-e3bb6a9dd1a7","title":"元日早朝","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["九陌朝臣满，三朝候鼓赊。","远珂时接韵，攒炬偶成花。","紫贝为高阙，黄龙建大牙。","参差万戟合，左右八貂斜。","羽扇纷朱槛，金𬬻隔翠华。","微风传曙漏，晓日上春霞。","环珮声重叠，蛮夷服等差。","乐和天易感，山固寿无涯。","渥泽千年圣，车书四海家。","盛明多在位，谁得守蓬麻。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["春节"]},"theme_conf":0.96},{"uid":"0e6f466c-3fc6-4930-a25b-3c14172c1b41","title":"寒食宴城北山池即故郡守荣阳郑钢目为折柳亭","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别馆青山郭，游人折柳行。","落花经上巳，细雨带清明。","𫛸鴂流芳暗，鸳鸯曲水平。","归心何处醉，宝瑟有余声。"],"theme":"节令风俗","theme2":["送别"],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"抒情":["离别","思乡"],"天气":["写雨"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.88},{"uid":"452ca2e5-a3f8-4dd1-b262-6ba2af5f3ea3","title":"杂曲歌辞 拜新月","author":"吉中孚妻张氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["拜新月，拜月出堂前。","暗魄深笼桂，虚弓未引弦。","拜新月，拜月妆楼上。","鸾镜未安台，蛾眉已相向。","拜新月，拜月不胜情，庭前风露清。","月临人自老，望月更长生。","东家阿母亦拜月，一拜一悲声断绝。","昔年拜月逞容仪，如今拜月双泪垂。","回看众女拜新月，却忆红闺年少时。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["月"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"0254bcd5-b7b9-43c3-9a6c-b2a8f8aba5a1","title":"送最澄阇梨还日本诗","author":"陆质","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["海东国主尊台教，遣僧来听《妙法华》。","归来香风满衣裓，讲堂日出映朝霞。","（见日本比睿山无量院沙门慈本〖一七九四--一八六八〗在文久二年〖一八六二〗撰《天台霞标》第四篇第一卷。","转录自《中国哲学史研究》一九八五年第一期刊日本户崎哲彦撰《留传日本的有关陆质的史料及若干考证》。","此篇承束景南先生告知。","）（按：慈本于诗下注云：「此诗未知出于何书。","慈本获之希烈宿称钞书中也。","原本海作汝，妙作于，慈本依义改之。","或曰：此诗载在《禅宗日工集》，又改数字载之《本朝高僧传》某传也。","」户崎氏考证此诗又见于《空华老师日用工夫略集》卷一，第二句作「故遣僧来听《法华》」。","约在公元一三○○年前后即传为陆质诗。","但吴𫖮等九人送最澄诗，皆为五言律诗，唯此首为七言古绝，「因此，该诗疑为后人假托之作，或以意采录。","」）。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"天气":["太阳"],"植物":["梨花"]},"theme_conf":0.659},{"uid":"dbda2c85-f609-450a-8e93-a6c8f2723372","title":"柏崖老人号无名先生男削发女黄冠自以云泉独乐命予赋诗","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古也忧婚嫁，君能乐性肠。","长男栖月宇，少女炫霓裳。","问尔餐霞处，春山芝桂旁。","鹤前飞九转，壶里驻三光。","与我开龙峤，披云静药堂。","胡麻兼藻绿，石髓隔花香。","帝力言何有，椿年喜渐长。","窅然高象外，宁不傲羲皇。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["月","花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.779},{"uid":"397d3ca6-87eb-49f5-ac12-65687c07ce8c","title":"相和歌辞 来日大难","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["来日一身，携粮负薪。","道长食尽，苦口焦唇。","今日醉饱，乐过千春。","仙人相存，诱我远学。","海陵三山，陆憩五岳。","乘龙上三天，飞目瞻两角。","授以神药，金丹满握。","蟪蛄蒙恩，深媿短促。","思填东海，彊衔一木。","道重天地，轩师广成。","蝉翼九五，以求长生。","下士大笑，如苍蝇声。"],"theme":"游仙梦幻","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"2b9b6071-6dc8-4b04-949c-5350f23e4f9d","title":"和微之春日投简阳明洞天五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青阳行已半，白日坐将徂。","越国强仍大，稽城高且孤。","利饶盐煮海，名胜水澄湖。","牛斗天垂象，台明地展图。","瓌奇填市井，佳丽溢𬮱阇。","句践遗风霸，西施旧俗姝。","船头龙夭矫，桥脚兽睢盱。","乡味珍蟛蚏，时鲜贵鹧鸪。","语言诸夏异，衣服一方殊。","捣练蛾眉婢，鸣榔蛙角奴。","江清敌伊洛，山翠胜荆巫。","华表双栖鹤，联樯几点乌。","烟波分渡口，云树接城隅。","涧远松如画，洲平水似铺。","绿科秧早稻，紫笋折新芦。","暖蹋泥中藕，香寻石上蒲。","雨来萌尽达，雷后蛰全苏。","柳眼黄丝颣，花房绛蜡珠。","林风新竹折，野烧老桑枯。","带亸长枝蕙，钱穿短贯榆。","暄和生野菜，卑湿长街芜。","女浣纱相伴，儿烹鲤一呼。","山魈啼稚子，林狖挂山都。","产业论蚕蚁，孳生计鸭雏。","泉岩雪飘洒，苔壁锦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹庙径盘纡。","洞穴何因凿，星槎谁与刳。","石凹仙药臼，峰峭佛香炉。","去为投金简，来因挈玉壶。","贵仍招客宿，健未要人扶。","闻望贤丞相，仪形美丈夫。","前驱驻旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳凫。","学禅超后有，观妙造虚无。","髻里传僧宝，环中得道枢。","登楼诗八咏，置砚赋三都。","捧拥罗将绮，趋跄紫与朱。","庙谟藏稷卨，兵略贮孙吴。","令下三军整，风高四海趋。","千家得慈母，六郡事严姑。","重士过三哺，轻财抵一铢。","送觥歌宛转，嘲妓笑卢胡。","佐饮时炮鼈，蠲酲数鲙鲈。","醉乡虽咫尺，乐事亦须臾。","若不中贤圣，何由外智愚。","伊予一生志，我尔百年躯。","江上三千里，城中十二衢。","出多无伴侣，归只对妻孥。","白首青山约，抽身去得无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"欢愉","mood2":["孤寂"],"scene":["江","山","江南","舟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"天气":["太阳"],"人物":["母亲","儿童"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"0167687e-8325-48bf-8da4-3749c9ce0a74","title":"横吹曲辞 关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"04803420-1f5b-48f0-abba-2940006ba36b","title":"月夜梧桐叶上见寒露","author":"戴察","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["萧疎桐叶上，月白露初团。","滴沥清光满，荧煌素彩寒。","风摇愁玉坠，枝动惜珠干。","气冷疑秋晚，声微觉夜阑。","凝空流欲遍，润物净宜看。","莫厌窥临倦，将晞聚更难。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.82},{"uid":"8a2266dd-ed4e-4168-8464-ec32d966daaa","title":"校猎义成喜逢大雪率题九韵以示群官","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["弧矢威天下，旌旗游近县。","一面施鸟罗，三驱教人战。","暮云成积雪，晓色开行殿。","皓然原隰同，不觉林野变。","北风勇士马，东日华组练。","触地银麞出，连山缟鹿见。","月兔落高矰，星狼下急箭。","既欣盈尺兆，复忆磻谿便。","岁丰将遇贤，俱荷皇天眷。"],"theme":"边塞征战","theme2":["边塞征战","咏物","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"],"人生":["战争"]},"theme_conf":0.55},{"uid":"25be9870-8794-4702-bdb9-8ed2a7df8051","title":"湘夫人二首 二","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南有涔阳路，渺渺多新愁。","桂酒神降时，回风江上秋。","彩云忽无处，碧水空安流。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.68},{"uid":"7ef7bc94-3b3f-4224-ba4c-889a39870e38","title":"朝日勅赐百官樱桃","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["仙果人间都未有，今朝忽见下天门。","捧盘小吏初宣勅，当殿群臣共拜恩。","日色遥分门下坐，露香才出禁中园。","每年重此先偏待，愿得千春奉至尊。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"天气":["太阳"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"92f47c36-d77a-4ab5-b5df-893d6ea09e28","title":"赋得白云起封中","author":"李正辞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千年泰山顶，云起汉皇封。","不作奇峰状，宁分触石容。","为霖虽易得，表圣自难逢。","冉冉排空上，依依叠影重。","素光非曳练，灵贶是从龙。","岂学无心出，东西任所从。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"天气":["写云"]},"theme_conf":0.648},{"uid":"dad3755e-883c-4022-83a4-4a47583c8112","title":"相和歌辞 陇西行","author":"长孙佐辅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阴云凝朔气，陇上正飞雪。","四月草不生，北风劲如切。","朝来羽书急，夜救长城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲堕，马冻蹄亦裂。","射雁旋充饥，斧冰还止渴。","宁辞解围鬬，但恐乘疲没。","早晚边候空，归来养羸卒。"],"theme":"边塞征战","theme2":["民生疾苦","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思乡"],"天气":["写雪"]},"theme_conf":0.388},{"uid":"cp54b638987d48b5","title":"天香","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["孤峤蟠烟，层涛蜕月，骊宫夜采铅水。","讯远槎风，梦深薇露，化作断魂心字。","红瓷候火，还乍识、冰环玉指。","一缕萦帘翠影，依稀海天云气。","几回娇半醉。","翦春灯、夜寒花碎。","更好故溪飞雪，小窗深闭。","荀令如今顿老，总忘却、樽前旧风味。","谩惜馀熏，空篝素被。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约","豪放"],"mood":"孤寂","mood2":[],"scene":["雪","夜","花","酒"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"0a0f9231-d88c-4f81-b941-83b67a736194","title":"长恨歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["夜","楼","山","春","秋","园林"],"cats":{"抒情":["爱情","伤感","孤独","闺怨","感恩"],"四季":["春天","秋天"],"天气":["写雨","星星"],"人物":["老师"],"人生":["梦想"]},"theme_conf":0.85},{"uid":"49359d18-613c-4aa0-8836-e2253b88d772","title":"十月诞辰内殿宴群臣效柏梁体联句","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["润色鸿业寄贤才，叨居右弼媿盐梅。","运筹帷幄荷时来，职掌图籍滥蓬莱。","两司谬忝谢钟裴，礼乐铨管效涓埃。","陈师振旅清九垓，欣承顾问侍天杯。","衔恩献寿梁柏台，黄缣青简奉康哉。","鲰生侍从忝王枚，右掖司言实不才。","宗伯秩礼天地开，帝歌难续仰昭回。","微臣捧日变寒灰，远慙班左媿游陪。"],"theme":"羁旅思乡","theme2":["游仙梦幻","送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"抒情":["思乡"],"天气":["月亮"]},"theme_conf":0.35},{"uid":"81144889-f17a-4590-bbeb-5a9fdb7fcf4d","title":"春日江村五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["群盗哀王粲，中年召贾生。","登楼初有作，前席竟为荣。","宅入先贤传，才高处士名。","异时怀二子，春日复含情。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"cp0485bf7cefb2ea","title":"五煞・腊月里桑采甚的，肚脐里爆豆实心儿退。木猫儿守窟瞧他甚，泥狗","author":"杜仁杰","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["儿看家守甚黑。","天长观里看水庵相识，济元庙里口愿把我抛持。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"天气":["月亮"],"动物":["写猫"]},"theme_conf":1.0},{"uid":"cc0d85da-2fc0-4cd0-9163-b23561e07541","title":"横吹曲辞 陇头吟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长安少年游侠客，夜上戍楼看太白。","陇头明月迥临关，陇上行人夜吹笛。","关西老将不胜愁，驻马听之双泪流。","身经大小百余战，麾下偏裨万户侯。","苏武才为典属国，节旄空尽海西头。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人生":["战争"]},"theme_conf":1.0},{"uid":"a891f80d-fe12-429e-a820-3890a3c6af9e","title":"秋风函谷应诏","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋风起函谷，劲气动河山。","偃松千岭上，杂雨二陵间。","低云愁广隰，落日惨重关。","此时飘紫气，应验真人还。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.97},{"uid":"6393b72d-7d61-4201-9072-e5589b1637ab","title":"杂曲歌辞 行路难","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见长安城北渭桥边，枯木横槎卧古田。","昔日含红复含紫，常时留雾亦留烟。","春景春风花似雪，香车玉轝恒阗咽。","若个游人不竞攀，若个倡家不来折。","倡家宝袜蛟龙帔，公子银鞍千万骑。","黄莺一向花娇春，两两三三将子戏。","千尺长条百尺枝，丹桂青榆相蔽亏。","珊瑚叶上鸳鸯鸟，凤凰巢里雏鹓儿。","巢倾枝折凤归去，条枯叶落狂风吹。","一朝零落无人问，万古摧残君讵知。","人生贵贱无终始，倏忽须臾难久恃。","谁家能驻西山日，谁家能堰东流水。","汉家陵树满秦川，行来行去尽哀怜。","自昔公卿二千石，咸拟荣华一万年。","不见朱唇将白貌，惟闻素棘与黄泉。","金貂有时须换酒，玉麈但摇莫计钱。","寄言坐客神仙署，一生一死交情处。","苍龙阙下君不来，白鹤山前我应去。","云间海上邈难期，赤心会合在何时？","但愿尧年一百万，长作巢由也不辞。"],"theme":"羁旅思乡","theme2":["哲理悟道","送别","山水田园"],"style":"绮丽","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","春","花","雪"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":0.35},{"uid":"9f5ded08-4f6f-4641-878e-897904483479","title":"郡斋雨中与诸文士燕集","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["兵卫森画戟，宴寝凝清香。","海上风雨至，逍遥池阁凉。","烦疴近消散，嘉宾复满堂。","自慙居处崇，未覩斯民康。","理会是非遣，性达形迹忘。","鲜肥属时禁，蔬果幸见尝。","俯饮一杯酒，仰聆金玉章。","神欢体自轻，意欲凌风翔。","吴中盛文史，群彦今汪洋。","方知大藩地，岂曰财赋疆。"],"theme":"应制干谒","theme2":[],"style":"旷达","style2":["清新","绮丽"],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"afb30a0c-422f-4656-b0bb-90174c0d3d1f","title":"长安叙怀寄崔十五","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["延首直城西，花飞绿草齐。","迢遥隔山水，怅望思游子。","百啭黄鹂细雨中，千条翠柳衡门里。","门对长安九衢路，愁心不惜芳菲度。","风尘冉冉秋复春，钟鼓喧喧朝复暮。","汉家宫阙在中天，紫陌朝臣车马连。","萧萧霓旌合仙杖，悠悠剑佩入炉烟。","李广少时思报国，终军未遇敢论边。","无媒守儒行，荣悴纷相映。","家甚长卿贫，身多公干病。","不知身病竟如何，嬾向青山眠薜萝。","鸡黍空多元伯惠，琴书不见子猷过。","超名累岁与君同，自叹还随鹢退风。","闻说唐生子孙在，何当一为问穷通。"],"theme":"寄赠酬答","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["相思","恬淡"],"scene":["雨","春","花"],"cats":{"抒情":["思念","爱国"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.9},{"uid":"7b1f320f-14f3-4520-9bd8-314be626f5f3","title":"琴曲歌辞 雉朝飞操","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝阳陇东泛暖景，双啄双飞双顾影。","朱冠锦襦聊日整，漠漠雾中如衣褧。","伤心卢女弦，七十老翁长独眠。","雄飞在草雌在田，衷肠结愤气呵天。","圣人在上心不偏，翁得女妻甚可怜。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":0.66},{"uid":"0457d34c-f28a-47a0-aa77-ab3b3a3b14e7","title":"杂曲歌辞 古别离","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["太湖三山口，吴王在时道。","寂寞千载心，无人见春草。","谁堪缄怨者，持此伤怀抱。","孤舟畏狂风，一点宿烟岛。","望所思兮若何，月荡漾兮空波。","云离离兮北断，鴈眇眇兮南多。","身去兮天畔，心折兮湖岸。","春山胡为兮塞路，使我归梦兮撩乱。"],"theme":"送别","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["春","塞外","舟","山","月"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.619},{"uid":"c012d2aa-e678-491c-aa1d-d201ed7d6e2a","title":"寄李白","author":"任华","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古来文章有能奔逸气，耸高格。","清人心神，惊人魂魄。","我闻当今有李白，大猎赋，鸿猷文，嗤长卿，笑子云。","班张所作琐细不入耳，未知卿云得在嗤笑限。","登庐山，观瀑布，海风吹不断，江月照还空。","余爱此两句：登天台，望渤海云垂大鹏飞，山压巨鳌背，斯言亦好在。","至于他作多不拘常律，振摆超腾，既俊且逸。","或醉中操纸，或兴来走笔。","手下忽然片云飞，眼前划见孤峰出。","而我有时白日忽欲睡，睡觉歘然起攘臂。","任生知有君，君也知有任生未。","中间闻道在长安，及余戾止。","君已江东访元丹，邂逅不得见君面。","每常把酒，向东望良久。","见说往年在翰林，胸中矛戟何森森。","新诗传在宫人口，佳句不离明主心。","身骑天马多意气，目送飞鸿对豪贵。","承恩召入凡几回，待诏归来仍半醉。","权臣妬盛名，群犬多吠声。","有勅放君却归隐沦处，高歌大笑出关去。","且向东山为外臣，诸侯交迓驰朱轮。","白璧一双买交者，黄金百镒相知人。","平生傲岸其志不可测，数十年为客，未尝一日低颜色。","八咏楼中坦腹眠，五侯门下无心忆。","繁花越台上，细柳吴宫侧。","绿水青山知有君，白云明月偏相识。","养高兼养闲，可望不可攀。","庄周万物外，范蠡五湖间。","人传访道沧海上，丁令王乔每往还。","蓬莱径是曾到来，方丈岂唯方一丈。","伊余每欲乘兴往相寻，江湖拥隔劳寸心。","今朝忽遇东飞翼，寄此一章表胸臆。","傥能报我一片言，但访任华有人识。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新","旷达"],"mood":"恬淡","mood2":["欢愉","慷慨"],"scene":["山","江","月","酒"],"cats":{"山水":["庐山","瀑布"],"天气":["写云","月亮"],"人生":["哲理","梦想"]},"theme_conf":0.95},{"uid":"92fa6241-0397-448c-8a97-27f659ef9dd9","title":"秋雨叹三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["阑风长雨（一作「东风细雨」）秋纷纷，四海（一作「万里」）八荒同一云。","去马来牛不复辨，浊泾清渭何当分。","禾（一作「木」）头生耳黍穗黑，农夫田妇（一作「父」）无消息。","城中斗米换（一作「抱」）衾裯，相许宁论两相直。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","秋"],"cats":{"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.673},{"uid":"24f063d6-b3bb-4368-ae89-1e2af8fb3a0f","title":"雨过苏端","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸡鸣风雨交，久旱云亦好。","杖藜入春泥，无食起我早。","诸家忆所历，一饭迹便埽。","苏侯得数过，欢喜每倾倒。","也复可怜人，呼儿具梨枣。","浊醪必在眼，尽醉摅怀抱。","红稠屋角花，碧委墙隅草。","亲宾纵谈谑，喧闹畏衰老。","况蒙霈泽垂，粮粒或自保。","妻孥隔军垒，拨弃不拟道。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"1352fbf1-2c3d-459c-b4ac-061e0c6befb8","title":"杂曲歌辞 长干行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾发初覆额，折花门前剧。","郎骑竹马来，遶床弄青梅。","同居长干里，两小无嫌猜。","十四为君妇，羞颜尚不开。","低头向暗壁，千唤不一回。","十五始展眉，愿同尘与灰。","常存抱柱信，岂上望夫台。","十六君远行，瞿塘滟预堆。","五月不可触，猨鸣天上哀。","门前迟行迹，一一生绿苔。","苔深不能扫，落叶秋风早。","八月蝴蝶来，双飞西园草。","感此伤妾心，坐愁红颜老。","早晚下三巴，预将书报家。","相迎不道远，直至长风沙。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":["豪放","清新"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","月","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.557},{"uid":"bee2baa5-b40f-4740-a10e-5633dc1250d8","title":"听夜雨寄卢纶","author":"李端","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["暮雨萧条过凤城，霏霏飒飒重还轻。","闻君此夜东林宿，听得荷池几番声。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","夜"],"cats":{"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"9525f99d-39cb-4d04-8650-263493d223e0","title":"早发白帝城","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朝辞白帝彩云间，千里江陵一日还。","两岸猨声啼不尽，轻舟已过万重山。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江","山"],"cats":{"天气":["写云"]},"theme_conf":1.0},{"uid":"88d4489c-981b-416d-97bd-d7de86b432d8","title":"九日与敬处士左学士同赋采菊上东山便为首句","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采菊上东山，山高路非远。","江湖乍辽敻，城郭亦在眼。","昼日市井喧，闰年禾稼晚。","开尊会佳客，长啸临绝𪩘。","戏鹤唳且闲，断云轻不卷。","乡心各万里，醉话时一展。","乔木列遥天，残阳贯平坂。","徒忧征车重，自笑谋虑浅。","却顾郡斋中，寄傲与君同。"],"theme":"节令风俗","theme2":["山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["重阳","山"],"cats":{"抒情":["思乡"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"9fa92cdf-24cf-4a6a-af33-db5809652091","title":"杂曲歌辞 秋夜曲二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天清漏长霜泊泊，兰绿收荣桂膏涸。","高楼云鬟弄婵娟，古瑟暗断秋风弦。","玉关遥隔万里道，金刀不翦双泪泉。","香囊火死香气少，向帷合眼何时晓？","城乌作营嗁野月，秦川少妇生离别。"],"theme":"送别","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","夜"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.511},{"uid":"faada38b-ba84-4066-b426-10159e66011b","title":"陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雨来沾席上，风急打船头。","越女红帬湿，燕姬翠黛愁。","缆侵隄柳系，幔宛浪花浮。","归路飜萧飒，陂塘五月秋。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.65},{"uid":"8eeb3273-d271-4674-900b-2057c3f59957","title":"杂曲歌辞 结客少年场行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韩魏多奇节，倜傥遗名利。","共矜然诺心，各负纵横志。","结友一言重，相思千里至。","绿沈明月弦，金络浮云辔。","吹箫入吴市，击筑游燕肆。","寻源博望侯，结客远相求。","少年重一顾，长驱背陇头。","燄燄霜戈动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈行秋。","轻生徇知己，非是为身谋。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["月","冬","秋","夏","雪"],"cats":{"抒情":["友情","思念","思乡"],"四季":["夏天","秋天","冬天"],"天气":["月亮"],"人生":["青春"]},"theme_conf":0.495},{"uid":"98b0fd3d-e436-43bb-98b3-3949c75a902a","title":"三星行","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我生之辰，月宿南斗。","牛奋其角，箕张其口。","牛不见服箱，斗不挹酒浆。","箕独有神灵，无时停簸扬。","无善名已闻，无恶声已讙。","名声相乘除，得少失有余。","三星各在天，什伍东西陈。","嗟汝牛与斗，汝独不能神。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","月"],"cats":{"抒情":["思乡","孤独"],"天气":["星星"]},"theme_conf":0.65},{"uid":"6045a96b-444d-4bc2-adb7-84baa1d21591","title":"杜秀才画立走水牛歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昆仑儿，骑白象，时时锁著师子项。","奚奴跨马不搭鞍，立走水牛惊汉官。","江村小儿好夸骋，脚踏牛头上牛领。","浅草平田攃过时，大虫著钝几落井。","杜生知我恋沧州，画作一障张床头。","八十老婆拍手笑，妬他织女嫁牵牛。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.634},{"uid":"cpfeda664cad7f2d","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"theme":"送别","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["悲慨","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","春","月"],"cats":{"抒情":["友情","离别","伤感","闺怨"],"四季":["春天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.357},{"uid":"cp3a5031bf7e3981","title":"拜星月・拜星月慢","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜色催更，清尘收露，小曲幽坊月暗。","竹槛灯窗，识秋娘庭院。","笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。","水眄兰情，总平生稀见。","画图中、旧识春风面。","谁知道、自到瑶台畔。","眷恋雨润云温，苦惊风吹散。","念荒寒、寄宿无人馆。","重门闭、败壁秋虫叹。","怎奈向、一缕相思，隔溪山不断。"],"theme":"山水田园","theme2":["爱情相思","游仙梦幻"],"style":"清新","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月","园林","夜"],"cats":{"抒情":["爱情","思念","孤独"],"天气":["月亮","星星"]},"theme_conf":0.359},{"uid":"36b6f467-dc98-4ac0-9b1b-316b4a65db43","title":"连州吟 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["羽翼不自有，相追力难任。","唯凭方寸灵，独夜万里寻。","方寻魂飘飖，南梦山岖嵚。","髣髴惊魍魉，悉窣闻枫林。","正直被放者，鬼魅无所侵。","贤人多安排，俗士多虚钦。","孤怀吐明月，众毁铄黄金。","愿君保玄曜，壮志无自沉。"],"theme":"游仙梦幻","theme2":[],"style":"幽峭","style2":["旷达","豪放"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.65},{"uid":"fb087f9d-b19c-4c65-a310-c605f73a1fde","title":"夏日叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夏日出东北，陵天经中街。","朱光彻厚地，郁蒸何由开。","上苍久无雷，无乃号令乖。","雨降不濡物，良田起黄埃。","飞鸟苦热死，池鱼涸其泥。","万人尚流冗，举目唯蒿莱。","至今大河北，化作虎与豺。","浩荡想幽蓟，王师安在哉？","对食不能餐，我心殊未谐。","眇然贞观初，难与数子偕。"],"theme":"民生疾苦","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"6d303931-f900-4f29-a8b9-caea611a521f","title":"寄韩谏议","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今我不乐思岳阳，身欲奋飞病在床。","美人娟娟隔秋水，濯足洞庭望八荒。","鸿飞冥冥日月白，青枫叶赤天雨霜。","玉京群帝集北斗，或骑骐𬴊翳凤皇。","芙蓉旌旗烟雾乐，影动倒景摇潇湘。","星宫之君醉琼浆，羽人稀少不在旁。","似闻昨者赤松子，恐是汉代韩张良。","昔随刘氏定长安，帷幄未改神惨伤。","国家成败吾岂敢，色难腥腐餐风香。","周南留滞古所惜，南极老人应寿昌。","美人胡为隔秋水，焉得置之贡玉堂。"],"theme":"游仙梦幻","theme2":["送别","边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["星星"],"人物":["女子"]},"theme_conf":0.385},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"c89fcc8b-70df-4b67-84c8-6c855555eb41","title":"杂曲歌辞 夜坐吟","author":"李白","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马头谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞稍出东南涯，陆郎去矣乘斑骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"cpbf297a8f400d71","title":"澡兰香","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。","银瓶露井，彩云窗，往事少年依约。","为当时、曾写榴裙，伤心红绡褪萼。","黍梦光阴渐老，汀洲烟箬。","莫唱江南古调，怨抑难招，楚江沈魄。","薰风燕乳，暗雨梅黄，午镜澡兰帘幕。","念秦楼、也拟人归，应翦菖浦自酌。","但怅望、一屡新蟾，随人天角。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["清新","绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["江","花","江南"],"cats":{"抒情":["伤感","怀古"],"天气":["写云"],"人生":["时光"]},"theme_conf":1.0},{"uid":"3e598395-2064-42df-ae7a-16bf591c0695","title":"苦雪四首 一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二月犹北风，天阴雪冥冥。","寥落一室中，怅然慙百龄。","苦愁正如此，门柳复青青。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"68a65221-277b-4996-8d68-fed7604c1b8c","title":"东平蓬莱驿夜宴平卢杨判官醉后赠别姚太守置酒留宴","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["驿楼涨海壖，秋月寒城边。","相见自不足，况逢主人贤。","夜清酒浓人如玉，一斗何啻直十千。","木兰为樽金为杯，江南急管卢女弦。","齐童如花解郢曲，起舞激楚歌采莲。","固知别多相逢少，乐极哀至心婵娟。","少留莫辞醉，前路方悠然。","明日分飞傥相忆，祗应遥望西南天。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["离别"],"天气":["月亮"],"节日":["中秋节"],"食物":["写酒"]},"theme_conf":0.416},{"uid":"5180277d-a3b2-4644-9f1f-2d5a4af7c604","title":"杂曲歌辞 春日行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春日融融池上暖，竹牙出土兰心短。","草堂晨起酒半醒，家僮报我园花满。","头上皮冠未曾整，直入花间不寻径。","树树殷勤尽遶行，举枝未徧春日暝。","不用积金著青天，不用服药求神仙。","但愿园里花长好，一生饮酒花前老。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"c353940d-4bbc-4420-83bf-07cb4606d35f","title":"赋得早雁出云鸣","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["初秋玉露清，早雁出空鸣。","隔云时乱影，因风乍含声。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"四季":["秋天"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.697},{"uid":"335314f2-aa38-4f25-a0c3-6d8e375daec6","title":"宿曾江口示姪孙湘二首 一","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["云昏水奔流，天水漭相围。","三江灭无口，其谁识涯圻。","暮宿投民村，高处水半扉。","犬鸡俱上屋，不复走与飞。","篙舟入其家，暝闻屋中唏。","问知岁常然，哀此为生微。","海风吹寒晴，波扬众星辉。","仰视北斗高，不知路所归。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["星星"]},"theme_conf":0.534},{"uid":"f8ec87e7-3074-40dd-8d87-a260dad83ae7","title":"相和歌辞 短歌行二首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曈曈太阳如火色，上行千里下一刻。","出为白昼入为夜，圜转如珠住不得。","住不得，可奈何？为君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君复强饮一杯。","人生不得长欢乐，年少须臾老到来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"天气":["写风"],"人生":["青春"]},"theme_conf":0.65},{"uid":"84d91507-c2a6-4260-8145-2ed3cab95504","title":"夜归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜来归来冲虎过，山黑家中已眠卧。","傍见北斗向江低，仰看明星当空大。","庭前把烛嗔两炬，峡口惊猿闻一个。","白头老罢舞复歌，杖藜不睡谁能那。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡"],"天气":["星星"]},"theme_conf":1.0},{"uid":"3ef4b782-4495-49dc-9da5-b022da15c2a6","title":"句","author":"后主煜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["迢迢牵牛星，杳在河之阳。","粲粲黄姑女，耿耿遥相望。","鸎狂应有恨，蝶舞已无多。","揖让月在手，动摇风满怀。","病态如衰弱，厌厌向五年。","衰颜一病难牵复，晓殿君临颇自羞。","冷笑秦皇经远略，静怜姬满苦时巡。","鬓从今日添新白，菊是去年依旧黄。","万古到头归一死，醉乡葬地有高原。","人生不满百，刚作千年画。","日暎仙云薄，秋高天碧深。","乌照始潜辉，龙烛便争秉。","凝珠满露枝，游飏日已西。","肃穆寒初至，九重开扇鹄。","四牖炳灯鱼，羽觞无算酌。","倾盌更为寿，深卮递酬宾。"],"theme":"羁旅思乡","theme2":["送别"],"style":"清新","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"天气":["星星"]},"theme_conf":0.507},{"uid":"49577c84-9adc-4983-96ef-81d474492aa9","title":"又雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南雪不到地，青崖沾未消。","微微向日薄，脉脉去人遥。","冬热鸳鸯病，峡深豺虎骄。","愁边有江水，焉得北之朝。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["爱情","伤感"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"0a28ac61-d628-4b69-8c3e-5dfa084bcaae","title":"舞曲歌辞 霓裳辞十首 六","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["弦索𪭢𪭢隔彩云，五更初发一山闻。","武皇自送西王母，新换霓裳月色裙。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"天气":["写云","月亮"]},"theme_conf":1.0},{"uid":"551ff4cc-f942-44ea-942a-9e97dedc5431","title":"舞曲歌辞 东海有勇妇","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["梁山感杞妻，恸哭为之倾。","金石忽暂开，都由激深情。","东海有勇妇，何慙苏子卿。","学劒越处子，超腾若流星。","捐躯报夫讐，万死不顾生。","白刃耀素雪，苍天感精诚。","十步两躩跃，三呼一交兵。","斩首掉国门，蹴踏五藏行。","割此伉俪愤，粲然大义明。","北海李使君，飞章奏天庭。","舍罪警风俗，流芳播沧瀛。","志在列女籍，竹帛已光荣。","淳于免诏狱，汉主为缇萦。","津妾一櫂歌，脱父于严刑。","十子若不肖，不如一女英。","豫让斩空衣，有心竟无成。","要离杀庆忌，壮夫素所轻。","妻子亦何辜，焚之买虚名。","岂如东海妇，事立独扬名。"],"theme":"闺情宫怨","theme2":["送别"],"style":"豪放","style2":["冲淡"],"mood":"悲怆","mood2":["慷慨"],"scene":["雪","江南"],"cats":{"抒情":["闺怨","爱国"],"天气":["写雪"]},"theme_conf":0.643},{"uid":"805134d3-3d71-496b-a4ae-08e6871461ec","title":"咏虹","author":"苏味道","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纡余带星渚，窈窕架天浔。","空因壮士见，还共美人沈。","逸照含良玉，神花藻瑞金。","独留长劒彩，终负昔贤心。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"孤寂","mood2":["慷慨"],"scene":[],"cats":{"抒情":["孤独"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":1.0},{"uid":"489e9d6a-f619-4103-acde-0ba0bdfca086","title":"相和歌辞 蛾眉怨","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见宜春苑中九华殿，飞阁连连直如发。","白日全含朱鸟窗，流云半入苍龙阙。","宫中彩女夜无事，学凤吹箫弄清越。","珠帘北卷待凉风，绣户南开向明月。","忽闻天子忆蛾眉，宝凤衔花揲两螭。","传声走马开金屋，夹路鸣环上玉墀。","长乐彤庭宴华寝，三千美人曳光锦。","灯前含笑更罗衣，帐里承恩荐瑶枕。","不意君心半路回，求仙别作望仙台。","仓琅禁闼遥相忆，紫翠岩房昼不开。","欲向人间种桃实，先从海底觅蓬莱。","蓬莱可求不可上，孤舟缥缈知何往？","黄金作盘铜作茎，晴天白露掌中擎。","王母嫣然感君意，云车雨斾欲相迎。","飞帘观前空怨慕，少君何事须相误。","一朝埋没茂陵田，贱妾蛾眉不重顾。","宫车晚出向南山，仙卫逶迤去不还。","朝晡泣对麒麟树，树下苍苔日渐斑。","人生百年夜将半，对酒长歌莫长叹。","賸知白日不可思，一死一生何足算。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思","欢愉"],"scene":["夜","月","山","楼"],"cats":{"抒情":["思念","闺怨","感恩"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.59},{"uid":"1d65129a-ea27-4ec6-b8ed-8c12ee3d0d0a","title":"秋日书怀","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["金貂玉铉奉君恩，夜漏晨钟老掖垣。","参决万机空有媿，静观群动亦无言。","杯中壮志红颜歇，林下秋声绛叶翻。","倦鸟不知归去日，青芜白露满郊园。"],"theme":"咏怀抒感","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"慷慨","mood2":["恬淡"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["励志","梦想"]},"theme_conf":0.9},{"uid":"b48efd98-7757-45e7-88d9-f9bbcadadc51","title":"相里使君第七男生日","author":"包何","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["取妻生子复生男，独有君家众所谈。","荀氏八龙唯欠一，桓山四凤已过三。","他时干蛊声名著，今日悬弧宴乐酣。","谁道众贤能继体，须知个个出于蓝。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"04fa7a4c-e624-4083-9668-b05394a5a61d","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["伊昔黄花酒，如今白发翁。","追欢筋力异，望远岁时同。","弟妹悲歌里，朝廷醉眼中。","兵戈与关塞，此日意无穷。"],"theme":"边塞征战","theme2":["节令风俗"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["酒","重阳","塞外"],"cats":{"抒情":["伤感"],"天气":["太阳"],"生活":["边塞"],"节日":["重阳节"]},"theme_conf":0.374},{"uid":"fdf597bd-d45c-407d-9a5b-739be83771de","title":"春日望海","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["披襟眺沧海，凭轼玩春芳。","积流横地纪，疎派引天潢。","仙气凝三岭，和风扇八荒。","拂潮云布色，穿浪日舒光。","照岸花分彩，迷云雁断行。","怀卑运深广，持满守灵长。","有形非易测，无源讵可量。","洪涛经变野，翠岛屡成桑。","之罘思汉帝，碣石想秦皇。","霓裳非本意，端拱且图王。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":0.693},{"uid":"93c07519-1b9a-4ec0-b8e8-841cd597e49c","title":"腊日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["腊日常年暖尚遥，今年腊日冻全消。","侵陵雪色还萱草，漏泄春光有柳条。","纵酒欲谋良夜醉，还家初散紫宸朝。","口脂面药随恩泽，翠管银罂下九霄。"],"theme":"节令风俗","theme2":["应制干谒","闲适隐逸"],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","酒","夜"],"cats":{"天气":["太阳"]},"theme_conf":0.9},{"uid":"22abc39e-e43e-4644-97f0-08053b5fa3ee","title":"相和歌辞 上云乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞香走红满天春，花龙盘盘上紫云。","三千宫女列金屋，五十弦瑟海上闻。","大江碎碎银沙路，嬴女机中断烟素。","断烟素，缝舞衣，八月一日君前舞。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","春","月"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["长江"],"天气":["写云"]},"theme_conf":1.0},{"uid":"a2aed629-465d-412c-a68d-780068488725","title":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"],"theme":"亲情","theme2":["民生疾苦","亲情","羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["离别","思乡","伤感"],"山水":["江河"],"天气":["月亮"],"生活":["田野"]},"theme_conf":0.87},{"uid":"9149aa7c-b352-4a0f-aaeb-85ab10403744","title":"和谢舍人雪夜寓直","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["禁省夜沈沈，春风雪满林。","沧洲归客梦，青琐近臣心。","挥翰宣鸣玉，承恩在赐金。","建章寒漏起，更助掖垣深。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["思乡","感恩"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"202bd0c0-4003-4749-a804-f28a5995b752","title":"玩月诗 三","author":"曲龙山仙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["造化天桥碧海东，玉轮还过辗晴虹。","霓襟似拂瀛洲顶，颢气潜消橐籥中。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"天气":["彩虹","月亮"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"e4d4c69a-9803-4863-bb93-8b0be8420bbd","title":"郊居对雨寄赵涓给事包佶郎中","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暑雨青山里，随风到野居。","乱沤浮曲砌，悬溜响前除。","尘镜愁多掩，蓬头嬾更梳。","夜窗凄枕席，阴壁润图书。","萧飒宜新竹，龙钟拾野蔬。","石泉空自咽，药圃不堪锄。","浊水淙深辙，荒兰拥败渠。","繁枝留宿鸟，碎浪出寒鱼。","桑屐时登望，荷衣自卷舒。","应怜在泥滓，无路托高车。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.577},{"uid":"4a88edd5-84ad-4d97-a77b-f60be6dcf70e","title":"绝句漫兴九首 九","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隔户杨柳弱袅袅，恰似十五女儿腰。","谁谓朝来不作意，狂风挽断最长条。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"天气":["写风"]},"theme_conf":0.7},{"uid":"21d815f2-631f-4389-935e-f7054b2552e2","title":"谪官辰州冬至日[有]怀","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年长至在长安，策杖曾簪獬豸冠。","此岁长安逢至日，下堦遥想雪霜寒。","梦随行伍朝天去，身寄穷荒报国难。","北望南郊消息断，江头唯有泪阑干。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["相思","愁怨"],"scene":["冬"],"cats":{"抒情":["思乡","伤感","爱国"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"8b6db087-2999-4f42-9877-67c2a4cfde45","title":"喜雨","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["闲居倦时燠，开轩俯平林。","雷声殷遥空，云气布层阴。","川上风雨来，洒然涤烦襟。","田家共欢笑，沟浍亦已深。","团团聚邻曲，斗酒相与斟。","樵歌野田中，渔钓沧江浔。","苍天暨有念，悠悠终我心。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["田野"]},"theme_conf":0.578},{"uid":"2cb99ff8-0c0b-40c2-8d66-a760adba5c7f","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 九","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹起处，头尾地侵天。","其虹见时非有雨，晴天见者血成川，民更有灾愆。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"43f8bb74-5673-41a8-96ac-6a5e3a906382","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春生南国瘴，气待北风苏。","向晚霾残日，初宵鼓大𬬻。","爽携卑湿地，声拔洞庭湖。","万里鱼龙伏，三更鸟兽呼。","涤除贪破浪，愁绝付摧枯。","执热沈沈在，凌寒往往须。","且知宽疾胏，不敢恨危途。","再宿烦舟子，衰容问仆夫。","今晨非盛怒，便道即长驱。","隐几看帆席，云州涌坐隅。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["夜","江","舟"],"cats":{"抒情":["伤感"],"天气":["写风"],"人生":["励志"]},"theme_conf":0.72},{"uid":"0c1c7765-a078-485f-9e03-f3905bc9d517","title":"赋得含峰云","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["翠楼含晓雾，莲峰带晚云。","玉叶依岩聚，金枝触石分。","横天结阵影，逐吹起罗文。","非复阳台下，空将惑楚君。"],"theme":"咏物","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":0.508},{"uid":"3e627ebd-0fd3-4669-a32c-5d108d5d4ce6","title":"相和歌辞 决绝[词]三首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乍可为天上牵牛织女星，不愿为庭前红槿枝。","七月七日一相见，故心终不移。","那能朝开暮飞去，一任东西南北吹。","分不两相守，恨不两相思。","对面且如此，背面当何知。","春风撩乱伯劳语，此时抛去时。","握手苦相问，竟不言后期。","君情既决绝，妾意已参差。","借如死生别，安得长苦悲。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["七夕","春","月"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"四季":["春天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"e9ff4727-4dec-4fd8-ab61-336c693af7c3","title":"清明日登城春望寄大夫使君","author":"王表","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春城闲望爱睛天，何处风光不眼前。","寒食花开千树雪，清明日出万家烟。","兴来促席唯同舍，醉后狂歌尽少年。","闻说莺啼却惆怅，诗成不见谢临川。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"相思","mood2":["惆怅"],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"50b39f91-4d82-4166-b291-d73be5d35733","title":"阻雨不得归瀼西甘林","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三伏适已过，骄阳化为霖。","欲归瀼西宅，阻此江浦深。","坏舟百版坼，峻岸复万寻。","篙工初一弃，恐泥劳寸心。","伫立东城隅，怅望高飞禽。","草堂乱悬圃，不隔昆仑岑。","昏浑衣裳外，旷绝同层阴。","园甘长成时，三寸如黄金。","诸侯旧上计，厥贡倾千林。","邦人不足重，所迫豪吏侵。","客居暂封殖，日夜偶瑶琴。","虚徐五株态，侧塞烦胸襟。","焉得辍两足，杖藜出岖嵚。","条流数翠实，偃息归碧浔。","拂拭乌皮几，喜闻樵牧音。","令儿快搔背，脱我头上簪。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"]},"theme_conf":0.357},{"uid":"e1404531-b21b-4e48-b715-9a9ead6cf56c","title":"寄卢仝","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉川先生洛城里，破屋数间而已矣。","一奴长须不裹头，一婢赤脚老无齿。","辛勤奉养十余人，上有慈亲下妻子。","先生结发憎俗徒，闭门不出动一纪。","至今邻僧乞米送，仆忝县尹能不耻。","俸钱供给公私余，时致薄少助祭祀。","劝参留守谒大尹，言语才及輙掩耳。","水北山人得名声，去年去作幕下士。","水南山人又继往，鞍马仆从塞闾里。","少室山人索价高，两以谏官徴不起。","彼皆刺口论世事，有力未免遭驱使。","先生事业不可量，惟用法律自绳己。","春秋三传束高阁，独抱遗经究终始。","往年弄笔嘲同异，怪辞惊众谤不已。","近来自说寻坦途，犹上虚空跨绿駬。","去年生儿名添丁，意令与国充耘耔。","国家丁口连四海，岂无农夫亲耒耜。","先生抱才终大用，宰相未许终不仕。","假如不在陈力列，立言垂范亦足恃。","苗裔当蒙十世宥，岂谓贻厥无基阯。","故知忠孝生天性，洁身乱伦安足拟。","昨晚长须来下状，隔墙恶少恶难似。","每骑屋山下窥阚，浑舍惊怕走折趾。","凭依婚媾欺官吏，不信令行能禁止。","先生受屈未曾语，忽此来告良有以。","嗟我身为赤县令，操权不用欲何俟。","立召贼曹呼伍伯，尽取鼠辈尸诸市。","先生又遣长须来，如此处置非所喜。","况又时当长养节，都邑未可猛政理。","先生固是余所畏，度量不敢窥涯涘。","放纵是谁之过欤，效尤戮仆愧前史。","买羊沽酒谢不敏，偶逢明月曜桃李。","先生有意许降临，更遣长须致双鲤。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春","塞外","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":0.95},{"uid":"cp63c0eb274856fe","title":"念奴娇","author":"张孝祥","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洞庭青草，近中秋、更无一点风色。","玉鉴琼田三万顷，著我扁舟一叶。","素月分辉，明河共影，表里俱澄澈。","悠然心会，妙处难与君说。","应念岭海经年，孤光自照，肝肺皆冰雪。","短发萧骚襟袖冷，稳泛沧浪空阔。","尽吸西江，细斟北斗，万象为宾客。","扣舷独笑，不知今夕何夕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","江","舟","中秋","冬"],"cats":{"抒情":["思乡","孤独"],"天气":["写雪"],"节日":["中秋节"]},"theme_conf":0.529},{"uid":"b08883e7-d43b-45fd-9c1d-b770b8e8bbdf","title":"奉使过石门观瀑","author":"丘丹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["溪上望悬泉，耿耿云中见。","披榛上岩岫，峭壁正东面。","千仞泻联珠，一潭喷飞霰。","嵯𤄓满山响，坐觉炎氛变。","照日类虹霓，从风似绡练。","灵奇既天造，惜处穷海甸。","吾祖昔登临，谢公亦游衍。","王程惧淹泊，下磴空延眷。","千里雷尚闻，峦回树葱蒨。","此来共贱役，探讨愧前彦。","永欲洗尘缨，终当惬此愿。"],"theme":"山水田园","theme2":["咏史怀古","民生疾苦"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.44},{"uid":"009701aa-5f62-4c7c-b0d7-c7a195709dd9","title":"玉台观","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浩劫因王造，平台访古游。","彩云萧史驻，文字鲁恭留。","宫阙通群帝，乾坤到十洲。","人传有笙鹤，时过此山头。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"天气":["写云"]},"theme_conf":0.6},{"uid":"08cf0ce8-bd26-4bab-a4d2-5bc43acf8376","title":"相和歌辞 日出行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["日出东方隈，似从地底来。","历天又入海，六龙所舍安在哉？","其始与终古不息，人非元气安能与之久裴回。","草不谢荣于春风，木不怨落于秋天。","谁挥鞭策驱四运，万物兴歇皆自然。","羲和羲和，汝奚汩没于荒淫之波。","鲁阳何德？驻景挥戈。","逆道违天，矫诬实多。","吾将囊括大块，浩然与溟涬同科。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"天气":["太阳"]},"theme_conf":0.65},{"uid":"7175c86c-5225-4405-a542-0a41be737c43","title":"古意","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["河边织女星，河畔牵牛郎。","未得渡清浅，相对遥相望。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.93},{"uid":"a8ad6062-6360-4804-8a85-e123e41c7058","title":"上元日梦王母献白玉环","author":"张佐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梦中朝上日，阙下拜天颜。","仿佛瞻王母，分明献玉环。","灵姿趋甲帐，悟道契玄关。","似见霜姿白，如看月彩弯。","霓裳归物外，凤历晓人寰。","仙圣非相远，昭昭寤寐间。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"人生":["梦想"],"节日":["春节","元宵节"]},"theme_conf":0.97},{"uid":"b67ddf05-43fb-4859-a1a9-34f95d45aabf","title":"和晋陵陆丞早春游望","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光照绿苹。","忽闻歌苦调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"6b91be50-04b7-4afd-a8cd-fd519f6913e2","title":"送冷朝阳及第东归江宁","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高第由佳句，诸生似者稀。","长安带酒别，建业候潮归。","稚子欢迎櫂，隣人为扫扉。","含情过旧浦，鸥鸟亦依依。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"天气":["太阳"],"人物":["儿童"]},"theme_conf":0.563},{"uid":"ee3195f6-eb17-4e87-b714-f7cf07ff03f2","title":"鼓吹曲辞 上之回","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三十六离宫，楼台与天通。","阁道步行月，美人愁烟空。","恩疎宠不及，桃李伤春风。","淫乐意何极，金舆向回中。","万乘出黄道，千旗扬彩虹。","前军细柳北，后骑甘泉东。","岂问渭川老，宁邀襄野童。","秋暮瑶池宴，归来乐未穷。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.538},{"uid":"4cfeb483-2cfb-4f3e-8ed1-059eaccdd260","title":"君不见简苏徯","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见道边废弃池，君不见前者摧折桐。","百年死树中琴瑟，一斛旧水藏蛟龙。","丈夫盖棺事始定，君今幸未成老翁。","何恨顦顇在山中，深山穷谷不可处，霹雳魍魉兼狂风。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"天气":["写风"]},"theme_conf":0.88},{"uid":"efb8e0c4-59ad-4806-9df7-31ce2b642c11","title":"南家桃","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南家桃树深红色，日照露光看不得。","树小花狂风易吹，一夜风吹满墙北。","离人自有经时别，眼前落花心叹息。","更待明年花满枝，一年迢递空相忆。"],"theme":"送别","theme2":["羁旅思乡","爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["夜","花"],"cats":{"抒情":["离别","思念","思乡"],"天气":["写风"],"植物":["桃花"]},"theme_conf":0.374},{"uid":"545ae0c5-171e-4e69-9c4c-b9a4300f6f95","title":"九日","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惆怅重阳日，空山野菊新。","蒹葭百战地，江海十年人。","叹老堪衰柳，伤秋对白苹。","孤楼闻夕磬，塘路向城𬮱。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"776db07f-66d2-4776-bd49-70f44b8aa67f","title":"奉和太常王卿酬中书李舍人中书寓直春夜对月见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["露如轻雨月如霜，不见星河见鴈行。","虚晕入池波自泛，满轮当苑桂多香。","春台几望黄龙阙，云路宁分白玉郎。","是夜巴歌应金石，岂殊萤影对清光。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"绮丽","style2":["婉约","清新"],"mood":"相思","mood2":[],"scene":["月","春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮","星星"]},"theme_conf":0.98},{"uid":"258e8498-75f6-4ec4-968f-9043297c7e68","title":"送著公归越","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁能愁此别，到越会相逢。","长忆云门寺，门前千万峰。","石床埋积雪，山路倒枯松。","莫学白居士，无人知去踪。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["江南","山"],"cats":{"抒情":["思念","伤感","孤独"],"天气":["写雪"]},"theme_conf":0.644},{"uid":"4bd8ab64-ee6d-4ba5-938c-85650dace115","title":"献襄阳于大夫","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["襄阳青山郭，汉江白铜堤。","谢公领兹郡，山水无尘泥。","铁马万霜雪，绛旗千虹霓。","风漪参差泛，石板重叠跻。","旧泪不复堕，新欢居然齐。","还畊竟原野，归老相扶携。","物色增暧暧，寒芳更萋萋。","渊清有遐略，高躅无近蹊。","即此富苍翠，自然引翔栖。","曩游常抱忆，夙好今尚暌。","愿言从逸辔，暇日凌清溪。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":["愁怨"],"scene":["雪","山"],"cats":{"抒情":["伤感"],"天气":["彩虹"]},"theme_conf":0.479},{"uid":"830c5d4c-c70e-4b88-837a-f25efc71be2b","title":"端午日礼部宿斋有衣服彩结之贶以诗还荅","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良辰当五日，偕老祝千年。","彩缕同心丽，轻裾暎体鲜。","寂寥斋画省，欵曲擘香牋。","更想传觞处，孙孩徧目前。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.66},{"uid":"9477a2d1-3108-45a6-93e3-6b3f56d9bed6","title":"续姚梁公坐右铭","author":"贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["善为尔诸身，行为尔性命。","祸福必可转，莫悫言前定。","见人之得，如己之得。","则美无不克，见人之失。","如己之失，是亨贞吉。","反此之徒，天鬼必诛。","福先祸始，好杀灭[纪]。","不得不止，守谦寡欲。","善善恶恶，不得不作。","无见贵热，谄走蹩躠。","无轻贱微，上下相依。","古圣著书，矻矻孳孳。","忠孝信行，越食逾衣。","生天地间，未或非假。","身危彩虹，景速奔马。","胡不自彊，将升玉堂。","胡为自坠，言虚行伪。","艳殃尔寿须戒，酒腐尔肠须畏。","励志须至，扑满必破。","非莫非于餙非，过莫过于文过。","及物阴功，子孙必封。","无恃文学，是司奇薄。","患随不忍，害逐无足。","一此一彼，谐宫合征。","亲仁下问，立节求己。","恶木之阴匪阴，盗泉之水匪水。","世孚草草，能生几几。","直须如冰如玉，种桃种李。","嫉人之恶，酬恩报义。","忽己之慢，成人之美。","毋担虚誉，无背至理。","恬和𢙏畅，冲融终始。","天人之行，尽此而已。","丁宁丁宁，戴发含齿。"],"theme":"边塞征战","theme2":["送别"],"style":"旷达","style2":["幽峭","婉约"],"mood":"慷慨","mood2":[],"scene":[],"cats":{"天气":["彩虹"]},"theme_conf":0.538},{"uid":"699800d5-6ce3-4f34-8f68-78b6c32f7202","title":"古瑟怨","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["破瑟悲秋已减弦，湘灵沈怨不知年。","感君拂拭遗音在，更奏新声明月天。"],"theme":"闺情宫怨","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感","闺怨","感恩"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"54b45313-84ba-446a-9cbe-f58304b1c29b","title":"相和歌辞 江南弄","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江南弄，巫山连楚梦，行雨行云几相送。","瑶轩金谷上春时，玉童仙女无见期。","紫露香烟眇难托，清风明月遥相思。","遥相思，草徒绿，为听双飞凤凰曲。"],"theme":"山水田园","theme2":["爱情相思","送别"],"style":"清新","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","思念"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.357},{"uid":"bddf2874-e96b-43b9-85d9-e4d7d89d25b9","title":"大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["二八婵娟大堤女，开垆相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠娥。","珍簟华灯夕阳后，当垆理瑟矜纤手。","月落星微五鼓声，春风摇荡牕前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.667},{"uid":"906627d5-30e9-4ed3-adeb-3de852f9be50","title":"幽居有白菊一丛因而成咏呈知己","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["还是延年一种材，即将瑶朵冒霜开。","不如红艳临歌扇，欲伴黄英入酒杯。","陶令接䍠堪岸著，梁王高屋好欹来。","月中若有闲田地，为劝嫦娥作意裁。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["友情"],"天气":["月亮"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"c48a91ea-6d94-42d1-8466-f5a9f42cc1d6","title":"送兵到蓟北","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["积雪与天迥，屯军连塞愁。","谁知此行迈，不为觅封侯。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.529},{"uid":"9ea879f4-9781-469a-8b52-fc5777e633c2","title":"茅屋为秋风所破歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["八月秋高风怒号，卷我屋上三重茅。","茅飞度江洒江郊，高者挂罥长林梢。","下者飘转沈塘坳，南邨群童欺我老无力。","忍能对面为盗贼，公然抱茅入竹去。","唇焦口燥呼不得，归来倚仗自叹息。","俄顷风定云墨色，秋天漠漠向昏黑。","布衾多年冷似铁，骄儿恶卧踏里裂。","床床屋漏无干处，雨脚如麻未断绝。","自经丧乱少睡眠，长夜沾湿何由彻。","安得广厦千万间，大庇天下寒士俱欢颜。","风雨不动安如山，呜呼！何时眼前突兀见此屋？","吾庐独破受冻死亦足。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"悲慨","style2":["幽峭"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.568},{"uid":"3bbfafbe-cb90-4552-8ddf-b3789804f5d2","title":"温泉宫行","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["十月一日天子来，青绳御路无尘埃。","宫前内里汤各别，每个白玉芙蓉开。","朝元阁向山上起，城绕青山龙暖水。","夜开金殿看星河，宫女知更月明里。","武皇得仙王母去，山鸡昼鸣宫中树。","温泉决决出宫流，宫使年年修玉楼。","禁兵去尽无射猎，日西麋鹿登城头。","棃园弟子偷曲谱，头白人间教歌舞。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","夜","月","山"],"cats":{"天气":["星星"]},"theme_conf":0.593},{"uid":"c4912092-34c2-42fe-a9ff-b924b0dddf7f","title":"相和歌辞 春江花月夜","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉树歌阑海云黑，花庭忽作青芜国。","秦淮有水水无情，还向金陵漾春色。","杨家二世安九重，不御华芝嫌六龙。","百幅锦帆风力满，连天展尽金芙蓉。","珠翠丁星复明灭，龙头劈浪哀笳发。","千里涵空照水魂，万枝破鼻团香雪。","漏转霞高沧海西，颇黎枕上闻天鸡。","蛮弦代雁曲如语，一醉昏昏天下迷。","四方倾动烟尘起，犹在浓香梦魂里。","后主荒宫有晓莺，飞来只隔西江水。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"cp1ab8bda1f065cf","title":"采莲令","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月华收，云淡霜天曙。","西征客、此时情苦。","翠娥执手送临歧，轧轧开朱户。","千娇面、盈盈伫立，无言有泪，断肠争忍回顾。","一叶兰舟，便恁急桨凌波去。","贪行色、岂知离绪。","万般方寸，但饮恨，脉脉同谁语。","更回首、重城不见，寒江天外，隐隐两三烟树。"],"theme":"送别","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.622},{"uid":"ae472a2c-7977-4ed6-a893-7ef7c3136666","title":"柴门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["长江"],"天气":["月亮"],"生活":["乡村"]},"theme_conf":0.35},{"uid":"664ccc00-6def-413f-94ac-733c4ec9b6c1","title":"杂曲歌辞 君子有所思行 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我爱正考甫，思贤作商颂。","我爱扬子云，理乱皆如凤。","振衣中夜起，露花香旖旎。","扑碎骊龙明月珠，敲出凤凰五色髓。","陋卷萧萧风淅淅，缅想斯人胜珪璧。","寂寥千载不相逢，无限区区尽虚掷。","君不见沈约道，佳人不在兹，春光为谁惜。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["月","花"],"cats":{"抒情":["思念","怀古"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.86},{"uid":"83dcb67c-ccbc-4592-b232-368a6b5275ce","title":"赋得暮雨送李胄","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚江微雨里，建业暮钟时。","漠漠帆来重，冥冥鸟去迟。","海门深不见，浦树远含滋。","相送情无限，沾襟比散丝。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":0.603},{"uid":"40c8fa66-2802-43df-ada6-1bd286cb49db","title":"八哀诗 赠司空王公思礼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["司空出东夷，童稚刷劲翮。","追随燕蓟儿，颖锐物不隔。","服事哥舒翰，意无流沙碛。","未甚拔行间，犬戎大充斥。","短小精悍姿，屹然强寇敌。","贯穿百万众，出入由咫尺。","马鞍悬将首，甲外控鸣镝。","洗劒青海水，刻铭天山石。","九曲非外蕃，其王转深壁。","飞兔不近驾，鸷鸟资远击。","晓达兵家流，饱闻春秋癖。","胷襟日沈静，肃肃自有适。","潼关初溃散，万乘犹辟易。","偏裨无所施，元帅见手格。","太子入朔方，至尊狩梁益。","胡马缠伊洛，中原气甚逆。","肃宗登宝位，塞望势敦迫。","公时徒步至，请罪将厚责。","际会清河公，间道传玉册天王拜跪毕，谠议果冰释。","翠华卷飞雪，熊虎亘阡陌。","屯兵凤皇山，帐殿泾渭辟。","金成贼咽喉诏镇雄所搤。","禁暴清无双，爽气春淅沥。","巷有从公歌，野多青青麦。","及夫哭庙后，复领太原役恐惧禄位高，怅望王土窄。","不得见清时，呜呼就窀穸。","永系五湖舟，悲甚田横客。","千秋汾晋间，事与云水白。","昔观文苑传，岂述廉蔺绩。","嗟嗟邓大夫，士卒终倒戟。"],"theme":"悼亡挽歌","theme2":["悼亡挽歌","送别"],"style":"冲淡","style2":["悲慨","清新"],"mood":"悲怆","mood2":[],"scene":["雪","鸟","冬"],"cats":{"抒情":["伤感","悼亡"],"山水":["黄河"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"021b47d2-ef8a-42ca-a7c6-8a8bbb39a98a","title":"简简吟","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["苏家小女名简简，芙蓉花顋柳叶眼。","十一把镜学点妆，十二抽针能绣裳。","十三行坐事调品，不肯迷头白地藏。","玲珑云髻生花样，飘飖风袖蔷薇香。","殊姿异态不可状，忽忽转动如有光。","二月繁霜杀桃李，明年欲嫁今年死。","丈人阿母勿悲啼，此女不是凡夫妻。","恐是天仙谪人世，只合人间十三岁。","大都好物不坚牢，彩云易散琉璃脆。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["伤感","闺怨"],"天气":["写云"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"4e409fd6-6f44-40e3-82b0-3c0fb1f146ef","title":"秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄","author":"鲍防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["前月月明夜，美人同远光。","清尘一以间，今夕坐相忘。","风落芙蓉露，疑余绣被香。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"冲淡","style2":["沉郁","清新"],"mood":"相思","mood2":["欢愉"],"scene":["中秋","月","夜","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"天气":["月亮"],"人物":["女子"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"46b17890-4fbe-4d78-9fae-35ad3bad08e2","title":"奉和月夜观星应令","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["早秋炎景暮，初弦月彩新。","清风涤暑气，零露净嚣尘。","薄雾销轻縠，鲜云卷夕鳞。","休光灼前曜，瑞彩接重轮。","缘情摛圣藻，并作命徐陈。","宿草诚渝滥，吹嘘偶搢绅。","天文岂易述，徒知仰北辰。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月","夏","夜"],"cats":{"四季":["夏天"],"天气":["月亮","星星"]},"theme_conf":0.97},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"305ed419-7cad-4659-b393-9b52aafa375f","title":"温汤对雪","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风吹同云，同云飞白雪。","白雪乍回散，同云何惨烈。","未见温泉冰，宁知火井灭。","表瑞良在兹，庶几可怡悦。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","冬"],"cats":{"天气":["写雪"]},"theme_conf":1.0},{"uid":"8aa6132d-c61e-4218-af24-5d9009e6795d","title":"春日书情寄元校书伯和相国元子","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["数岁平津邸，诸生出门时。","羇孤力行早，疎贱托身迟。","芳草看无厌，青山到未期。","贫居悲老大，春日上茅茨。","卫玠琼瑶色，玄成鼎鼐姿。","友朋汉相府，兄弟谢家诗。","律合声虽应，劳歌调自悲。","流年不可住，惆怅镜中丝。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.88},{"uid":"9a2bdab8-9e68-4478-ade8-11d5fbb822c6","title":"杂曲歌辞 生别离","author":"孟云卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["结发生别离，相思复相保。","何知日已久，五变庭中草。","眇眇天海途，悠悠吴江岛。","但恐不出门，出门无远道。","远道行既难，家贫衣服单。","严风吹积雪，晨起鼻何酸。","人生各有恋，岂不怀所安。","分明天上日，生死誓同欢。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["雪"],"cats":{"抒情":["离别","思念"],"天气":["写雪"]},"theme_conf":0.74},{"uid":"1f92134b-bca9-46eb-b2fe-87b30413041a","title":"江雪","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["千山鸟飞绝，万迳人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["孤独"],"山水":["江河"],"天气":["写雪"]},"theme_conf":0.787},{"uid":"f5e1247c-6c4a-45a3-9f2e-60adee788526","title":"琴曲歌辞 宛转歌二首 二","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["晓将近，黄姑织女银河尽。","九华锦衾无复情，千金宝镜谁能引。","歌宛转，宛转伤别离。","愿作杨与柳，同向玉窗垂。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"抒情":["离别"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.486},{"uid":"7b36c019-2f0c-433b-b1a9-a4b5dec9b64b","title":"銮驾避狄岁寄别韩云卿","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白发壮心死，愁看国步移。","关山惨无色，亲爱忽惊离。","影绝龙分剑，声衰鸟恋枝。","茫茫云海外，相忆不相知。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["愁怨","悲怆"],"scene":["塞外","山"],"cats":{"抒情":["离别","伤感"],"天气":["写云"]},"theme_conf":0.839},{"uid":"aaf62ace-7464-47ef-a354-f952b9e2d2a9","title":"终南秋雪","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南岭见秋雪，千门生早寒。","闲时驻马望，高处卷帘看。","雾散琼枝出，日斜铅粉残。","偏宜曲江上，倒影入清澜。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","秋"],"cats":{"四季":["秋天"],"天气":["写雪"],"人物":["老师"]},"theme_conf":0.92},{"uid":"2c7dba62-fe55-41e2-a39b-baa1a128bcd8","title":"问李二司直所居云山","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["门外水流何处，天边树遶谁家。","山色东西多少，朝朝几度云遮。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":1.0},{"uid":"3379b41f-7a57-4cee-80e9-d4028f214653","title":"东郊迎春","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓见苍龙驾，东郊春已迎。","彩云天仗合，玄象太阶平。","佳气山川秀，和风政令行。","句陈霜骑肃，御道雨师清。","律向韶阳变，人随草木荣。","遥观上林树，今日遇迁莺。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"4874dc2a-9909-4205-b5da-4907c0724484","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十一","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白赤虹，昼（川本作「尽」）见莫兴兵。","更有虹霓垂军上，彼军杀将且须停，动必有灾迍。"],"theme":"边塞征战","theme2":[],"style":"旷达","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"e4bc93c8-417d-4670-8fc0-ca28d3fa3bf8","title":"忆长安 二月","author":"鲍防","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，二月时，玄鸟初至禖祠。","百啭宫莺绣羽，千条御柳黄丝。","更有曲江胜地，此来寒食佳期。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"清新","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","清明"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"cp8eb6476175d018","title":"风流子","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["新绿小池塘。","风帘动，碎影舞斜阳。","羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。","绣阁凤帏深几许，曾听得理丝簧。","欲说又休，虑乖芳信，未歌先咽，愁近清觞。","遥知新妆了，开朱户，应自待月西厢。","最苦梦魂，今宵不到伊行。","问甚时说与，佳音密耗，寄将秦镜，偷换韩香。","天便教人，霎时厮见何妨。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["旷达","绮丽"],"mood":"愁怨","mood2":[],"scene":["花","酒"],"cats":{"抒情":["伤感","闺怨"],"天气":["写风"]},"theme_conf":0.733},{"uid":"9f57b2df-7f47-4600-a68a-a3efb709ff40","title":"浙东元相公书叹梅雨郁蒸之候因寄七言","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["稽山自与岐山别，何事连年𬸚𬸦飞。","百辟商量旧相入，九天祗候老臣归。","平湖晚泛窥清镜，高阁晨开扫翠微。","今日看书最惆怅，为闻梅雨损朝衣。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","冬"],"cats":{"天气":["写雨"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"cp8ce1e669f23042","title":"戚氏","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚秋天。","一霎微雨洒庭轩。","槛菊萧疏，井梧零乱惹残烟。","凄然。","望江关。","飞云黯淡夕阳间。","当时宋玉悲感，向此临水与登山。","远道迢递，行人凄楚，倦听陇水潺。","正蝉吟败叶，蛩响衰草，相应喧喧。","孤馆度日如年。","风露渐变，悄悄至更阑。","长天净，绛河清浅，皓月婵娟。","思绵绵。","夜永对景，那堪屈指，暗想从前。","未名未禄，绮陌红楼，往往经岁迁延。","帝里风光好，当年少日，暮宴朝欢。","况有狂朋怪侣，遇当歌、对酒竞留连。","别来迅景如梭，旧游似梦，烟水程何限。","念利名、憔悴长萦绊。","追往事、空惨愁颜。","漏箭移、稍觉轻寒。","渐呜咽、画角数声残。","对闲窗畔，停灯向晓，抱影无眠。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"冲淡","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["夜","园林","楼"],"cats":{"抒情":["思乡","伤感","孤独","怀古"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.95},{"uid":"d35f583a-c20c-453c-a886-e13f98b2e4b4","title":"春思","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.596},{"uid":"20aa930c-017e-4a7d-8909-0782047d574d","title":"苦雨寄房四昆季","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["独坐见多雨，况兹兼索居。","茫茫十月交，穷阴千里余。","弥望无端倪，北风击林箊。","白日渺难覩，黄云争卷舒。","安得造化功，旷然一扫除。","滴沥簷宇愁，寥寥谈笑疎。","泥涂拥城郭，水潦盘丘墟。","惆怅悯田农，裴回伤里闾。","曾是力井税，曷为无斗储。","万事切中怀，十年思上书。","君门嗟缅邈，身计念居诸。","沈吟顾草茅，郁怏任盈虚。","黄鹄不可羡，鸡鸣时起予。","故人平台侧，高馆临通衢。","兄弟方荀陈，才华冠应徐。","弹棋自多暇，饮酒更何如。","知人想林宗，直道慙史鱼。","携手风流在，开襟鄙吝祛。","宁能访穷巷，相与对园蔬。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨","惆怅"],"scene":["雨"],"cats":{"抒情":["友情","伤感","孤独"],"天气":["写雨"]},"theme_conf":0.78},{"uid":"51e0d2da-d7db-4cd4-bdf8-a8f915a4834f","title":"送李八秘书赴杜相公幕","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青帘白舫益州来，巫峡秋涛天地回。","石出倒听枫叶下，橹摇背指菊花开。","贪趋相府今晨发，恐失佳期后命催。","南极一星朝北斗，五云多处是三台。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["星星"]},"theme_conf":0.554},{"uid":"a73d7bc0-d427-4363-9cff-b17eecd95e9d","title":"相和歌辞 朝云引","author":"郎大家宋氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["巴西巫峡指巴东，朝云触石上朝空。","巫山巫峡高何已，行雨行云一时起。","一时起，三春暮。","若言来，且就阳台路。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","雨","山"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"cp148022419cf353","title":"念奴娇","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["萧条庭院，有斜风细雨，重门须闭。","宠柳娇花寒食近，种种恼人天气。","险韵诗成，扶头酒醒，别是闲滋味。","征鸿过尽，万千心事难寄。","楼上几日春寒，帘垂四面，玉阑干慵倚。","被冷香消新梦觉，不许愁人不起。","清露晨流，新桐初引，多少游春意。","日高烟敛，更看今日晴未。"],"theme":"送别","theme2":["节令风俗","闲适隐逸"],"style":"婉约","style2":["清新","幽峭"],"mood":"相思","mood2":["慷慨","愁怨"],"scene":["雨","园林","楼","清明","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"ab0c8118-d665-4dc1-be2b-901ae13395ed","title":"夏日杨长宁宅送崔侍御常正字入京","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["醉酒扬雄宅，升堂子贱琴。","不堪垂老鬓，还对欲分襟。","天地西江远，星辰北斗深。","乌台俯麟阁，长夏白头吟。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["星星"]},"theme_conf":0.688},{"uid":"7fc091bf-83dd-498d-87e0-d82fd2575e0f","title":"赴阙次留献荆南成相公三十韵","author":"吴融","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["分阃兼文德，持衡有武功。","荆南知独去，海内更谁同。","拔地孤峰秀，当天一鹗雄。","云生五色笔，月吐六钧弓。","骨格凌秋耸，心源见底空。","神清飡沆瀣，气逸饮洪蒙。","临事成奇策，全身仗至忠。","解鞍欺李广，煮弩笑臧洪。","往昔逢多难，来兹故统戎。","卓旗云梦泽，扑火细腰宫。","铲土楼台搆，连江雉堞笼。","似平铺掌上，疑涌出壶中。","岂是劳人力，宁因役鬼工。","本遗三户在，今匝万家通。","画舸横青雀，危樯列彩虹。","席飞巫峡雨，袖拂宋亭风。","塲广盘毬子，池闲引钓筒。","礼贤金璧贱，煦物雪霜融。","酒满梁尘动，棋残漏滴终。","俭常资澹静，贵绝恃穹崇。","唯要臣诚显，那求帝渥隆。","甘棠名异奭，大树姓非冯。","自念为迁客，方谐谒上公。","痛知遭止棘，频叹委飘蓬。","借宅诛茅绿，分囷指粟红。","只惭燕馆盛，宁觉阮途穷。","涣汗沾明主，沧浪别钓翁。","去曾忧塞马，归欲逐边鸿。","积感深于海，衔恩重极嵩。","行行柳门路，回首下离东。"],"theme":"应制干谒","theme2":["闲适隐逸","应制干谒","送别"],"style":"冲淡","style2":["清新","幽峭"],"mood":"孤寂","mood2":["恬淡"],"scene":["楼","秋","酒","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.95},{"uid":"ce493923-7c4b-41a9-94e9-cf95741c018c","title":"酬程延秋夜即事见赠","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长簟迎风早，空城澹月华。","星河秋一雁，砧杵夜千家。","节候看应晚，心期卧亦赊。","向来吟秀句，不觉已鸣鸦。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","夜"],"cats":{"四季":["秋天"],"天气":["月亮","星星"]},"theme_conf":0.97},{"uid":"d30b4748-72eb-4f1d-b8de-99126216c38c","title":"梅雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南京西浦道，四月熟黄梅。","湛湛长江去，冥冥细雨来。","茅茨疎易湿，云雾密难开。","竟日蛟龙喜，盘涡与岸回。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨","江"],"cats":{"山水":["长江"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"3f79db59-87f2-4b64-9605-be330724d4de","title":"咏弓","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["上弦明月半，激箭流星远。","落雁带书惊，啼猿映枝转。"],"theme":"咏物","theme2":["边塞征战"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"天气":["月亮"]},"theme_conf":0.597},{"uid":"680c2d30-359c-475e-8e95-069f7018fdb0","title":"春日与诸公泛舟","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千里雪山开，沱江春水来。","驻帆云缥缈，吹管鹤裴回。","身外流年驶，尊前落景催。","不应归棹远，明月在高台。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.65},{"uid":"6ee646bb-07d2-4847-9527-8f90351bbe22","title":"沭阳古渡作","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日落问津处，云霞残碧空。","牧牛避田烧，退鹢随潮风。","回首故乡远，临流此路穷。","翩翩青冥去，羡彼高飞鸿。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":1.0},{"uid":"ce71032a-c075-492c-9554-51eb080348a5","title":"奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制","author":"王维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["渭水自萦秦塞曲，黄山旧遶汉宫斜。","銮舆迥出千门柳，阁道廻看上苑花。","云里帝城双凤阙，雨中春树万人家。","为乘阳气行时令，不是宸游玩物华。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨","楼","山"],"cats":{"四季":["春天"],"天气":["写雨"]},"theme_conf":0.99},{"uid":"1cdf7e65-ec12-41de-9474-7ff1eeacd5f3","title":"野次喜雪","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["拂曙辟行宫，寒皋野望通。","繁云低远岫，飞雪舞长空。","赋象恒依物，萦回屡逐风。","为知勤恤意，先此示年丰。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"]},"theme_conf":0.82},{"uid":"00ec6f0d-71fd-4eb2-b460-f95cecab414f","title":"清明日青龙寺上方赋得多字","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上方偏可适。","季月况堪过，远近水声至。","东西山色多，夕阳留径草。","新叶变庭柯，已度清明节。","春秋如客何。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.78},{"uid":"cp6a47d06d7bc689","title":"醉太平・这些时春寒绣ブ，月暗重门，梨花暮雨近黄昏，把香衾自温。金","author":"吴昌龄","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["杯不洗心头闷，青鸾不寄云边信，玉容不见意中人。","空教人害损。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","花","春","月","雨","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"],"食物":["写酒"]},"theme_conf":0.619},{"uid":"6cf4f8dd-9d3b-4ba0-84e6-109d36a9863e","title":"至日遣兴奉寄北省旧阁老两院故人二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去岁兹辰捧御床，五更三点入鹓行。","欲知趋走伤心地，正想氛氲满眼香。","无路从容陪语笑，有时颠倒著衣裳。","何人错忆穷愁日，愁日愁随一线长。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","园林"],"cats":{"抒情":["友情","伤感"],"天气":["太阳"]},"theme_conf":0.93},{"uid":"cd904f43-b9eb-4e30-a3fe-f2bcb215a8db","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红似燕支腻如粉，伤心好物不须臾。","山中风起无时节，明日重来得在无。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["清新","婉约"],"mood":"孤寂","mood2":[],"scene":["月","花","山","冬","夏"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["太阳","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.446},{"uid":"cd3d8e0c-a549-44a9-b55c-4f1c9b9befed","title":"秋霖中奉裴令公见招早出赴会马上先寄六韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是寻医药，非干送别离。","素书传好语，绛帐赴佳期。","续借桃花马，催迎杨柳姬。","只愁张录事，罚我怪来迟。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写雨"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.88},{"uid":"7c0b2801-38db-4c5a-95c1-9a8f1a65a1b9","title":"游石堂观","author":"萧祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西山高高何所如，上有古昔真人居。","嵚崖巨石自成室，其下磅礴含清虚。","我来斯邑访遗迹，乃遇沈生躭载籍。","沈生为政哀惸[嫠]，又能索隐探灵奇。","欣然向我话佳境，与我崎岖到山顶。","甘瓜剖绿出寒泉，碧瓯浮花酌春茗。","嚼瓜啜茗身清凉，汗消𫄨绤如迎霜。","胡为空山百草花，倏尔笾豆肆我旁。","始惊知周无小大，力寡多方验斯在。","妙用腾声冠盖间，胜游恣意烟霞外。","故碑石像凡几年，云郁雨霏生绿烟。","我知游此多灵仙，缥缈月中飞下天。","天风微微夕露委，松梢飕飕晓声起。","凤去空遗箫管音，星翻寥落银河水。","劝君学道此时来，结茅独宿何辽哉。","斋心玄默感灵卫，必见鸾鹤相裴回。","我爱崇山双劒北，峰如人首拄天黑。","群仙伛偻势奔走，壮若归尊趋有德。","半岩有洞顶有池，出入灵怪潜蛟螭。","我去不得昼夜思，梦游曾信南风吹。","南风吹我到林岭，故国不见秦天逈。","山花名药扑地香，月色泉声洞心冷。","荫松散发逢异人，寂寞旷然口不言。","道陵公远莫能识，发短耳长谁独存。","司农惊觉忽惆怅，可惜所游俱是妄。","蕴怀耿耿谁与言，直至今来意通形神开。","拥传又恨斜阳催，一丘人境尚堪恋，何况海上金银台。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["山","月"],"cats":{"抒情":["孤独","怀古"],"天气":["月亮","星星"]},"theme_conf":0.517},{"uid":"939e0995-4c5d-4af7-9f47-3c1ae9875797","title":"和东观群贤七夕临泛昆明池","author":"任希古","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋风始摇落，秋水正澄鲜。","飞眺牵牛渚，激赏镂鲸川。","岸珠沦晓魄，池灰敛曙烟。","泛查分写汉，仪星别搆天。","云光波处动，日影浪中悬。","惊鸿絓蒲弋，游鲤入庄筌。","萍叶疑江上，菱花似镜前。","长林代轻幄，细草即芳筵。","文峰开翠潋，笔海控清涟。","不挹兰樽圣，空仰桂舟仙。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["绮丽","婉约"],"mood":"欢愉","mood2":[],"scene":["七夕","园林"],"cats":{"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.82},{"uid":"3f27da66-1e73-4bee-91a4-9de2d9545fc2","title":"相和歌辞 采莲曲","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["妾家越水边，摇艇入江烟。","既觅同心侣，复采同心莲。","折藕丝能脆，开花叶正圆。","春歌弄明月，归棹落花前。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["爱情"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.713},{"uid":"7ac0a7d0-2347-4647-8165-9dca1bef2530","title":"鲜于少府宅看花","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谢家能植药，万簇相萦倚。","烂熳绿苔前，婵娟青草里。","垂栏复照户，映竹仍临水。","骤雨发芳香，回风舒锦绮。","孤光杂新故，众色更重累。","散碧出疎茎，分黄成细蘂。","游蜂高更下，惊蝶坐还起。","玉貌对应慙，霞标方不似。","春阴怜弱蔓，夏日同短晷。","回落报荣衰，交关鬬红紫。","花时苟未赏，老至谁能止。","上客屡移床，幽僧劳凭几。","初合虽薄劣，却得陪君子。","敢问贤主人，何如种桃李。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["思乡","孤独"],"天气":["写雨"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"e0cbff86-2ace-41db-b528-c33689a3afe8","title":"丈人山","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自为青城客，不唾青城地。","为爱丈人山，丹梯近幽意。","丈人祠西佳气浓，缘云拟住最高峰。","埽除白发黄精在，君看他时冰雪容。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写雪"]},"theme_conf":1.0},{"uid":"48e87201-2f41-4e2d-bb1a-f3e1c828757d","title":"郊庙歌辞 祀风师乐章 迎神","author":"包佶","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["太皞御气，句芒肇功。","苍龙青旗，爰候祥风。","律以和应，神以感通。","鼎俎修蚃，时惟礼崇。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"天气":["写风"]},"theme_conf":0.84},{"uid":"cp62f4acdb0a97af","title":"宴清都","author":"卢祖皋","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春讯飞琼管。","风日薄、度墙啼鸟声乱。","江城次第，笙歌翠合，绮罗香暖。","溶溶涧渌冰泮。","醉梦里、年华暗换。","料黛眉重锁隋堤，芳心还动梁苑。","新来雁阔云音，鸾分槛影，无计重见。","啼春细雨，笼愁澹月，恁时庭院。","离肠未语先断。","算犹有、凭高望眼。","更那堪、芳草连天，飞梅弄晚。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新","婉约"],"mood":"欢愉","mood2":["愁怨","恬淡"],"scene":["园林","雨","鸟","冬"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.509},{"uid":"0ee73c58-cce4-4852-b95b-73ce2d12618e","title":"过宣上人湖上兰若","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十年湖上结幽期，偏向东林遇远师。","未道姓名童子识，不酬言语上人知。","闲花落日滋苔径，细雨和烟著柳枝。","问我别来何所得，解将无事当无为。"],"theme":"佛道禅颂","theme2":["闲适隐逸","山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江","雨"],"cats":{"抒情":["怀古"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.82},{"uid":"e6bf25ce-19e9-4316-bd35-cdc6bb050c61","title":"奉酬卢给事云夫四兄曲江荷花行见寄幷呈上钱七兄阁老张十八助教","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲江千顷秋波净，平铺红云盖明镜。","大明宫中给事归，走马来看立不正。","遗我明珠九十六，寒光映骨睡骊目。","我今官闲得婆娑，问言何处芙蓉多。","撑舟昆明度云锦，脚敲两舷呌吴歌。","太白山高三百里，负雪崔嵬插花里。","玉山前却不复来，曲江汀滢水平杯。","我时相思不觉一回首，天门九扇相当开。","上界真人足官府，岂如散仙鞭笞鸾凤终日相追陪。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江","花","山"],"cats":{"抒情":["思念"],"山水":["江河"],"天气":["写云"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"efafe0cd-54fd-40a4-be7b-117a45d18ee1","title":"鼓吹曲辞 巫山高","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["巫山望不极，望望下朝雰。","莫辨啼猿树，徒看神女云。","惊涛乱水脉，骤雨暗峰文。","沾裳即此地，况复远思君。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"天气":["写雨"]},"theme_conf":1.0},{"uid":"6a322d06-85db-48ee-a1d1-5b5d3964e2d0","title":"步虚词十九首 十五","author":"韦渠牟","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西海辞金母，东方拜木公。","云行疑带雨，星步欲凌风。","羽袖挥丹凤，霞巾曳彩虹。","飘飖九霄外，下视望仙宫。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["雨"],"cats":{"天气":["彩虹"]},"theme_conf":0.65},{"uid":"6872be3d-cd6b-4609-b54a-e481006f6cf6","title":"奉和圣制春中兴庆宫酺宴应制","author":"张说","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千龄逢启圣，万域共来威。","庆接郊禋后，酺承农事稀。","御楼横广路，天乐下重闱。","鸾凤调歌曲，虹霓动舞衣。","合声云上聚，连步月中归。","物覩恩无外，神和道入微。","镐京陪乐饮，柏殿奉文飞。","徒竭秋云影，何资春日晖。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.99},{"uid":"7ecd869d-dd96-421b-905b-a70a0cb44bad","title":"琴曲歌辞 秋风引","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["何处秋风至？萧萧送鴈群。","朝来入庭树，孤客最先闻。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.402},{"uid":"e2fec465-cea1-4829-b12d-3ba37a267562","title":"同从弟销南斋玩月忆山阴崔少府","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高卧南斋时，开帷月初吐。","清辉淡水木，演漾在窗户。","苒苒几盈虚，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹兰杜。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.503},{"uid":"7fa19519-78a9-494b-b6f2-2a22a48ba3f3","title":"三日书怀因示百僚","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["佳节上元巳，芳时属暮春。","流觞想兰亭，捧劒得金人。","风轻水初绿，日晴花更新。","天文信昭回，皇道颇敷陈。","恭己每从俭，清心常保真。","戒兹游衍乐，书以示群臣。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵","花","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["元宵节"]},"theme_conf":0.86},{"uid":"01b077b6-659b-436b-9085-3c693bd0f48c","title":"诏许昌崔明府拜补阙","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["儒者久营道，诏书方问贤。","至精一耀世，高步谁同年。","何树可栖凤，高梧枝拂天。","脱身凫舄里，载笔虎闱前。","日月传轩后，衣冠真列仙。","则知骊龙珠，不秘清泠泉。","才子贵难见，郢歌空复传。","惜哉效颦客，心想劳婵娟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","月"],"cats":{"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"3ff56a31-51e0-4926-a44e-73635f47c545","title":"郊庙歌辞 享太庙乐章 景云舞","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["景云霏烂，告我帝符。","噫帝冲德，与天为徒。","笙镛遥远，俎豆虚无。","春秋孝献，回复此都。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春","秋","雨"],"cats":{"四季":["春天","秋天"],"天气":["写云"]},"theme_conf":0.95},{"uid":"09366fe4-04f9-4665-abc0-810b9a9c6720","title":"投简成华两县诸子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赤县官曹拥材杰，软裘快马当冰雪。","长安苦寒谁独悲，杜陵野老骨欲折。","南山豆苗早荒秽，青门瓜地新冻裂。","乡里儿童项领成，朝廷故旧礼数绝。","自然弃掷与时异，况乃疎顽临事拙。","饥卧动即向一旬，敝裘何啻联百结。","君不见空墙日色晚，此老无声泪垂血。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["冬","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人物":["儿童"]},"theme_conf":0.73},{"uid":"b7b344b4-2f7a-48a0-97b1-50073a9263c8","title":"和席八十二韵","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绛阙银河曙，东风右掖春。","官随名共美，花与思俱新。","绮陌朝游间，绫衾夜直频。","横门开日月，高阁切星辰。","庭变寒前草，天销霁后尘。","沟声通苑急，柳色压城匀。","纶綍谋猷盛，丹青步武亲。","芳菲含斧藻，光景畅形神。","傍砌看红药，巡池咏白苹。","多情怀酒伴，余事作诗人。","倚玉难藏拙，吹竽久混真。","坐慙空自老，江海未还身。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"孤寂","mood2":[],"scene":["春","园林","花"],"cats":{"四季":["春天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"5ddf9bdd-fa07-4f3c-897e-d6428fb97147","title":"送人游蜀","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["别离杨柳陌，迢遰蜀门行。","若听清猨后，应多白发生。","虹霓侵栈道，风雨杂江声。","过尽愁人处，烟花是锦城。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["离别","伤感"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"ca2145e0-816c-435b-8e7b-5bb087f6568c","title":"三学山夜看圣灯","author":"蜀太妃徐氏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["圣灯千万炬，旋向碧空生。","细雨湿不暗，好风吹更明。","磬敲金地响，僧唱梵天声。","若说无心法，此光如有情。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"天气":["写雨"],"节日":["元宵节"]},"theme_conf":0.93},{"uid":"02304a34-5fd7-44fc-a781-9a1ed35a8a03","title":"秋风二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹巫山，上牢下牢修水关。","吴樯楚柁牵百丈，暖向神都寒未还。","要路何日罢长戟，战自青羌连百蛮。","中巴不曾消息好，暝传戍鼓长云间。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cpbba50c920e98dd","title":"南浦","author":"孔夷","dynasty":"宋","section":"宋词","form":"词","paragraphs":["风悲画角，听单于、三弄落谯门。","投宿征骑，飞雪满孤村。","酒市渐闲灯火，正敲窗、乱叶舞纷纷。","送数声惊雁，下离烟水，嘹唳度寒云。","好在半胧溪月，到如今、无处不销魂。","故国梅花归梦，愁损绿罗裙。","为问暗香闲艳，也相思、万点付啼痕。","算翠屏应是，两眉馀恨倚黄昏。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["雪","夜"],"cats":{"抒情":["离别","思念","思乡","伤感","孤独","怀古"],"天气":["写雪"]},"theme_conf":0.92},{"uid":"a0a22f26-bd2a-457b-8f7d-74add294e009","title":"九日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年登高郪县北，今日重在涪江滨。","苦遭白发不相放，羞见黄花无数新。","世乱郁郁久为客，路难悠悠常傍人。","酒阑却忆十年事，肠断骊山清路尘。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.76},{"uid":"de67de33-4490-4be1-accf-46965ae26d38","title":"杂曲歌辞 少年行二首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["连环羁玉声光碎，绿锦蔽泥虬卷高。","春风细雨走马去，珠落璀璀白𦋺袍。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"],"人生":["青春"]},"theme_conf":1.0},{"uid":"bb80e9ef-e078-4ae2-8502-7f344d5fc05d","title":"过蜀龙门","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["龙门非禹凿，诡怪乃天功。","西南出巴峡，不与众山同。","长窦亘五里，宛转复嵌空。","伏湍喣潜石，瀑水生轮风。","流水无昼夜，喷薄龙门中。","潭河势不测，藻葩垂彩虹。","我行当季月，烟景共舂融。","江关勤亦甚，𪩘崿意难穷。","势将息机事，炼药此山东。"],"theme":"咏史怀古","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["山","夜","月"],"cats":{"抒情":["怀古"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"1318e5a7-c894-4bb0-a1aa-f5760e0b7f63","title":"旅馆雪晴又覩新月众兴所感因成杂言","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寥寥深夜雪初晴，楼上云开月渐明。","池中片影依稀见，帘外清光远近生。","皎皎晴空疑破镜，广庭积素偏相映。","珠帘卷却光更深，玉指持来色逾净。","梦觉青楼最可怜，婵娟素魄满寒天。","天地寥寥同一色，秦淮楚江无限极。","归鸿断猨何处声，深闺旅馆遥相忆。","长安五侯华阁开，嘉宾列坐倾金罍。","赏明月，玩流雪，纤手蛾眉座中设。","清歌一声无断绝，夜已央，乐未阑。","狐裘兽炭不知寒，珠环翠珮声珊珊。","履舃纷纭桂袖攒，朱颜倚醉尽君欢。","人生少年全不久，相看且劝杯中酒。","丈夫富贵自有期，映雪读书徒白首。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["孤寂"],"scene":["雪","月"],"cats":{"抒情":["思乡"],"天气":["写雪","月亮"],"人生":["青春","读书"],"节日":["中秋节"]},"theme_conf":0.557},{"uid":"d3e70d45-82d5-44a7-a20e-cbb2c762d857","title":"夜坐吟","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马蹄谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞梢出东南涯，陆郎去矣乘班骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"272095aa-4f8c-4674-b704-e626118c81db","title":"铜官渚守风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不夜楚帆落，避风湘渚间。","水耕先浸草，春火更烧山。","早泊云物晦，逆行波浪悭。","飞来双白鹤，过去杳难攀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","夜"],"cats":{"天气":["写风"]},"theme_conf":1.0},{"uid":"cpdfe6d2cd46549c","title":"夏云峰","author":"仲殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天阔云高，溪横水远。","晚日寒生轻晕。","闲阶静、杨花渐少，朱门掩、莺声犹嫩。","悔匆匆、过却清明，旋占得馀芳，已成幽恨。","都几日阴沈，连宵慵困。","起来韶华都尽。","怨入双眉闲斗损。","乍品得情怀，看承全近。","深深态、无非自许。","厌厌意、终羞人间。","争知道、梦里蓬莱，待忘了馀香，时传音信。","纵留得莺花，东风不住，也则眼前愁闷。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":["沉郁","冲淡"],"mood":"愁怨","mood2":["恬淡"],"scene":["夏","花","清明","春","山"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","夏天"],"天气":["写云"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"66711c88-d15e-4440-a51c-03447a294dee","title":"秋中雨田园即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["漠漠重云暗，萧萧密雨垂。","为霖淹古道，积日满荒陂。","五稼何时获，孤村几户炊。","乱流发通圃，腐叶著秋枝。","暮爨新樵湿，晨渔旧浦移。","空余去年菊，花发在东篱。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雨","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"],"生活":["乡村","田野"]},"theme_conf":0.762},{"uid":"cpeb9e1e9caece13","title":"永遇乐","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月如霜，好风如水，清景无限。","曲港跳鱼，圆荷泻露，寂寞无人见。","如三鼓，铿然一叶，黯黯梦云惊断。","夜茫茫，重寻无处，觉来小园行遍。","天涯倦客，山中归路，望断故园心眼。","燕子楼空，佳人何在，空锁楼中燕。","古今如梦，何曾梦觉，但有旧欢新怨。","异时对，黄楼夜景，为余浩叹。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["月","楼","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.763},{"uid":"11964ccb-20f2-4a42-9ae2-d6a3e11ef7dc","title":"登刘宾客高斋","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["能以功成疎宠位，不将心赏负云霞。","林间客散孙弘阁，城上山宜绮季家。","蝴蝶晴连池岸草，黄鹂晚出柳园花。","日陪鲤也趋文苑，谁道门生隔绛纱。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["园林"],"cats":{"抒情":["思乡"],"天气":["写云"],"人物":["老师"]},"theme_conf":0.581},{"uid":"3c004054-61d3-442e-b15c-07ee460b9cfe","title":"天门谷题孙逸人石壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["崖石乱流处，竹深斜照归。","主人卧磻石，心耳涤清晖。","春雷近作解，空谷半芳菲。","云栋彩虹宿，药圃蝴蝶飞。","恶嚣慕嘉遯，几夜瞻少微。","相见竟何说，忘情同息机。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["泰山"],"天气":["彩虹"]},"theme_conf":0.465},{"uid":"5c154375-4cf7-4a77-b792-b211e2dc4842","title":"海上卧病寄王临","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["离客穷海阴，萧辰归思结。","一随浮云滞，几怨黄鹄别。","妙年即沈疴，生事多所阙。","劒中负明义，枕上惜玄发。","之子良史才，华簪偶时哲。","相思千里道，愁望飞鸟绝。","岁暮冰雪寒，淮湖不可越。","百年去心虑，孤影守薄劣。","独余慕侣情，金石无休歇。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["冬","雪"],"cats":{"抒情":["离别","思念","伤感","孤独"],"天气":["写雪"]},"theme_conf":0.83},{"uid":"b9282ea7-ac4d-4f66-a960-517e1420d1b7","title":"赋得归云送李山人归华山","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秀色横千里，归云积几重。","欲依毛女岫，初卷少姨峰。","盖影随征马，衣香拂卧龙。","秪应函谷上，真气日溶溶。"],"theme":"送别","theme2":["山水田园","咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":0.339},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"e018d77b-84a8-4e85-b9af-d81845efe2a6","title":"苦雨奉寄陇西公兼呈王征士","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今秋乃淫雨，仲月来寒风。","群木水光下，万象云气中。","所思碍行潦，九里信不通。","悄悄素浐路，迢迢天汉东。","愿腾六尺马，背若孤征鸿。","划见公子面，超然欢笑同。","奋飞既胡越，局促伤樊笼。","一饭四五起，凭轩心力穷。","嘉蔬没混浊，时菊碎榛丛。","鹰隼亦屈猛，乌鸢何所蒙。","式瞻北邻居，取适南巷翁。","挂席钓川涨，焉知清兴终。"],"theme":"寄赠酬答","theme2":["送别","民生疾苦","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂","愁怨"],"scene":["雨"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"]},"theme_conf":0.93},{"uid":"d6631944-18f1-4767-a2d4-77b1516758cd","title":"保大五年元日大雪同太弟景遂汪王景逷齐王景逵进士李建勋中书徐铉勤政殿学士张义方登楼赋","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["珠帘高卷莫轻遮，往往相逢隔岁华。","春气昨宵飘律管，东风今日放梅花。","素姿好把芳姿掩，落势还同舞势斜。","坐有宾朋尊有酒，可怜清味属侬家。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["豪放","旷达"],"mood":"欢愉","mood2":[],"scene":["雪","楼","春","冬"],"cats":{"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.82},{"uid":"50da9443-962b-4d51-a2db-92084b98e1e4","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 八","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白赤虹，单见色无双。","如气冲天或横过，蚩尤旗号动戈鎗，起处必为殃。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"0f5874bf-3748-44c9-bc3a-be4a8c3eb2f6","title":"阁夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"],"theme":"边塞征战","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["夜"],"cats":{"抒情":["思乡","伤感"],"天气":["星星"],"人生":["战争"]},"theme_conf":0.425},{"uid":"a3e4aa0f-aba7-4024-a349-3c9fb23be270","title":"汉州月夕游房太尉西湖","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丞相鸣琴地，何年闭玉徽。","偶因明月夕，重敞故楼扉。","桃柳谿空在，芙蓉客暂依。","谁怜济川楫，长与夜舟归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋","月","江南"],"cats":{"抒情":["思乡"],"山水":["西湖"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"a28d04d1-9f9b-492e-8f1f-2d70542ffa27","title":"酬叶县刘明府避地庐山言怀诒郑录事昆季苟尊师兼见赠之","author":"吴筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["明哲良罕遇，遇君輙思齐。","挺生著天爵，自可析人珪。","河洛初沸腾，方期扫虹霓。","时命竟未合，安能亲鼓鼙。","从此罢飞凫，投簪辞割鸡。","驱车适南土，忠孝两不暌。","庐岳镇江介，于焉惬林栖。","入门披彩服，出谷杖红藜。","隐令旧闾里，而今复成跻。","郑公解簪绂，华萼曜松谿。","贤哉苟征君，灭迹为圃畦。","顾已成非薄，忝兹忘筌蹄。","相观对绿樽，逸思凌丹梯。","道泰我长往，时清君勿迷。","王孙且无归，芳草正萋萋。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花"],"cats":{"山水":["庐山"],"天气":["彩虹"],"植物":["叶子"]},"theme_conf":0.96},{"uid":"cpe17f558a5aa701","title":"洞仙歌","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["冰肌玉骨，自清凉无汗。","水殿风来暗香满。","绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。","起来携素手，庭户无声，时见疏星渡河汉。","试问夜如何，夜已三更，金波淡、玉绳低转。","但屈指、西风几时来，又不道、流年暗中偷换。"],"theme":"闺情宫怨","theme2":["游仙梦幻"],"style":"绮丽","style2":["冲淡","婉约"],"mood":"恬淡","mood2":[],"scene":["夜","月"],"cats":{"抒情":["闺怨"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.623},{"uid":"7af6841a-3381-426d-a811-4e1d133ba180","title":"正月十五夜闻京有灯恨不得观","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月色灯光满帝都，香车宝辇隘通衢。","身闲不睹中兴盛，羞逐乡人赛紫姑。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["元宵","月","夜"],"cats":{"抒情":["思乡"],"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.545},{"uid":"15a3131f-aaa2-4557-9233-aeceb9edbb63","title":"舟中夜雪有怀卢十四侍御弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔风吹桂水，朔雪夜纷纷。","暗度南楼月，寒深北渚云。","烛斜初近见，舟重竟无闻。","不识山阴道，听鸡更忆君。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["雪","夜","舟","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写风","写雪"]},"theme_conf":0.65},{"uid":"3b67a24e-33da-4a40-941a-e7a42931b390","title":"咏荆轲","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["燕秦不两立，太子已为虞。","千金奉短计，匕首荆卿趋。","穷年徇所欲，兵势且见屠。","微言激幽愤，怒目辞燕都。","朔风动易水，挥爵前长驱。","函首致宿怨，献田开版图。","炯然耀电光，掌握罔正夫。","造端何其锐，临事竟趑趄。","长虹吐白日，仓卒反受诛。","按劒赫凭怒，风雷助号呼。","慈父断子首，狂走无容躯。","夷城芟七族，台观皆焚污。","始期忧患弭，卒动灾祸枢。","秦皇本诈力，事与桓公殊。","奈何效曹子，实谓勇且愚。","世传故多谬，太史征无且。"],"theme":"咏史怀古","theme2":["咏物"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"天气":["写风","彩虹"]},"theme_conf":0.516},{"uid":"e43db4ab-925d-4cb0-b14a-d105ef6cd63c","title":"杂曲歌辞 昔昔盐 风月守空闺","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良人犹远戍，耿耿夜闺空。","绣户流宵月，罗帷坐晓风。","魂飞沙帐北，肠断玉关中。","尚自无消息，锦衾那得同。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["伤感","闺怨"],"天气":["写风","月亮"]},"theme_conf":0.818},{"uid":"4889a0b4-4921-4d09-bab3-b69ae5fb1f5b","title":"同辛衮州巢父虚副端岳相思献酬之作因纾归怀兼呈辛魏二院长杨长宁","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮角发高城，情人坐中起。","临觞不及醉，分散秋风里。","虽有明月期，离心若千里。","前欢反惆怅，后会还如此。","焉得夜淹留，一回终宴喜。","羇游复牵役，馆至重湖水。","早晚泛归舟，吾从数君子。"],"theme":"寄赠酬答","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["月","酒","园林"],"cats":{"抒情":["爱情","思念"],"天气":["月亮"],"人物":["父亲"]},"theme_conf":0.93},{"uid":"6bbd1c2c-8c43-4ffb-b7b3-506d74266cee","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"theme":"羁旅思乡","theme2":["节令风俗","亲情"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念","思乡"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.364},{"uid":"ef36b0a2-6327-47a2-b777-ccf669af3ebb","title":"大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知众壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝飏，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪𬬻。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹为客，蒙恩早厕儒。","廷争酬造化，朴直乞江湖。","滟滪险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"theme":"羁旅思乡","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":["沉郁","清新"],"mood":"欢愉","mood2":["悲怆","孤寂"],"scene":["江","鸟","春","舟","山"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"山水":["江河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.8},{"uid":"22099372-939e-4154-a175-15d5365ac21c","title":"奉酬乐天立秋夕有怀见寄","author":"李绅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深夜星汉静，秋风初报凉。","阶篁淅沥响，露叶参差光。","冰兔半升魄，铜壶微滴长。","薄帷乍飘卷，襟带轻摇飏。","此际昏梦清，斜月满轩房。","屣履步前楹，劒戟森在行。","重城宵正分，号鼓互相望。","独坐有所思，夫君鸾凤章。","天津落星河，一苇安可航。","龙泉白玉首，鱼服黄金装。","报国未知効，惟鹈徒在梁。","裴回顾戎旃，颢气生东方。","衰叶满栏草，斑毛盈镜霜。","羸牛未脱辕，老马强腾骧。","吟君白雪唱，慙媿巴人肠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.96},{"uid":"508e5a40-2ce9-41af-9bf5-7c58830b0fae","title":"端午日","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年佳节倍多情，老去谁知感慨生。","不効艾符趋习俗，但祈蒲酒话升平。","鬓丝日日添头白，榴锦年年照眼明。","千载贤愚同瞬息，几人湮没几垂名。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.83},{"uid":"cp9ea58780dad3ab","title":"贺新郎","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湛湛长空黑。","更那堪、斜风细雨，乱愁如织。","老眼平生空四海，赖有高楼百尺。","看浩荡、千崖秋色。","白发书生神州泪，尽凄凉、不向牛山滴。","追往事，去无迹。","少年自负凌云笔。","到而今、春华落尽，满怀萧瑟。","常恨世人新意少，爱说南朝狂客。","把破帽、年年拈出。","若对黄花孤负酒，怕黄花、也笑人岑寂。","鸿北去，日西匿。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["雨"],"cats":{"抒情":["思乡","伤感","孤独"],"天气":["写雨"]},"theme_conf":0.65},{"uid":"af55f487-b2a8-4e2c-a3ab-406cd7a450fb","title":"春日即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["邻里朝光徧，披衣夜醉醒。","庖厨非旧火，林木发新青。","接果移天性，疎泉逐地形。","清明来几日，戴胜已堪听。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"f1177b2a-c00f-4d1a-a8f8-95e33bd6c4f5","title":"秋风二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹我衣，东流之外西日微。","天清小城捣练急，石古细路行人稀。","不知明月为谁好，早晚孤帆他夜归。","会将白发倚庭树，故园池台今是非。"],"theme":"羁旅思乡","theme2":["送别"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","园林","月"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风","月亮"]},"theme_conf":0.567},{"uid":"cp7d9065abd6353a","title":"玉楼春","author":"严仁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春风只在园西畔。","荠菜花繁胡蝶乱。","冰池晴绿照还空，香径落红吹已断。","意长翻恨游丝短。","尽日相思罗带缓。","宝奁明月不欺人，明日归来君试看。"],"theme":"爱情相思","theme2":["边塞征战"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.577},{"uid":"6ed3a7f5-c68a-40ba-b28f-50ebbfac1091","title":"相和歌辞 春江花月夜二首 二","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["交甫怜瑶佩，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["月","江","春","花","夜"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.65},{"uid":"fd63be75-f6b3-491d-91d5-04179194f1aa","title":"初春登楼即目观作述怀","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凭轩俯兰阁，眺瞩散灵襟。","绮峰含翠雾，照日蕊红林。","镂丹霞锦岫，残素雪斑岑。","拂浪堤垂柳，娇花鸟续吟。","连甍岂一拱，众干如千寻。","明非独材力，终藉栋梁深。","弥怀矜乐志，更惧戒盈心。","媿制劳居逸，方规十产金。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","春","花"],"cats":{"抒情":["孤独","怀古"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.565},{"uid":"b6985205-7423-47bf-ad4d-19e2ee4eaed0","title":"夜闻觱篥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜闻觱篥沧江上，衰年侧耳情所向。","邻舟一听多感伤，塞曲三更歘悲壮。","积雪飞霜此夜寒，孤灯急管复风湍。","君知天地干戈满，不见江湖行路难。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["悲怆","慷慨"],"scene":["夜"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"9b5c9844-6e46-4d8d-8714-bd7c23382376","title":"三日梨园侍宴","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九重驰道出，三巳禊堂开。","画鹢中流动，青龙上苑来。","野花飘御座，河柳拂天杯。","日晚迎祥处，笙镛下帝台。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["园林"],"cats":{"天气":["太阳"],"植物":["梨花"]},"theme_conf":0.95},{"uid":"9cf2d943-e52c-4406-bd53-03f686f4abb7","title":"和都官苗员外秋夜省直对雨简诸知己","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多雨南宫夜，仙郎寓直时。","漏长丹凤阙，秋冷白云司。","萤影侵堦乱，鸿声出苑迟。","萧条人吏散，小谢有新诗。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋","雨"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"78975868-daef-40f6-89f2-1aa8b5308c55","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已愁花落荒岩底，复恨根生乱石间。","几度欲移移不得，天教抛掷在深山。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","花","月","冬","夏"],"cats":{"抒情":["伤感","孤独","感恩"],"四季":["夏天","冬天"],"天气":["月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.475},{"uid":"9c00d63a-b248-45a7-ad8b-d40f0c52b857","title":"相和歌辞 陇西行","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十里一走马，五里一扬鞭。","都护军书至，匈奴围酒泉。","关山正飞雪，烽戍断无烟。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"]},"theme_conf":0.674},{"uid":"c269dec4-e6e7-40b3-b1c5-b371d0450eb0","title":"怀素上人草书歌","author":"窦冀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狂僧挥翰狂且逸，独任天机摧格律。","龙虎惭因点画生，雷霆却避锋铓疾。","鱼牋娟素岂不贵，只嫌局促儿童戏。","粉壁长廊数十间，兴来小豁胸襟气。","长幼集，贤豪至，枕糟藉曲犹半醉。","忽然绝叫三五声，满壁纵横千万字。","吴兴张老尔莫颠，叶县公孙我何谓。","如熊如罴不足比，如虺如蛇不足拟。","涵物为动鬼神泣，狂风入林花乱起。","殊形怪状不易说，就中惊燥尤枯绝。","边风杀气同惨烈，崩槎卧木争摧折。","塞草遥飞大漠霜，胡天乱下阴山雪。","偏看能事转新奇，郡守王公同赋诗。","枯藤劲铁媿三舍，骤雨寒猨惊一时。","此生绝艺人莫测，假此常为护持力。","连城之璧不可量，五百年知草圣当。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"孤寂","mood2":["悲怆"],"scene":["雪","塞外"],"cats":{"抒情":["孤独"],"天气":["写风","写雨"],"人物":["儿童"],"生活":["边塞"]},"theme_conf":0.773},{"uid":"cpda401b77a73d37","title":"贺新郎","author":"叶梦得","dynasty":"宋","section":"宋词","form":"词","paragraphs":["睡起啼莺语。","掩青苔、房栊向晚，乱红无数。","吹尽残花无人见，惟有垂杨自舞。","渐暖霭、初回轻暑。","宝扇重寻明月影，暗尘侵、尚有乘鸾女。","惊旧恨，遽如许。","江南梦断横江渚。","浪黏天、葡萄涨绿，半空烟雨。","无限楼前沧波意，谁采苹花寄取。","但怅望、兰舟容与。","万里云帆何时到，送孤鸿、目断千山阻。","谁为我，唱金缕。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新","豪放"],"mood":"孤寂","mood2":[],"scene":["月","舟","江","江南","花","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.659},{"uid":"d0be6b0d-6be7-4235-9db2-55ab10e437fd","title":"月宫词","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["宫中月明何所似，如积如流满田地。","逈过前殿曾学眉，回照长门惯催泪。","昭阳昨夜秋风来，绮阁金铺情影开。","藻井浮花共陵乱，玉阶零露相裴回。","稍映明河泛仙驭，满牕犹在更衣处。","管弦回烛无限情，环珮凭栏不能去。","皎皎苍苍千里同，穿烟飘叶九门通。","珠帘欲卷畏成水，瑶席初陈惊似空。","复值君王事欢宴，宫女三千一时见。","飞盖愁看素晕低，称觞愿踏清辉遍。","江上无云夜可怜，冒沙披浪自婵娟。","若共心赏风流夜，那比高高太液前。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":["愁怨"],"scene":["月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"4365fdc6-9e89-489c-abe1-4eda95a85062","title":"杂曲歌辞 升天行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["身不沈，骨不重，驱青鸾，驾白凤。","幢盖飘飘入冷空，天风瑟瑟星河动。","瑶阙参差阿母家，楼台戏闭凝彤霞。","五三仙子乘龙车，堂前碾烂蟠桃花。","回头却顾蓬山顶，一点浓岚在深井。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"天气":["星星"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"571a9d34-1572-42f4-bb50-96c4d88974b4","title":"春日忆李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白也诗无敌，飘然思不群。","清新庾开府，俊逸鲍参军。","渭北春天树，江东日暮云。","何时一尊酒，重与细论文。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"294bc7b2-b4f8-4a53-be17-a40ded4afd1a","title":"白雪歌送武判官归京","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["北风卷地白草折，胡天八月即飞雪。","忽然一夜春风来，千树万树梨花开。","散入珠帘湿罗幕，狐裘不煖锦衾薄。","将军角弓不得控，都护铁衣冷难着。","瀚海阑干百丈冰，愁云黪淡万里凝。","中军置酒饮归客，胡琴琵琶与羌笛。","纷纷暮雪下辕门，风掣红旗冻不翻。","轮台东门送君去，去时雪满天山路。","山回路转不见君，雪上空留马行处。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["离别","伤感"],"天气":["写风","写雪"]},"theme_conf":0.33},{"uid":"06bcd5bc-f822-48b9-9204-08e3eff83f4d","title":"雨中对后簷丛竹","author":"崔元翰","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["含风摇砚水，带雨拂墙衣。","乍似秋江上，渔家半掩扉。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"55b11522-995c-490d-ada6-d82404b72473","title":"相和歌辞 大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["二八婵娟大堤女，开𬬻相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠蛾。","珍簟华灯夕阳后，当𬬻理瑟矜纤手。","月落星微五鼓声，春风摇荡窗前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别","闺怨"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.62},{"uid":"3f218bb2-5f46-423d-869b-fa166ac8ba49","title":"秋灯对雨寄史近崔积","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["坐听宫城传晚漏，起看衰叶下寒枝。","空庭绿草结离念，细雨黄花赠所思。","蟋蟀已惊良节度，茱萸偏忆故人期。","相逢莫厌尊前醉，春去秋来自不知。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["雨","秋"],"cats":{"抒情":["友情","思念"],"四季":["秋天"],"天气":["写雨"],"节日":["元宵节","重阳节"]},"theme_conf":0.95},{"uid":"afa0d6db-b93a-4e96-aae9-59ec920eb6de","title":"杂曲歌辞 游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故巢思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰晖百年内，惟愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何艰哉？北斗不可斟。","夜晴星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蜻蛚催寒砧。","立身计几误，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧因古今。","胡为不归欤，孤负丘中琴。","腰下是何物？牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山杳岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾霄汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分堙沈。","层城发云韶，玉府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋","江","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.291},{"uid":"32c6a206-1a90-452e-a032-19a7665bceba","title":"风雨看舟前落花戏为新句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江上人家桃树枝，春寒细雨出疎篱。","影遭碧水潜勾引，风妒红花却倒吹。","吹花困癫傍舟檝，水光风力俱相怯。","赤憎轻薄遮入怀，珍重分明不来接。","湿久飞迟半日高，萦沙惹草细于毛。","蜜蜂蝴蝶生情性，偷眼蜻蜓避百劳。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"清新","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["雨","舟"],"cats":{"天气":["写风","写雨"]},"theme_conf":0.556},{"uid":"0949fe2a-aadf-4cd4-b1c3-25fcdaecdb96","title":"积雨辋川庄作","author":"王维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["积雨空林烟火迟，蒸藜炊黍饷东菑。","漠漠水田飞白鹭，阴阴夏木啭黄鹂。","山中习静观朝槿，松下清斋折露葵。","野老与人争席罢，海鸥何事更相疑。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":1.0},{"uid":"2188f98e-d5f0-4740-b94b-e1497a3619ee","title":"黄鹤楼","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔人已乘白云去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，春草萋萋鹦鹉洲。","日暮乡关何处是，烟波江上使人愁。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","江","鸟"],"cats":{"抒情":["思乡","伤感","怀古"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.443},{"uid":"a4856804-965c-40d0-a54d-5379ace1d95c","title":"陪王使君晦日泛江就黄家亭子二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山豁何时断，江平不肯流。","稍知花改岸，始验鸟随舟。","结束多红粉，欢娱恨白头。","非君爱人客，晦日更添愁。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.634},{"uid":"cpec064f31d7955a","title":"青门引・青门饮","author":"张先","dynasty":"宋","section":"宋词","form":"词","paragraphs":["乍暖还轻冷。","风雨晚来方定。","庭轩寂寞近清明，残花中酒，又是去年病。","楼头画角风吹醒。","入夜重门静。","那堪更被明月，隔墙送过秋千影。"],"theme":"闺情宫怨","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","雨","清明","楼","夜"],"cats":{"抒情":["孤独","闺怨"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.66},{"uid":"feb085bc-e461-4a18-b787-e831e3ef1885","title":"宿庐山赠白鹤观刘尊师","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苍苍五老雾中坛，杳杳三山洞里官。","手护昆仑象牙简，心推霹雳枣枝盘。","春飞雪粉如毫润，晓漱琼膏冰齿寒。","渐恨流年筋力少，惟思露冕事星冠。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["清新","雄浑"],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"山水":["庐山"],"天气":["写雪"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"e0b629da-76cc-4223-98b8-25fad7f63656","title":"忆寿春废虎坑余以春二月至郡主吏举所职称霍山多虎每岁采茶为患择肉于人至春常修陷穽数十所勒猎者采其皮睛余悉除罢之是岁虎不复为害至余去郡三载","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["匪将履尾求兢惕，那效探雏所患争。","当路绝群尝诫暴，为猫驱狝亦先迎。","每推至化宣余力，岂用潜机害尔生。","休逐豺狼止贪戾，好为仁兽答皇明。"],"theme":"咏物","theme2":["边塞征战","送别","山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"食物":["写茶"]},"theme_conf":0.65},{"uid":"15a04b03-7a41-4faa-9e46-c8d6fb228bb0","title":"涉沅潇","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["屈原死处潇湘阴，沧浪淼淼云沈沈。","蛟龙长怒虎长啸，山木翛翛波浪深。","烟横日落惊鸿起，山映余霞杳千里。","鸿叫离离入暮天，霞消漠漠深云水。","水灵江暗扬波涛，鼋鼍动荡风骚骚。","行人愁望待明月，星汉沈浮𩲒鬼号。","屈原尔为怀王没，水府通天化灵物。","何不驱雷击电除奸邪，可怜空作沈泉骨。","举杯沥酒招尔魂，月影滉漾开乾坤。","波白水黑山隐见，汨罗之上遥昏昏。","风帆候晓看五两，戍鼓冬冬远山响。","潮满江津猨鸟啼，荆夫楚语飞蛮桨。","潇湘岛浦无人居，风惊水暗惟鲛鱼。","行来击棹独长叹，问尔精魄何所如。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["端午","月","酒","舟","江"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["端午节"]},"theme_conf":0.58},{"uid":"c5b74274-de21-482b-ae7a-b0d8200bbb18","title":"琴曲歌辞 湘妃","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帝子不可见，秋风来暮思。","婵娟湘江月，千载空蛾眉。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","秋","月","江"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"8fca99c7-a467-43a6-8893-4f2151ec902a","title":"赋得浦外虹送人","author":"陈润","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日影化为虹，弯弯出浦东。","一条微雨后，五色片云中。","轮势随天度，桥形跨海通。","还将饮水处，持送使车雄。"],"theme":"送别","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.641},{"uid":"2ac203a8-6e70-4b78-ad75-9acacae9b04a","title":"相和歌辞  北上行","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北上何所苦，北上缘太行。","磴道盘且峻，巉岩凌穹苍。","马足蹶侧石，车轮摧高冈。","沙尘接幽州，烽火连朔方。","杀气毒劒戟，严风裂衣裳。","奔鲸夹黄河，凿齿屯洛阳。","前行无归日，返顾思旧乡。","惨戚冰雪里，悲号绝中肠。","尺布不掩体，皮肤剧枯桑。","汲水涧谷阻，采薪陇坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，饥饮零露浆。","叹此北上苦，停骖为之伤。","何日王道平？开颜覩天光。"],"theme":"边塞征战","theme2":["民生疾苦","山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["秋","冬","江","雪"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"山水":["黄河"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.296},{"uid":"b0f61bf4-5c31-4875-a33f-97de1a1560d2","title":"浪淘沙九首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","七夕"],"cats":{"抒情":["思乡"],"山水":["黄河"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.551},{"uid":"86f844a6-969b-4af7-be73-b1c12c0cd7fb","title":"九日五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["重阳独酌杯中酒，抱病起登江上台。","竹叶于人既无分，菊花从此不须开。","殊方日落玄猨哭，旧国霜前白雁来。","弟妹萧条各何往，干戈衰谢两相催。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["重阳","酒"],"cats":{"抒情":["思乡","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.8},{"uid":"b27b13fb-d8e2-4231-a109-65068e60437d","title":"奉寄中书王舍人","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["腰金载笔谒承明，至道安禅得此生。","西掖几年纶綍贵，东山遥夜薜萝情。","风传刻漏星河曙，月上梧桐雨露清。","圣主好文谁为荐，闭门空赋子虚成。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","月","雨"],"cats":{"天气":["星星"]},"theme_conf":0.85},{"uid":"e1863f14-2d00-47ca-bb8c-3996c3bacb2a","title":"相和歌辞 上云乐","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["金天之西，白日所没。","康老胡雏，生彼月窟。","巉岩仪容，[戌]削风骨。","碧玉炅炅双目瞳，黄金拳拳两鬓红。","华盖垂下睫，嵩岳临上唇。","不覩谲诡貌，岂知造化神。","大道是文康之严父，元气乃文康之老亲。","抚顶弄盘古，推车转天轮。","云见日月初生时，铸冶火精与水银。","阳乌未出谷，顾兔半藏身。","女娲戏黄土，团作愚下人。","散在六合间，蒙蒙如沙尘。","生死了不尽，谁明此胡是仙真。","西海栽若木，东溟植扶桑。","别来几多时，枝叶万里长。","中国有七圣，半路颓鸿荒。","陛下应运起，龙飞入咸阳。","赤眉立盆子，白水兴汉光。","叱咤四海动，洪涛为簸扬。","举足蹋紫微，天关自开张。","老胡感至德，东来进仙倡。","五色师子，九苞凤凰。","是老胡鸡犬，鸣舞飞帝乡。","淋漓飒沓，进退成行。","能胡歌，献汉酒。","跪双膝，并两肘。","散花指天举素手，拜龙颜，献圣寿。","北斗戾，南山摧。","天子九九八十一[万]岁，长倾万岁杯。"],"theme":"山水田园","theme2":["游仙梦幻","边塞征战"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","山","月"],"cats":{"天气":["写云"]},"theme_conf":0.385},{"uid":"ab4e15ff-7244-4bd0-860e-4622b1feca27","title":"中秋夜登楼望月寄人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西楼见月似江城，脉脉悠悠倚槛情。","万里此情同皎洁，一年今日最分明。","初惊桂子从天落，稍误芦花带雪平。","知称玉人临水见，可怜光彩有余清。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["月","中秋","楼","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"6dbed00f-b5d4-4276-8de1-d65054b3d4a7","title":"和程员外春日东郊即事","author":"包何","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官休浣怜迟日，野老欢娱为有年。","几处折花惊蝶梦，数家留叶待蚕眠。","藤垂宛地萦珠履，泉迸侵堦浸绿钱。","直到闭关朝谒去，莺声不散柳含烟。"],"theme":"民生疾苦","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"f0d0412b-b79c-4643-a730-f980bf7e088a","title":"秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南征为客久，西候别君初。","岁满归凫舄，秋来把雁书。","荆门留美化，姜被就离居。","闻道和亲人，垂名报国余。","连枝不日竝，八座几时除。","往者胡星孛，恭惟汉网疎。","风尘相澒洞，天地一丘墟。","殿瓦鸳鸯坼，宫帘翡翠虚。","钩陈摧徼道，枪櫐失储胥。","文物陪巡守，亲贤病拮据。","公时呵䝟貐，首唱却鲸鱼。","势惬宗萧相，材非一范雎。","尸填太行道，血走浚仪渠。","滏口师仍会，函关愤已摅。","紫微临大角，皇极正乘舆。","赏从频峨冕，殊私再直庐。","岂惟高卫霍，曾是接应徐。","降集飜翔凤，追攀绝众狙。","侍臣双宋玉，战策两穰苴。","鉴澈劳悬镜，荒芜已荷锄。","向来披述作，重此忆吹嘘。","白发甘凋丧，青云亦卷舒。","经纶功不朽，跋涉体何如。","应讶耽湖橘，常餐占野蔬。","十年婴药饵，万里狎樵渔。","扬子淹投阁，邹生惜曳裾。","但惊飞熠耀，不记改蟾蜍。","烟雨封巫峡，江淮略孟诸。","汤池虽险固，辽海尚填淤。","努力输肝胆，休烦独起予。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["离别","爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.532},{"uid":"18a2aaed-39a3-4ec2-a730-4479ec0b94ec","title":"孤山寺遇雨","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["拂波云色重，洒叶雨声繁。","水鹭双飞起，风荷一向翻。","空蒙连北岸，萧飒入东轩。","或拟湖中宿，留船在寺门。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.564},{"uid":"a4bf89a1-d3e1-418c-abdd-25129c326348","title":"巫山神女庙","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["巫山十二郁苍苍，片石亭亭号女郎。","晓雾乍开疑卷幔，山花欲谢似残妆。","星河好夜闻清佩，云雨归时带异香。","何事神仙九天上，人间来就楚襄王。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["雄浑"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["星星"]},"theme_conf":1.0},{"uid":"be118ff0-566d-466d-ac07-0de6e6493419","title":"雨中宿义兴寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["遥夜宿东林，虫声阶草深。","高风初落叶，多雨未归心。","家国身犹负，星霜鬓已侵。","沧洲纵不去，何处有知音。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["友情","思乡"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.658},{"uid":"1168c377-42c2-4c1f-a283-1ba089165dab","title":"秋日荆南述怀三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔承推奖分，媿匪挺生材。","迟暮宫臣忝，艰危衮职陪。","扬镳随日驭，折槛出云台。","罪戾宽犹活，干戈塞未开。","星霜玄鸟变，身世白驹催。","伏枕因超忽，扁舟任往来。","九钻巴噀火，三蛰楚祠雷。","望帝传应实，昭王问不回。","蛟螭深作横，豺虎乱雄猜。","素业行已矣，浮名安在哉？","琴乌曲怨愤，庭鹤舞摧颓。","秋雨漫湘水，阴风过岭梅。","苦摇求食尾，常曝报恩顋。","结舌防谗柄，探肠有祸胎。","苍茫步兵哭，展转仲宣哀。","饥籍家家米，愁征处处杯。","休为贫士叹，任受众人咍。","得丧初难识，荣枯划易该。","差池分组冕，合沓起蒿莱。","不必伊周地，皆知屈宋才。","汉庭和异域，晋史坼中台。","霸业寻常体，忠臣忌讳灾。","群公纷戮力，圣虑窅裴回。","数见铭钟鼎，真宜法斗魁。","愿闻锋镝铸，莫使栋梁摧。","盘石圭多翦，凶门毂少推。","垂旒资穆穆，祝网但恢恢。","赤雀飜然至，黄龙讵假媒。","贤非梦傅野，隐类凿颜坯。","自古江湖客，冥心苦死灰。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏史怀古","讽喻刺世"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","园林","舟"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"人生":["时光","战争"]},"theme_conf":0.95},{"uid":"cp8bb678591e441b","title":"伴云来・天香","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["烟络横林，山沈远照，逦迤黄昏钟鼓。","烛映帘栊，蛩催机杼，共苦清秋风露。","不眠思妇，齐应和、几声砧杵。","惊动天涯倦宦，岁华行暮。","当年酒狂自负。","谓东君、已春相付。","流浪征骖北道，客墙南浦。","幽恨无人晤语。","赖明月曾知旧游处。","好伴云来，还将梦去。"],"theme":"羁旅思乡","theme2":["民生疾苦","送别"],"style":"豪放","style2":["婉约","沉郁"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["月","秋"],"cats":{"抒情":["离别","思乡","孤独"],"四季":["秋天"],"天气":["写云","月亮"]},"theme_conf":0.286},{"uid":"9482c243-95f3-4929-a211-9081efcc386d","title":"一百五日夜对月","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无家对寒食，有泪如金波。","斫却月中桂，清光应更多。","仳离放红蘂，想像嚬青蛾。","牛女漫愁思，秋期犹渡河。"],"theme":"爱情相思","theme2":["送别"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["寒食节","七夕节"]},"theme_conf":0.86},{"uid":"1a2571ec-f313-41ac-9a3b-695ebd446b8d","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 七","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓见，更或似弓形。","有若晕来如断续，兵兴五日定（辛本、川本作「便」）回程。","久住必灾成。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp0ebe2ac2d276d9","title":"绣鸾凤花犯・花犯","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚江湄，湘娥乍见，无言洒清泪。","淡然春意。","空独倚东风，芳思谁寄。","凌波路冷秋无际。","香云随步起。","谩记得，汉宫仙掌，亭亭明月底。","冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。","春思远，谁叹赏、国香风味。","相将共、岁寒伴侣。","小窗净、沈烟熏翠袂。","幽梦觉，涓涓清露，一枝灯影里。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":["绮丽","冲淡"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春","月","冬"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天","冬天"],"天气":["月亮"]},"theme_conf":0.588},{"uid":"13d43a14-988d-48a8-86f5-c1b6fa3baced","title":"奉和幽山雨后应令","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["肃城邻上苑，黄山迩桂宫。","雨歇连峰翠，烟开竟野通。","排虚翔戏鸟，跨水落长虹。","日下林全暗，云收岭半空。","山泉鸣石涧，地籁响岩风。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"天气":["写雨","彩虹"]},"theme_conf":0.96},{"uid":"9a85b1aa-f7e3-46c6-9d47-c032a38ee885","title":"桃源行","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渔舟何招招，浮在武陵水。","拖纶掷饵信流去，误入桃源行数里。","清源寻尽花绵绵，踏花觅径至洞前。","洞门苍黑烟雾生，暗行数步逢虚明。","俗人毛骨惊仙子，争来致词何至此。","须臾皆破冰雪颜，笑言委曲问人间。","因嗟隐身来种玉，不知人世如风烛。","筵羞石髓劝客餐，灯𦶟松脂留客宿。","鸡声犬声遥相闻，晓色葱茏开五云。","渔人振衣起出户，满庭无路花纷纷。","翻然恐失乡悬处，一息不肯桃源住。","桃花满溪水似镜，尘心如垢洗不去。","仙家一出寻无踪，至今流水山重重。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","雪","舟"],"cats":{"天气":["写雪"],"植物":["桃花"]},"theme_conf":0.664},{"uid":"36e09cb4-4fb7-48be-b6c6-c9bd906d9331","title":"辋川集 竹里馆","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["独坐幽篁里，弹琴复长啸。","深林人不知，明月来相照。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"植物":["竹子"]},"theme_conf":0.86},{"uid":"41815024-acd3-414d-9520-a00f0ceb3edd","title":"上韦左相二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤历轩辕纪，龙飞四十春。","八荒开寿域，一气转洪钧。","霖雨思贤佐，丹青忆老臣。","应图求骏马，惊代得麒麟。","沙汰江河浊，调和鼎鼐新。","韦贤初相汉，范叔已归秦。","盛业今如此，传经固绝伦。","豫樟深出地，沧海阔无津。","北斗司喉舌，东方领搢绅。","持衡留藻鉴，听履上星辰。","独步才超古，余波德照邻。","聪明过管辂，尺牍倒陈遵。","岂是池中物，由来席上珍。","庙堂知至理，风俗尽还淳。","才杰俱登用，愚蒙但隐沦。","长卿多病久，子夏索居频。","回首驱流俗，生涯似众人。","巫咸不可问，邹鲁莫容身。","感激时将晚，苍茫兴有神。","为公歌此曲，涕泪在衣巾。"],"theme":"题画咏艺","theme2":[],"style":"雄浑","style2":["沉郁","豪放"],"mood":"相思","mood2":["孤寂"],"scene":["雨","江"],"cats":{"抒情":["思念","孤独"],"天气":["星星"]},"theme_conf":1.0},{"uid":"c8bae0f0-12c6-4d6c-a35d-7077217cfdea","title":"南邻","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["锦里先生乌角巾，园收芋粟不全贫。","惯看宾客儿童喜，得食阶除鸟雀驯。","秋水才深四五尺，野航恰受两三人。","白沙翠竹江村暮，相对柴门月色新。"],"theme":"寄赠酬答","theme2":["山水田园","送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["月","夜"],"cats":{"天气":["月亮"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.72},{"uid":"2e743a29-04ae-416e-a014-6da19281a515","title":"雪后宿王纯池州草堂","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宿君湖上宅，琴韵静参差。","夜雪入秋浦，孤城连贵池。","流年看共老，衔酒发中悲。","良会应难再，晨鸡自有期。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["时光"]},"theme_conf":0.72},{"uid":"0db42110-bda6-490a-b3e0-61a5dfffad79","title":"江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["楼上炎天冰雪生，高飞燕雀贺新成。","碧窗宿雾蒙蒙湿，朱栱浮云细细轻。","杖钺褰帷瞻具美，投壶散帙有余清。","自公多暇延参佐，江汉风流万古情。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["婉约"],"mood":"惆怅","mood2":[],"scene":["楼","江"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"690ec16d-1c00-4f82-afe0-98e4dd46ead0","title":"月三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["并照巫山出，新窥楚水清。","羁栖愁里见，二十四回明。","必验升沈体，如知进退情。","不违银汉落，亦伴玉绳横。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["月","七夕"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"6bb1ee39-265a-4c53-a5b4-311b2e65429c","title":"和荅弟志和渔父歌","author":"张松龄","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乐是风波钓是闲，草堂松径已胜攀。","太湖水，洞庭山，狂风浪起且须还。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["江"],"cats":{"天气":["写风"],"人物":["父亲"],"人生":["梦想"]},"theme_conf":0.598},{"uid":"d9aa05ba-6c7d-4ebd-9401-5edd412f9b93","title":"轻薄行","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹄，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沉月上且鬬鸡，醉来莫问天高低。","伯阳道德何唾咦，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"652f32ba-492d-4b39-9216-aca92a6e9370","title":"相和歌辞 当来日大难","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["当来日大难行，前有坂，后有坑，大梁侧，小梁倾，两轴相绞，两轮相撑，大牛竖，小牛横，乌啄牛背，足跌力狞。","当来日大难行，太行虽险，险可使平。","轮轴自挠，牵制不停。","泥潦渐久，荆棘旋生。","行必不得，不如不行。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":["幽峭"],"mood":"惆怅","mood2":[],"scene":[],"cats":{"天气":["太阳"]},"theme_conf":0.82},{"uid":"04c4e10d-6c09-4fc2-a702-b55dbba16ee4","title":"喜雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春旱天地昏，日色赤如血。","农事都已休，兵戈况骚屑。","巴人困军须，恸哭厚土热。","沧江夜来雨，真宰罪一雪。","谷根小苏息，沴气终不灭。","何由见宁岁，解我忧思结。","峥嵘群山云，交会未断绝。","安得鞭雷公，滂沱洗吴越。"],"theme":"边塞征战","theme2":["山水田园"],"style":"沉郁","style2":["雄浑"],"mood":"悲怆","mood2":["欢愉"],"scene":["雨","江南"],"cats":{"天气":["写雨"],"人生":["战争"]},"theme_conf":0.522},{"uid":"de6b7e3d-03cd-4daa-bdc2-7fb820fda441","title":"出塞二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"d1ba29c5-333c-4b5d-978f-d5bfdf29a89b","title":"左丞相说右丞相璟太子少傅乾曜同日上官命宴东堂赐诗","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["赤帝收三杰，黄轩举二臣。","由来丞相重，分掌国之钧。","我有握中璧，双飞席上珍。","子房推道要，仲子讶风神。","复辍台衡老，将为调护人。","鹓鸾同拜日，车骑拥行尘。","乐聚南宫宴，觞连北斗醇。","俾予成百揆，垂拱问彝伦。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","酒"],"cats":{"天气":["太阳"]},"theme_conf":0.95},{"uid":"b5246cf9-130a-4cd8-afc5-ca0f33a16b32","title":"对雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["战哭多新鬼，愁吟独老翁。","乱云低薄暮，急雪舞回风。","瓢弃尊无绿，炉存火似红。","数州消息断，愁坐正书空。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["雪","冬"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"b9521e2b-963e-4d90-acf3-d87c2a135071","title":"古意呈补阙乔知之","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家少妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催木叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁谓含愁独不见，更教明月照流黄。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","秋","夜"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.594},{"uid":"1b9d00c7-3128-4bee-b338-2d354d51c002","title":"和武相公中秋锦楼玩月得苍字","author":"张正一","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高秋今夜月，皓色正苍苍。","远水澄如练，孤鸿逈带霜。","旅人方积思，繁宿稍沈光。","朱槛叨陪赏，尤宜清漏长。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["秋","中秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"cda42a70-1158-4d7e-a1de-b7580ff210cb","title":"弘农清岩曲有磐石可坐宋十一每拂拭待余寄诗赠之","author":"田游岩","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["信彼称灵石，居然狎遁栖。","裴回承翠𪩘，斌驳带深谿。","夕阴起层岫，清景半虹霓。","风来应啸阮，波动可琴嵇。","仆也颍阳客，望彼空思齐。","傥见山人至，簪嵩且杖藜。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["幽峭"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"天气":["彩虹"]},"theme_conf":0.88},{"uid":"4be77185-992e-4614-9746-de2e73c8a3c3","title":"关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","[戍]客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"cp3132bc43c19b92","title":"摸鱼儿","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["旷达","豪放"],"mood":"愁怨","mood2":[],"scene":["春","雨","酒","夜","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["西湖"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"9b07bc6b-8022-4278-a691-a47120a1da16","title":"南至日隔仗望含元殿香𬬻","author":"车𬘔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["抗殿疏元首，高高接上元。","节当南至日，星是北辰天。","宝戟罗仙仗，金𬬻引瑞烟。","霏微双阙丽，溶曳九州连。","拂曙祥光满，分晴晓色鲜。","一阳今在历，生植愿陶甄。"],"theme":"应制干谒","theme2":[],"style":"婉约","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["元宵","花"],"cats":{"天气":["太阳"],"节日":["元宵节"]},"theme_conf":0.9},{"uid":"9391ef33-933e-452d-8fc3-5c6ccfe8eb12","title":"和崔中丞中秋月","author":"张南史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋夜月偏明，西楼独有情。","千家看露湿，万里觉天清。","映水金波动，衔山桂树生。","不知飞鹊意，何用此时惊。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["月","中秋","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"24eec460-2dda-41a7-8104-e590096f3e03","title":"相和歌辞 长歌行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["桃李得日开，荣华照当年。","东风动百物，草木尽欲言。","枯枝无丑叶，涸水吐清泉。","大力运天地，羲和无停鞭。","功名不早著，竹帛将何宣？","桃李务青春，谁能贯白日。","富贵与神仙，蹉跎成两失。","金石犹销铄，风霜无久质。","畏落日月后，强欢歌与酒。","秋霜不惜人，倏忽侵蒲柳。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"天气":["太阳"],"人生":["青春"]},"theme_conf":1.0},{"uid":"1a6a438f-ee84-40e8-8e66-56ccc4ace6df","title":"元日望含元殿御扇开合","author":"章八元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万国来朝岁，千年觐圣君。","辇迎仙杖出，扇匝御香焚。","俯对朝容近，先知曙色分。","冕旒开处见，钟磬合时闻。","影动承朝日，花攒似庆云。","蒲葵那可比，徒用隔炎氛。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","夏"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.91},{"uid":"37cd5393-d24a-426a-9c53-a774251bd650","title":"蒙山作","author":"萧颖士","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东蒙镇海沂，合沓余百里。","清秋净氛霭，崖崿隐天起。","于役劳往还，息徒暂攀跻。","将穷绝迹处，偶得冥心理。","云气杂虹霓，松声乱风水。","微明绿林际，杳窱丹洞里。","仙鸟时可闻，羽人邈难视。","此焉多深邃，贤达昔所止。","子尚捐俗纷，季随蹑遐轨。","蕴真道弥旷，怀古情未已。","白鹿凡几游，黄精复奚似。","顾予尚牵缠，家业重书史。","少学务从师，壮年贵趋仕。","方驰桂林誉，未暇桃源美。","岁暮期再寻，幽哉羡门子。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"清新","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["山","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.435},{"uid":"38438036-586a-47f6-a4c0-d75bc30801c0","title":"相和歌辞 从军行二首 一","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涂山烽候惊，弭节度龙城。","冀马楼兰将，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凛凛严霜节，冰壮黄河绝。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精骑乘胶折。","结发早驱驰，辛苦事旌麾。","马冻重关冷，轮摧九折危。","独有西山将，年年属数奇。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","冬","江"],"cats":{"抒情":["孤独"],"山水":["黄河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"9f32abfa-6459-4020-b79d-5f96a026c945","title":"九月十日雨中过张伯佳期柳镇未至以诗招之","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["柳吴兴近无消息，张长公贫苦寂寥。","唯有角巾沾雨至，手持残菊向西招。"],"theme":"爱情相思","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["怀古"],"天气":["写雨","月亮"],"植物":["柳树"]},"theme_conf":0.574},{"uid":"30cd14b3-98fd-4a64-b57f-6d2cc05f52d9","title":"暮春喜雨诗","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风云喜际会，雷雨遂流滋。","荐币虚陈礼，动天实精思。","渐侵九夏节，复在三春时。","霡霂垂朱阙，飘飖入绿墀。","郊坰既沾足，黍稷有丰期。","百辟同康乐，万方伫雍熙。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"天气":["写雨"]},"theme_conf":0.66},{"uid":"d1647555-1944-4bdb-9515-7ab825db789b","title":"奉和武相公中秋锦楼玩月得来字","author":"徐放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉露中秋夜，金波碧落开。","鹊惊初泛滥，鸿思共裴回。","远月清光徧，高空爽气来。","此时陪永望，更得上燕台。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"1bcd81fb-6fb5-4994-b9ec-6baf5bbd4142","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朔风飘胡雁，惨澹带砂砾。","长林何萧萧，秋草萋更碧。","北里富熏天，高楼夜吹笛。","焉知南邻客，九月犹𫄨绤。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["夜","秋","楼","月","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.551},{"uid":"6dcc533e-01af-48f9-835f-47f087bc81c7","title":"酬李二十二兄主簿马迹山见寄","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["杳杳尘外想，悠悠区中缘。","如何战未胜，曾是教所牵。","远郊有灵峰，夙昔栖真仙。","鸾声去已久，马迹空依然。","丹崖转初旭，碧落凝秋烟。","松风共箫飒，萝月想婵娟。","内兄蕴遐心，嘉遯性所便。","不能栖枳棘，且复探云泉。","中有冥寂人，闲读逍遥篇。","联袂共支[策]，抠衣赏绝编。","徐行石上苔，静韵风中弦。","烟霞湿儒服，日月生寥天。","新诗来起予，璀璨六义全。","能尽含写意，转令山水鲜。","若闻笙鹤声，宛在耳目前。","登攀阻心赏，愁绝空怀贤。","出处岂异途，心冥即真筌。","𫏐从西府檄，终卧东菑田。","不嫌予步蹇，但恐君行膻。","如能固旷怀，谷口期穷年。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":0.457},{"uid":"88abad3a-4ba9-461a-a592-34eb50aa80ef","title":"湖城东遇孟云卿复归刘颢宅宿宴饮散因为醉歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["疾风吹尘暗河县，行子隔手不相见。","湖城城南一开眼，驻马偶识云卿面。","向非刘颢为地主，嬾回鞭辔成高宴。","刘侯叹我携客来，置酒张灯促华馔。","且将款曲终今夕，休语艰难尚酣战。","照室红炉促曙光，萦窗素月垂文练。","天开地裂长安陌，寒尽春生洛阳殿。","岂知驱车复同轨，可惜刻漏随更箭。","人生会合不可常，庭树鸡鸣泪如线。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","江","夜"],"cats":{"抒情":["思乡","伤感"],"天气":["写云"],"食物":["写酒"]},"theme_conf":0.381},{"uid":"1168acab-dc79-42cd-82a8-439ee1fc51ae","title":"杂曲歌辞 十二月乐辞 七月","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["星依云渚冷，露滴盘中圆。","好花生木末，衰蕙愁空园。","夜天如玉砌，池叶极青钱。","仅厌舞衫薄，稍知花簟寒。","晓风何拂拂，北斗光阑干。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":["清新"],"mood":"欢愉","mood2":["愁怨","孤寂"],"scene":["园林","月"],"cats":{"抒情":["伤感"],"天气":["月亮","星星"]},"theme_conf":0.9},{"uid":"9b8940d5-7966-47ab-bbf9-55efadf169b3","title":"观云篇","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兴云感阴气，疾足如见机。","晴来意态行，有若功成归。","葱茏含晚景，洁白凝秋晖。","夜深度银汉，漠漠仙人衣。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","秋","七夕","夜"],"cats":{"四季":["秋天"],"天气":["写云"],"节日":["七夕节"]},"theme_conf":0.65},{"uid":"f0226faf-8724-49ba-abe6-6c2096447765","title":"郡楼晴望二首 二","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一雨晴山郭，惊秋碧树风。","兰巵谁与荐，玉斾自无悰。","云景嘶宾雁，岚阴露彩虹。","闲吟嬾闭阁，旦夕郡楼中。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"天气":["彩虹"]},"theme_conf":0.554},{"uid":"a7318ace-183f-44e8-9704-3fceabe908be","title":"人日寄杜二拾遗","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["人日题诗寄草堂，遥怜故人思故乡。","柳条弄色不忍见，梅花满枝空断肠。","身在远藩无所预，心怀百忧复千虑。","今年人日空相忆，明年人日知何处。","一卧东山三十春，岂知书劒老风尘。","龙钟还忝二千石，愧尔东西南北人。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.94},{"uid":"262d09ef-c986-4c06-81a4-9a75c6d83719","title":"岳阳楼别窦司直","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["洞庭九州间，厥大谁与让。","南汇群崖水，北注何奔放。","潴为七百里，吞纳各殊状。","自古澄不清，环混无归向。","炎风日搜搅，幽怪多冗长。","轩然大波起，宇宙隘而妨。","巍峩拔嵩华，腾踔较健壮。","声音一何宏，轰輵车万两。","犹疑帝轩辕，张乐就空旷。","蛟螭露笋簴，缟练吹组帐。","鬼神非人世，节奏颇跌踼。","阳施见夸丽，阴闭感凄怆。","朝过宜春口，极北缺隄障。","夜缆巴陵洲，丛芮才可傍。","星河尽涵泳，俯仰迷下上。","余澜怒不已，喧聒鸣瓮盎。","明登岳阳楼，辉焕朝日亮。","飞廉戢其威，清晏息纤纩。","泓澄湛凝绿，物影巧相况。","江豚时出戏，惊波忽荡瀁。","时当冬之孟，隙窍缩寒涨。","前临指近岸，侧坐眇难望。","涤濯神魂醒，幽怀舒以畅。","主人孩童旧，握手乍忻怅。","怜我窜逐归，相见得无恙。","开筵交履舃，烂漫倒家酿。","杯行无留停，高柱送清唱。","中盘进橙栗，投掷倾脯酱。","欢穷悲心生，婉娈不能忘。","念昔始读书，志欲干霸王。","屠龙破千金，为艺亦云亢。","爱才不择行，触事得谗谤。","前年出官由，此祸最无妄。","公卿采虚名，擢拜识天仗。","奸猜畏弹射，斥逐恣欺诳。","新恩移府庭，逼侧厕诸将。","于嗟苦驽缓，但惧失宜当。","追思南渡时，鱼腹甘所葬。","严程迫风帆，劈箭入高浪。","颠沈在须臾，忠鲠谁复谅。","生还真可喜，尅己自惩创。","庶从今日后，粗识得与丧。","事多改前好，趣有获新尚。","誓耕十亩田，不取万乘相。","细君知蚕织，稚子已能饷。","行当挂其冠，生死君一访。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":["慷慨","悲怆"],"scene":["楼","江"],"cats":{"抒情":["离别","伤感"],"天气":["星星"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.467},{"uid":"1fc07309-faba-489d-924d-9c46e950a35c","title":"裴端公使院赋得隔帘见春雨","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["细雨未成霖，垂帘但觉阴。","唯看上砌湿，不遣入簷深。","度隟沾霜简，因风润绮琴。","须移户外屦，簷溜夜相侵。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.621},{"uid":"620e2d04-2cd5-4217-a8f0-64837017c7e4","title":"夜看美人宫棋","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宫棋布局不依经，黑白分明子数停。","巡拾玉沙天汉晓，犹残织女两三星。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","七夕"],"cats":{"天气":["星星"],"人物":["女子"],"节日":["七夕节"]},"theme_conf":0.62},{"uid":"25b83882-d6df-4662-9463-fdde2af46b26","title":"东渡早梅一树岁华如雪酣赏成咏","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暇日留囗事，期云亦囗开。","乡心持岁酒，津下赏山梅。","晚实和商鼎，浓香拂寿杯。","唯应招北客，日日踏青来。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","雪","酒"],"cats":{"抒情":["思乡"],"天气":["写雪"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"81981192-77b7-407d-ab89-18ebf00d8de4","title":"九月九日上幸慈恩寺登浮图群臣上菊花寿酒","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["帝里重阳节，香园万乘来。","却邪萸入佩，献寿菊传杯。","墖类承天涌，门疑待佛开。","睿词悬日月，长得仰昭回。"],"theme":"题画咏艺","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳","月亮"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.381},{"uid":"cp92f27b08a6a25e","title":"水调歌头","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月几时有，把酒问青天。","不知天上宫阙，今夕是何年。","我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","起舞弄清影，何似在人间。","转朱阁，低绮户，照无眠。","不应有恨，何事长向别时圆。","人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","清新"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["月","楼","中秋"],"cats":{"抒情":["离别","伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"08a8ab7b-fb84-4a05-8b4e-177f2728bdbf","title":"和浙西李大夫晚下北固山喜径松成阴怅然怀古偶题临江亭幷浙东元相公所和依本韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一辞温室树，几见武昌柳。","荀谢年何少，韦平望已久。","种松夹石道，纡组临沙阜。","目览帝王州，心存股肱守。","叶动惊彩翰，波澄见頳首。","晋宋齐梁都，千山万江口。","烟散隋宫出，涛来海门吼。","风俗太伯余，衣冠永嘉后。","江长天作限，山固壤无朽。","自古称佳丽，非贤谁奄有。","八元邦族盛，万石门风厚。","天柱揭东溟，文星照北斗。","高亭一骋望，举酒共为寿。","因赋咏怀诗，远寄同心友。","禁中晨夜直，江左东西偶。","将手握兵符，儒腰盘贵绶。","颁条风有自，立事言无苟。","农野闻让耕，军人不使酒。","用材当构厦，知道宁窥牖。","谁谓青云高，鹏飞终背负。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["江","山","楼"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["星星"],"人生":["梦想"]},"theme_conf":0.383},{"uid":"01cc3e31-e2e4-4598-915f-36e8dbbe7c95","title":"琴曲歌辞 湘夫人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["娥眉对湘水，遥哭苍梧间。","万乘既已殁，孤舟谁忍还。","至今楚山上，犹有泪痕斑。","南有涔阳路，渺渺多新愁。","昔神降回时，风波江上秋。","彩云忽无处，碧水空安流。"],"theme":"闺情宫怨","theme2":["闲适隐逸","羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["舟","秋","山","江"],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.392},{"uid":"2fa31522-6b7d-4c10-b9a4-ee278d17a714","title":"雪夜观象阙待漏","author":"张少博","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["残雪初睛后，鸣珂奉阙庭。","九门传晓漏，五夜候晨扃。","北斗横斜汉，东方落曙星。","烟氛初动色，簪佩未分形。","雪重犹垂白，山遥不辨青。","鸡人更唱处，偏入此时听。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["闺怨"],"天气":["写雪","星星"]},"theme_conf":0.65},{"uid":"1877173b-b4bb-467b-93da-a390559efe41","title":"留花门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北门天骄子，饱肉气勇决。","高秋马肥健，挟矢射汉月。","自古以为患，诗人厌薄伐。","修德使其来，羁縻固不绝。","胡为倾国至，出入暗金阙。","中原有驱除，隐忍用此物。","公主歌黄鹄，君王指白日。","连云屯左辅，百里见积雪。","长戟鸟休飞，哀笳曙幽咽。","田家最恐惧，麦倒桑枝折。","沙苑临清渭，泉香草丰洁。","渡河不用船，千骑常撇烈。","胡尘逾太行，杂种抵京室。","花门既须留，原野转萧瑟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["爱国"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.443},{"uid":"e27839b5-a0d2-41ff-aa5b-a2a0355afc68","title":"岁日作","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["更劳今日春风至，枯树无枝可寄花。","览镜唯看飘乱发，临风谁为驻浮槎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"57990c9f-c5a0-479a-81bc-284da6828046","title":"西阁曝日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凛冽倦玄冬，负暄嗜飞阁。","羲和流德泽，颛顼媿倚薄。","毛发具自和，肌肤潜沃若。","太阳信深仁，衰气歘有托。","攲倾烦注眼，容易收病脚。","流离木杪猨，翩跹山颠鹤。","用知苦聚散，哀乐日已作。","即事会赋诗，人生忽如昨。","古来遭丧乱，贤圣尽萧索。","胡为将暮年，忧世心力弱。"],"theme":"闲适隐逸","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆","欢愉"],"scene":["楼"],"cats":{"天气":["太阳"]},"theme_conf":0.7},{"uid":"cp442579beaba036","title":"诈妮子调风月・梨花儿","author":"关汉卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["是教我软地上吃交，我也不共你争。","煞是多劳重，降尊临卑，（云）有劳长者车马，贵脚踏于贱地，小的每多谢承。","本待麻线道上不和你一处行；（云）你依得我一件事，依得我愿随鞭镫。","（云）你要我饶你咱，再对星月赌一个誓。","（云了）（出门了）（正旦唱）。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"天气":["写云","月亮"],"植物":["梨花"]},"theme_conf":0.65},{"uid":"d32a2610-09d7-49ad-8cdf-dd9c649144c7","title":"风雨","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凄凉宝剑篇，羁泊欲穷年。","黄叶仍风雨，青楼自管弦。","新知遭薄俗，旧好隔良缘。","心断新丰酒，销愁斗几千。"],"theme":"讽喻刺世","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡","伤感"],"天气":["写风","写雨"]},"theme_conf":0.506},{"uid":"cpce56cd8545a87f","title":"圣药王・脚又滑，手又麻，乱纷纷瑞雪舞梨花。情绪杂，囊箧乏。若老天","author":"苏彦文","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["全不可怜咱，冻钦钦怎行踏？。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"],"植物":["梨花"]},"theme_conf":0.526},{"uid":"7456691c-636e-46d7-9093-edc778b0a7ea","title":"楚江怀古三首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["露气寒光集，微阳下楚丘。","猨啼洞庭树，人在木兰舟。","广泽生明月，苍山夹乱流。","云中君不降，竟夕自悲秋。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江","月"],"cats":{"抒情":["伤感","怀古"],"天气":["月亮"]},"theme_conf":0.773},{"uid":"f3e3dab9-6df9-4bc1-b428-ace90e3a922c","title":"杂曲歌辞 结客少年场行","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长安重游侠，洛阳富才雄。","玉劒浮云骑，金鞍明月弓。","鬬鸡过渭北，走马向关东。","孙宾遥见待，郭解暗相通。","不受千金爵，谁论万里功。","将军下天上，虏骑入云中。","烽火夜似月，兵气晓成虹。","横行徇知己，负羽远从戎。","龙旌昏朔雾，鸟阵卷寒风。","追奔瀚海咽，战罢阴山空。","归来谢天子，何如马上翁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","冲淡"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.711},{"uid":"6beb5cc2-ae49-4e23-952a-1cb92fa11512","title":"望蓟门","author":"祖咏","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["燕台一望客心惊，箫鼓喧喧汉将营。","万里寒光生积雪，三边曙色动危旌。","沙场烽火连胡月，海畔云山拥蓟城。","少小虽非投笔吏，论功还欲请长缨。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.842},{"uid":"699b5dce-f6cd-4580-b5fe-968eaa185c33","title":"开元观陪杜大夫中元日观乐","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["今朝欢称玉京天，况值关东俗理年。","舞态疑回紫阳女，歌声似遏彩云仙。","盘空双鹤惊几剑，洒砌三花度管弦。","落日香尘拥归骑，囗风油幕动高烟。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["花","园林"],"cats":{"天气":["写云","太阳"],"节日":["春节"]},"theme_conf":0.78},{"uid":"79e7ec6e-0d6c-4f95-8181-4671c42e1faf","title":"夜月","author":"刘方平","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["更深月色半人家，北斗阑干南斗斜。","今夜偏知春气暖，虫声新透绿窗纱。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["月","夜"],"cats":{"天气":["月亮"]},"theme_conf":0.5},{"uid":"dd4c60cf-6385-48a0-86b2-2020cdf70f36","title":"青云干吕 二","author":"彭伉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣布中区化，祥符异域云。","含春初应吕，晕碧已成文。","东起随风暖，西流共日曛。","升时嘉异月，为庆等凝汾。","轻与晴烟比，高将晓雾分。","飘飘如可致，愿此翊明君。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","月"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"cp1263481f8f5d84","title":"江神子・江城子","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["十年生死两茫茫。","不思量。","自难忘。","千里孤坟，无处话凄凉。","纵使相逢应不识，尘满面，鬓如霜。","夜来幽梦忽还乡。","小轩窗。","正梳妆。","相顾无言，惟有泪千行。","料得年年断肠处，明月夜，短松冈。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月","江","夜"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"]},"theme_conf":0.99},{"uid":"668bda10-2fcd-45a3-9795-a8393e22ae00","title":"和李舍人直中书对月见寄","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["名卿步月正淹留，上客裁诗怨别游。","素魄近成班女扇，清光远似庾公楼。","婵娟更称凭高望，皎洁能传自古愁。","盈手入怀皆不见，阳春曲丽转难酬。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"06bb6ddd-5f47-42f0-a020-b7671ad56bdf","title":"相和歌辞 短歌行六首 四","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["何处春风吹晓幕？江南绿水通朱阁。","美人二八面如花，泣向东风畏花落。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["春","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.65},{"uid":"83de3747-2242-4ae3-be3e-56a7b040aae2","title":"宋中遇林卢杨十七山人因而有别","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔余涉漳水，驱车行邺西。","遥见林虑山，苍苍戛天倪。","邂逅逢尔曹，说君彼岩栖。","萝径垂野蔓，石房倚云梯。","秋韭何青青，药苗数百畦。","栗林隘谷口，栝树森廻谿。","耕耘有山田，纺绩有山妻。","人生苟如此，何必组与珪。","谁谓远相访，曩情殊不迷。","簷前举醇醪，灶下烹双鸡。","朔风忽振荡，昨夜寒螀啼。","游子益思归，罢琴伤解携。","出门尽原野，白日黯已低。","始惊道路难，终念言笑暌。","因声谢岑壑，岁暮一攀跻。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"天气":["写风"]},"theme_conf":0.365},{"uid":"7e29d72b-7386-48c6-af3c-9dafd02f0665","title":"木兰歌","author":"韦元甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["木兰抱杼嗟，借问复为谁。","欲闻所戚戚，感激彊其颜。","老父隶兵籍，气力日衰耗。","岂足万里行，有子复尚少。","胡沙没马足，朔风裂人肤。","老父旧羸病，何以彊自扶。","木兰代父去，秣马备戎行。","易却纨绮裳，洗却铅粉妆。","驰马赴军幕，慷慨携干将。","朝屯雪山下，暮宿青海傍。","夜袭燕支虏，更携于阗羌。","将军得胜归，士卒还故乡。","父母见木兰，喜极成悲伤。","木兰能承父母颜，却卸巾鞲理丝簧。","昔为烈士雄，今为娇子容。","亲戚持酒贺父母，始知生女与男同。","门前旧军都，十年共崎岖。","本结弟兄交，死战誓不渝。","今者见木兰，言声虽是颜貌殊。","惊愕不敢前，叹息徒嘻吁。","世有臣子心，能如木兰节。","忠孝两不渝，千古之名焉可灭。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放","悲慨"],"mood":"悲怆","mood2":["慷慨"],"scene":["冬","夜","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"天气":["写风"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.668},{"uid":"cp667abac29b3ed1","title":"乔木查・掩柴扉静悄，不许红尘到。皓月清风为故友，肩将梨杖桃，闲访","author":"高秀文","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["渔樵。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"冲淡","style2":["清新","绮丽"],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"植物":["梨花","桃花"]},"theme_conf":0.528},{"uid":"c92216ac-114d-4bda-9c55-89688840f5b0","title":"薄命篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔住邯郸年尚少，只是娇羞弄花鸟。","青楼碧纱大道边，绿杨日暮风褭褭。","婵娟玉貌二八余，自怜颜色花不如。","丽质全胜秦氏女，藁砧宁用专城居。","岁去年来年渐长，青春红粉全堪赏。","玉楼珠箔但闲居，南陌东城讵来往。","韶光日日看渐迟，[摽]梅既落行有时。","宁知燕赵娉婷子，翻嫁幽幷游侠儿。","年年结束青丝骑，出门一去何时至。","秋月空悬翡翠帘，春帏嬾卧鸳鸯被。","沙塞经时不寄书，深闺愁独意何如。","花前拭泪情无限，月下调琴恨有余。","离别苦多相见少，洞房愁梦何由晓。","闲看双燕泪霏霏，静对空床魂悄悄。","镜里红颜不自禁，陌头香骑动春心。","为问佳期早晚是，人人总解有黄金。"],"theme":"闺情宫怨","theme2":["送别","闺情宫怨","爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","秋","鸟","春","塞外","中秋"],"cats":{"抒情":["爱情","离别","伤感","闺怨"],"四季":["春天","秋天"],"天气":["月亮"],"人生":["青春"],"节日":["中秋节"]},"theme_conf":0.96},{"uid":"be5ce2f9-2aaf-40b1-8f05-1a5817447ed3","title":"横吹曲辞 后出塞五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝进东门营，暮上河阳桥。","落日照大旗，马鸣风萧萧。","平沙列万幕，部伍各见招。","中天悬明月，令严夜寂寥。","悲笳数声动，壮士惨不骄。","借问大将谁，恐是霍嫖姚。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["塞外","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"生活":["边塞","写桥"]},"theme_conf":1.0},{"uid":"39f705dc-3756-4ec4-bbc3-ea2e48e3e010","title":"云山","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["京洛云山外，音书静不来。","神交作赋客，力尽望乡台。","衰疾江边卧，亲朋日暮回。","白鸥元水宿，何事有余哀。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.55},{"uid":"c11ca31f-2354-4bf8-8be4-101c5e81c601","title":"登润州城","author":"江为","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天末江城晚，登临客望迷。","春潮平岛屿，残雨隔虹霓。","鸟与孤帆远，烟和独树低。","乡山何处是，目断广陵西。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","雨","舟"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.399},{"uid":"cec1b138-6e5a-4e43-963b-7dae24a295fc","title":"游长宁公主流杯池二十五首 十一","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暂尔游山第，淹留惜未归。","霞窗明月满，涧户白云飞。","书引藤为架，人将薜作衣。","此真攀玩所，临睨赏光辉。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","酒","园林"],"cats":{"天气":["月亮"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9","title":"送元处士游天台","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥路口绝人行，独与僧期上赤城。","树列烟岚春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野馆风来竹气清。","若过石桥看瀑布，不妨高处便题名。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","楼","雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["瀑布"],"天气":["写雪"],"生活":["写桥"]},"theme_conf":0.458},{"uid":"970e1233-9d3b-4ee6-92c1-1491ffc37bfa","title":"相和歌辞 凤凰曲","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["嬴女吹玉箫，吟弄天上春。","青鸾不独去，更有携手人。","影灭彩云断，遗声落西秦。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.88},{"uid":"22a880cf-50a6-48c2-babd-0a6a19a7fad3","title":"一字至七字诗 茶","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["茶，香叶，嫩芽。","慕诗客，爱僧家。","碾雕白玉，罗织红纱。","铫煎黄蘂色，椀转曲尘花。","夜后邀陪明月，晨前命对朝霞。","洗尽古今人不倦，将知醉后岂堪夸。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["月","花"],"cats":{"天气":["月亮"],"食物":["写茶"]},"theme_conf":0.97},{"uid":"5641758a-d34f-4d86-8631-5f0b17869fc3","title":"相和歌辞 江南曲八首 四","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皓如楚江月，霭若吴岫云。","波中自皎镜，山上亦氛氲。","明月留照妾，轻云持赠君。","山川各离散，光气乃殊分。","天涯一为别，江北自相闻。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江","月"],"cats":{"抒情":["离别"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.94},{"uid":"362e9ec3-e452-4f59-b5f4-10757da34b28","title":"杂曲歌辞 妾薄命","author":"刘元淑","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自从离别守空闺，遥闻征战起云梯。","夜夜愁君辽海外，年年弃妾渭桥西。","阳春白日照空暖，紫燕衔花向庭满。","彩鸾琴里怨声多，飞鹊镜前妆梳断。","谁家夫壻不从征，应是渔阳别有情。","莫道红颜燕地少，家家还似洛阳城。","且逐新人殊未归，还令秋至夜霜飞。","北斗星前横度鴈，南楼月下捣寒衣。","夜深闻鴈肠欲绝，独坐缝衣灯又灭。","暗啼罗帐空自怜，梦度阳关向谁说。","每怜容貌宛如神，如何薄命不胜人。","愿君朝夕燕山至，好作明年杨柳春。"],"theme":"闺情宫怨","theme2":["送别","边塞征战"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","秋","鸟","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天","秋天"],"天气":["星星"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.354},{"uid":"cp8daaa9d387a076","title":"瑶花慢","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["朱钿宝。","天上飞琼，比人间春别。","江南江北，曾未见，谩拟梨云梅雪。","淮山春晚，问谁识、芳心高洁。","消几番、花落花开，老了玉关豪杰。","金壶翦送琼枝，看一骑红尘，香度瑶阙。","韶华正好，应自喜、初识长安蜂蝶。","杜郎老矣，想旧事、花须能说。","记少年，一梦扬州，二十四桥明月。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪","月"],"cats":{"天气":["月亮"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"c3a14148-94d9-47f2-afff-9f9ef345b018","title":"寄袁州李嘉祐员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谁谓江山阻，心亲梦想偏。","容辉常在目，离别任经年。","郡国通流水，云霞共远天。","行春莺几啭，迟客月频圆。","雁有归乡羽，人无访戴船。","愿徴黄霸入，相见玉堦前。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["春","鸟"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.96},{"uid":"5679526b-d077-4f1f-a67e-fc430e4643a9","title":"柳州二月榕叶落尽偶题","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宦情羁思共凄凄，春半如秋意转迷。","山城过雨百花尽，榕叶满庭莺乱啼。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["月亮"],"植物":["柳树","叶子"]},"theme_conf":0.421},{"uid":"11e193d2-f374-43c1-b475-94751f6569b8","title":"田园雨后赠邻人","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["安排常任性，偃卧晚开户。","樵客荷蓑归，向来春山雨。","残云虹未落，返景霞初吐。","时鸟鸣村墟，新泉遶林圃。","尧年尚恬泊，邻里成太古。","室迩人遂遥，相思怨芳杜。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["雨","园林"],"cats":{"抒情":["思念"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.447},{"uid":"77ae50af-e0a1-44f5-9d40-b319a0549ea5","title":"咏虹","author":"董思恭","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春暮萍生早，日落雨飞余。","横彩分长汉，倒色媚清渠。","梁前朝影出，桥上晚光舒。","愿逐旌旗转，飘飘侍直庐。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.701},{"uid":"7c5abe03-8a94-43d1-b340-e25aa1f83fc6","title":"春日茶山病不饮酒因呈宾客","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["笙歌登画船，十日清明前。","山秀白云腻，溪光红粉鲜。","欲开未开花，半阴半晴天。","谁知病太守，犹得作茶仙。"],"theme":"寄赠酬答","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒","清明"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"],"节日":["清明节"],"食物":["写酒","写茶"]},"theme_conf":0.7},{"uid":"cp6c3b8276f269f5","title":"采桑子","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["群芳过后西湖好，狼籍残红。","飞絮蒙蒙。","垂柳阑干尽日风。","笙歌散尽游人去，始觉春空。","垂下帘栊。","双燕归来细雨中。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","江南"],"cats":{"山水":["西湖"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"e39702ba-5835-461f-ae4f-4fc597c65478","title":"同李三月夜作","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["霜风惊度雁，月露皓疎林。","处处砧声发，星河秋夜深。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["月","夜","秋"],"cats":{"四季":["秋天"],"天气":["月亮","星星"]},"theme_conf":0.58},{"uid":"e26b59de-597a-433f-8f89-49fc83e0407e","title":"奉真观","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["真门逈向北，驰道直向西。","为与天光近，云色成虹霓。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"天气":["彩虹"]},"theme_conf":0.72},{"uid":"8331c76b-a250-4d07-9c28-b8a456e0974c","title":"春雨","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怅卧新春白袷衣，白门寥落意多违。","红楼隔雨相望冷，珠箔飘灯独自归。","远路应悲春晼晚，残宵犹得梦依稀。","玉珰缄札何由达，万里云罗一雁飞。"],"theme":"山水田园","theme2":["爱情相思","羁旅思乡"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂","相思"],"scene":["雨","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.38},{"uid":"cpa35401f760960a","title":"桂枝香","author":"王安石","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹残阳里，背西风、酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐。","叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事随流水，但寒烟、芳草凝绿。","至今商女，时时犹唱，后庭遗曲。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨","绮丽"],"mood":"悲怆","mood2":["愁怨","恬淡"],"scene":["舟","秋","花"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.578},{"uid":"09e503f0-2aaf-4625-a805-f3960d19d9cd","title":"渔父歌沧浪赋附歌 二","author":"何蠲","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["泛蓬𦩘戏凫鹥，澄水暗（一作「镜」）兮照虹霓。","指尘路兮何足迷，来濯缨兮沧浪溪。","（见伯二四八八、二六二一、二七一二卷，兹从张锡厚校录本。","）。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"天气":["彩虹"],"人物":["父亲"]},"theme_conf":0.714},{"uid":"d441a467-c7a4-4a9b-8f4a-bcba626c16d8","title":"奉和春日游龙门应制","author":"武三思","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤架临香地，龙舆上翠微。","星宫含雨气，月殿抱春辉。","碧涧长虹下，雕梁早燕归。","云疑浮宝盖，石似拂天衣。","露草侵阶长，风花遶席飞。","日斜宸赏洽，清吹入重闱。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["绮丽","婉约"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["彩虹","太阳"]},"theme_conf":0.99},{"uid":"1c1d545e-07a1-46a9-bb76-b7473c1fde43","title":"九日登望仙台呈刘明府容","author":"崔曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉文皇帝有高台，此日登临曙色开。","三晋云山皆北向，二陵风雨自东来。","关门令尹谁能识，河上仙翁去不回。","且欲近寻彭泽宰，陶然共醉菊花杯。"],"theme":"咏史怀古","theme2":["游仙梦幻"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.72},{"uid":"68c0c67f-eb61-4dfc-8685-a43c60f1e0e2","title":"长安道中早行","author":"张泌","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["客离孤馆一灯残，牢落星河欲曙天。","鸡唱未沈函谷月，鴈声新度灞陵烟。","浮生已悟庄周蝶，壮志仍输祖逖鞭。","何事悠悠策羸马，此中辛苦过流年。"],"theme":"哲理悟道","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["星星"],"人生":["励志","哲理","时光","梦想"]},"theme_conf":0.49},{"uid":"ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5","title":"鼓吹曲辞 有所思","author":"刘氏云","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝亦有所思，暮亦有所思。","登楼望君处，蔼蔼浮云飞。","浮云遮却阳关道，向晚谁知妾怀抱。","玉井苍苔春院深，桐花落地无人扫。"],"theme":"边塞征战","theme2":["送别","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","楼","园林"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写云"],"生活":["边塞"]},"theme_conf":0.38},{"uid":"75db753d-e7da-48a1-a6c0-6ed9147e58db","title":"夜雨寄北","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["君问归期未有期，巴山夜雨涨秋池。","何当共剪西窗烛，却话巴山夜雨时。"],"theme":"爱情相思","theme2":["山水田园","爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雨","夜"],"cats":{"天气":["写雨"]},"theme_conf":0.8},{"uid":"95016fcd-87f8-4828-9d26-b9a2b43c5a89","title":"过鸣臯隐者","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["磻石老红鲜，徴君卧几年。","飞泉出林下，一径过崖巅。","鸡犬逐人静，云霞宜地偏。","终朝数峰胜，不远一壶前。","仲月霁春雨，香风生药田。","丹溪不可别，琼草色芊芊。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","月","雨","山"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":0.515},{"uid":"d827bbc7-2b82-4437-b81b-5e174dcdc134","title":"石上阁","author":"无名氏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["水石引我去，南湖复东壑。","不厌随竹阴，来登石上阁。","磴道通石门，欹崖断如凿。","飞梁架峰头，夭矫虹霓若。","下视竹木杪，仰见悬泉落。","水声兼松吹，音响参众乐。","时时为雾雨，飘洒湿帘箔。","吾欲弃簪缨，于兹守寂寞。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","山"],"cats":{"抒情":["孤独"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.75},{"uid":"d1d57a82-baf7-4776-854e-b99e5319ae87","title":"在滁苦雨归桃花崦伤亲友略尽","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["废弃忝残生，后来亦先夭。","诗人感风雨，长夜何时晓。","去国宦情无，近乡归梦少。","庇身绝中授，甘静忘外扰。","丽景变重阴，洞山空木表。","灵潮若可通，寄谢西飞鸟。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["雨"],"cats":{"抒情":["友情","思乡","伤感","悼亡"],"天气":["写雨"],"植物":["桃花"]},"theme_conf":0.431},{"uid":"4de1320f-f293-4f10-846b-1059c07aaab8","title":"清明日送邓芮二子还乡","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["钟鼓喧离日，车徒促夜装。","晓厨新变火，轻柳暗翻霜。","传镜看华发，持杯话故乡。","每嫌儿女泪，今日自沾裳。"],"theme":"送别","theme2":["节令风俗","羁旅思乡"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.329},{"uid":"90d24d06-910e-476e-8819-47f127e03360","title":"含风夕","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["炎昏勌烦久，逮此含风夕。","夏服稍轻清，秋堂已岑寂。","载欣凉宇旷，复念佳辰掷。","络纬惊岁功，顾我何成绩。","青荧微月钩，幽晖洞阴魄。","水镜涵玉轮，若见渊泉璧。","参差帘牖重，次第笼虚白。","树影满空床，萤光缀深壁。","怅望牵牛星，复为经年隔。","露网褭风珠，轻河泛遥碧。","讵无深秋夜，感此乍流易。","亦有迟暮年，壮年良自惜。","循环切中肠，感念追往昔。","接瞬无停阴，何言问陈积。","馨香推蕙兰，坚贞谕松柏。","生物固有涯，安能比金石。","况兹百龄内，扰扰纷众役。","日月东西驰，飞车无留迹。","来者良未穷，去矣定奚适。","委顺在物为，营营复何益。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"孤寂","mood2":["恬淡","慷慨"],"scene":["夏","秋"],"cats":{"四季":["夏天","秋天"],"天气":["写风","星星"]},"theme_conf":0.567},{"uid":"7d4ab8fc-aa99-46f4-8571-54af4d4666bf","title":"咏风","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧条起关塞，摇飏下蓬瀛。","拂林花乱彩，响谷鸟分声。","披云罗影散，泛水织文生。","劳歌大风曲，威加四海清。"],"theme":"咏物","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"天气":["写风"],"生活":["边塞"]},"theme_conf":0.475},{"uid":"09f26016-922c-4bb4-a70f-a846c5b03661","title":"落日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日在帘钩，溪边春事幽。","芳菲缘岸圃，樵爨倚滩舟。","啅雀争枝坠，飞虫满院游。","浊醪谁造汝，一酌散千忧。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"cp4411ce7078f356","title":"定风波","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["莫听穿林打叶声。","何妨吟啸且徐行。","竹杖芒鞋轻胜马。","谁怕。","一蓑烟雨任平生。","料峭春风吹酒醒。","微冷。","山头斜照却相迎。","回首向来萧瑟处。","归去。","也无风雨也无晴。"],"theme":"山水田园","theme2":[],"style":"旷达","style2":["幽峭","婉约"],"mood":"恬淡","mood2":[],"scene":["雨","春","酒"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"ce27f085-cc00-44d2-8bdd-2732050b6f44","title":"郊庙歌辞 朝日乐章 肃和","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["惟圣格天，惟明飨日。","帝郊肆类，王宫戒吉。","珪奠春舒，钟歌晓溢。","礼云克备，斯文有秩。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":0.9},{"uid":"2ceb871e-c8a7-488a-95e9-46d34a6f088f","title":"寻华山云台观道士","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日西山明，胜趣引孤策。","桃源数曲尽，洞口两岸坼。","还从罔象来，忽得仙灵宅。","霓裳谁之子，霞酌能止客。","残阳在翠微，携手更登历。","林行拂烟雨，溪望乱金碧。","飞鸟下天窗，褭松际云壁。","稍寻玄踪远，宛入寥天寂。","愿言葛仙翁，终年炼玉液。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.831},{"uid":"e4a1f615-2b63-4797-8b7a-3ea3708722df","title":"杂言湖山歌送许鸣谦","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["湖中之山兮波上青，桂飒飒兮雨冥冥。","君归兮春早，满山兮碧草。","晨舂暮汲兮心何求，涧户岩扉兮身自老。","东岭西峰兮同白云，鸡鸣犬吠兮时相闻。","幽芳媚景兮当嘉月，践石扪萝兮恣超忽。","空山寂寂兮颍阳人，旦夕孤云随一身。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.564},{"uid":"87beeed5-93f8-4ac6-a8e0-6bc7e42957c2","title":"九成宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["十二层城阆苑西，平时避暑拂虹霓。","云随夏后双龙尾，风逐周王八骏蹄。","吴岳晓光连翠𪩘，甘泉晚景上丹梯。","荔枝卢橘沾恩幸，鸾鹊天书湿紫泥。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["彩虹"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"256d10b8-dba7-466f-8bf9-ba87b8deac72","title":"刈稻了咏怀","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["稻获空云水，川平对石门。","寒风疎落木，旭日散鸡豚。","野哭初闻战，樵歌稍出村。","无家问消息，作客信乾坤。"],"theme":"山水田园","theme2":["咏物"],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":[],"cats":{"天气":["太阳"],"生活":["田野"]},"theme_conf":0.531},{"uid":"eaf1094e-b116-4d91-819b-df1a80e1c991","title":"月蚀诗","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["新天子即位五年，岁次庚寅。","斗柄插子，律调黄钟。","森森万木夜僵立，寒气赑屭顽无风。","烂银盘从海底出，出来照我草屋东。","天色绀滑凝不流，冰光交贯寒朣胧。","初疑白莲花，浮出龙王宫。","八月十五夜，比并不可双。","此时怪事发，有物吞食来。","轮如壮士斧斫坏，桂似雪山风拉摧。","百炼镜，照见胆。","平地埋寒灰，火龙珠。","飞出脑，却入蚌蛤胎。","摧环破璧眼看尽，当天一搭如煤炲。","磨踪灭迹须臾间，便似万古不可开。","不料至神物，有此大狼狈。","星如撒沙出，争头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射户外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太阴太阳精，皇天要识物。","日月乃化生，走天汲汲劳四体。","与天作眼行光明，此眼不自保。","天公行道何由行，吾见阴阳家有说。","望日蚀月月光灭，朔月掩日日光缺。","两眼不相攻，此说吾不容。","又孔子师老子云，五色令人目盲。","吾恐天似人，好色即丧明。","幸且非春时，万物不娇荣。","青山破瓦色，绿水冰峥嵘。","花枯无女艳，鸟死沈歌声。","顽冬何所好，偏使一目盲。","传闻古老说，蚀月虾蟇精。","径圆千里入汝腹，汝此痴骸阿谁生。","可从海窟来，便解缘青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝悬四目，四海生光辉。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受虫豸欺。","长嗟白兔捣灵药，恰似有意防奸非。","药成满臼不中度，委任白兔夫何为。","忆昔尧为天，十日烧九州。","金烁水银流，玉煼丹砂焦。","六合烘为窑，尧心增百忧。","帝见尧心忧，勃然发怒决洪流。","立拟沃杀九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御导九日。","争持节幡麾幢旒，驾车六九五十四头蛟螭虬。","掣电九火辀，汝若蚀开齱齵轮。","御辔执索相爬钩，推荡轰訇入汝喉。","红鳞燄鸟烧口快，翎鬣倒侧声醆邹。","撑肠拄肚礧傀如山丘，自可饱死更不偷。","不独填饥坑，亦解尧心忧。","恨汝时当食，藏头𢬍脑不肯食。","不当食，张唇哆觜食不休。","食天之眼养逆命，安得上帝请汝刘。","呜呼！人养虎，被虎啮。","天媚蟇，被蟇瞎。","乃知恩非类，一一自作孽。","吾见患眼人，必索良工诀。","想天不异人，爱眼固应一。","安得常娥氏，来习扁鹊术。","手操舂喉戈，去此睛上物。","其初犹朦胧，既久如抹漆。","但恐功业成，便此不吐出。","玉川子又涕泗下，心祷再拜额榻砂土中。","地上虮虱臣仝告愬帝天皇，臣心有铁一寸。","可刳妖蟇痴肠，上天不为臣立梯磴。","臣血肉身，无由飞上天。","扬天光，封词付与小心风。","𩙥排阊阖入紫宫，密迩玉几前擘坼。","奏上臣仝顽愚胸，敢死横干天。","代天谋其长，东方苍龙角。","插戟尾捭风，当心开明堂。","统领三百六十鳞虫，坐理东方宫。","月蚀不救援，安用东方龙。","南方火鸟赤泼血，项长尾短飞跋躠。","头戴井冠高逵枿，月蚀鸟宫十三度。","鸟为居停主人不觉察，贪向何人家。","行赤口毒舌，毒虫头上吃却月。","不啄杀，虚眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧为牙，凿为齿。","偷牺牲，食封豕。","大蟇一脔，固当软美。","见似不见，是何道理。","爪牙根天不念天，天若准拟错准拟。","北方寒龟被虵缚，藏头入壳如入狱。","虵筋束紧束破壳，寒龟夏鼈一种味。","且当以其肉充臛，死壳没信处。","唯堪支床脚不堪钻灼与天卜，岁星主福德。","官爵奉董秦，忍使黔娄生。","覆尸无衣巾，天失眼不吊。","岁星胡其仁，荧惑矍铄翁。","执法大不中，月明无罪过。","不纠蚀月虫，年年十月朝太微。","支卢谪罚何灾凶，土星与土性相背。","反养福德生祸害，到人头上死破败。","今夜月蚀安可会，太白真将军。","怒激锋铓生，恒州阵斩郦定进。","项骨脃甚春蔓菁，天唯两眼失一眼。","将军何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固应乐见天盲时，天若不肯信。","试唤臯陶鬼一问，一如今日。","三台文昌宫，作上天纪纲。","环天二十八宿，磊磊尚书郎。","整顿排班行，劒握他人将。","一四太阳侧，一四天市傍。","操斧代大匠，两手不怕伤。","弧矢引满反射人，天狼呀啄明煌煌。","痴牛与𫘤女，不肯勤农桑。","徒劳含淫思，旦夕遥相望。","蚩尤簸旗弄旬朔，始搥天鼓鸣珰琅。","枉矢能蛇行，眊目森森张。","天狗下舐地，血流何滂滂。","谲险万万党，架搆何可当。","眯目衅成就，害我光明王。","请留北斗一星相北极，指麾万国悬中央。","此外尽扫除，堆积如山冈。","赎我父母光，当时常星没。","殒雨如迸浆，似天会事发。","叱喝诛奸强，何故中道废。","自遗今日殃，善善又恶恶。","郭公所以亡，愿天神圣心。","无信他人忠，玉川子词讫。","风色紧格格，近月黑暗边。","有似动劒戟，须臾痴蟇精。","两吻自决坼，初露半个璧。","渐吐满轮魄，众星尽原赦。","一蟇独诛磔，腹肚忽脱落。","依旧挂穹碧，光彩未苏来。","惨澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蚀尽不收，今子咄咄词。","颇合孔意不，玉川子笑荅。","或请听逗留，孔子父母鲁。","讳鲁不讳周，书外书大恶。","故月蚀不见收，予命唐天。","口食唐土，唐礼过三。","唐乐过五，小犹不说。","大不可数，灾沴无有小大瘉。","安得引衰周，研核其可否。","日分昼，月分夜。","辨寒暑，一主刑。","二主德，政乃举。","孰为人面上，一目偏可去。","愿天完两目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["幽峭","豪放"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["月","夏","冬"],"cats":{"抒情":["思念","伤感"],"四季":["夏天","冬天"],"天气":["月亮","星星"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.423},{"uid":"99953267-a278-429d-8470-cc30ebcb23d8","title":"九日诸人集于林","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日明朝是，相要旧俗非。","老翁难早出，贤客幸知归。","旧采黄花賸，新梳白发微。","漫看年少乐，忍泪已沾衣。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":["愁怨"],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.75},{"uid":"6b78aaf7-4de0-4fc2-a524-8eaa6e66a244","title":"题清源寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["儒墨兼宗道，云泉隐旧庐。","盂城今寂寞，辋水自纡余。","内学销多累，西林易故居。","深房春竹老，细雨夜钟疎。","陈迹留金地，遗文在石渠。","不知登座客，谁得蔡邕书。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.563},{"uid":"d9b26a58-c9cb-4a98-8980-32df48b58348","title":"代九九","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年桃李月，颜色共花宜。","廻脸莲初破，低蛾柳竝垂。","望山多倚树，弄水爱临池。","远被登楼识，潜因倒影窥。","隔林徒想像，上砌转逶迤。","谩掷庭中果，虚攀墙外枝。","强持文玉佩，求结麝香缡。","阿母怜金重，亲兄要马骑。","把将娇小女，嫁与冶游儿。","自隐勤勤索，相要事事随。","每常同坐卧，不省暂参差。","才学羞兼妒，何言宠便移。","青春来易皎，白日誓先亏。","僻性嗔来见，邪行醉后知。","别床铺枕席，当面指瑕疵。","妾貌应犹在，君情遽若斯。","的成终世恨，焉用此宵为。","鸾镜灯前扑，鸳衾手下隳。","参商半夜起，琴瑟一声离。","努力新丛艳，狂风次第吹。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["豪放","婉约"],"mood":"慷慨","mood2":["愁怨"],"scene":["园林","夜","春"],"cats":{"抒情":["离别","闺怨"],"四季":["春天"],"天气":["写风"],"人物":["母亲"],"人生":["青春"]},"theme_conf":0.431},{"uid":"cp8a42437795a11b","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["宫粉雕痕，仙云堕影，无人野水荒湾。","古石埋香，金沙锁骨连环。","南楼不恨吹横笛，恨晓风、千里关山。","半飘零，庭上黄昏，月冷阑干。","寿阳空理愁鸾。","问谁调玉髓，暗补香瘢。","细雨归鸿，孤山无限春寒。","离魂难倩招清些，梦缟衣、解佩溪边。","最愁人，啼鸟晴明，叶底青圆。"],"theme":"山水田园","theme2":["羁旅思乡","游仙梦幻"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.378},{"uid":"b188d669-90b1-4227-8fed-d725bde3105d","title":"白水明府舅宅喜雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["吾舅政如此，古人谁复过。","碧山晴又湿，白水雨偏多。","精祷既不昧，欢娱将谓何。","汤年旱颇甚，今日醉弦歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":1.0},{"uid":"b4780bd1-1703-4bce-a801-d5ed566826b5","title":"终南望余雪","author":"祖咏","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["终南阴岭秀，积雪浮云端。","林表明霁色，城中增暮寒。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","冬"],"cats":{"天气":["写雪"]},"theme_conf":1.0},{"uid":"f5584095-bed0-43b3-a45b-a437877d266c","title":"蒹葭","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["摧折不自守，秋风吹若何。","暂时花戴雪，几处叶沈波。","体弱春风早，丛长夜露多。","江湖后摇落，亦恐岁蹉跎。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江","雪","秋","春","夜"],"cats":{"四季":["春天","秋天"],"天气":["写风"]},"theme_conf":0.96},{"uid":"4c57a579-0494-41cf-a174-6472ac4f2e8e","title":"游桃源一百韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["沅江清悠悠，连山郁岑寂。","回流抱绝𪩘，皎镜含虚碧。","昏旦递明媚，烟岚分委积。","香蔓垂绿潭，暴龙照孤碛。","渊明著前志，子骥思远跖。","寂寂无何乡，密尔天地隔。","金行太元岁，渔者偶探赜。","寻花得幽踪，窥洞穿暗隙。","依微闻鸡犬，豁达值阡陌。","居人互将迎，笑语如平昔。","广乐虽交奏，海禽心不怿。","挥手一来归，故溪无处觅。","绵绵五百载，市朝几迁革。","有路在壶中，无人知地脉。","皇家感至道，圣祚自天锡。","金阙传本枝，玉函留宝历。","禁山开秘宇，复户洁灵宅。","蘂检香氛氲，醮坛烟幂幂。","我来尘外躅，莹若朝星析。","崖转对翠屏，水穷留画鹢。","三休俯乔木，千级扳峭壁。","旭日闻撞钟，彩云迎蹑屐。","遂登最高顶，纵目还楚泽。","平湖见草青，远岸连霞赤。","幽寻如梦想，绵思属空阒。","夤缘且忘疲，耽玩近成癖。","清猨伺晓发，瑶草凌寒坼。","祥禽舞葱茏，珠树摇玓𬍛。","羽人顾我笑，劝我税归轭。","霓裳何飘飖，童颜洁白皙。","重岩是藩屏，驯鹿受羁靮。","楼居弥清霄，萝茑成翠帟。","仙翁遗竹杖，王母留桃核。","姹女飞丹砂，青童护金液。","宝气浮鼎耳，神光生劒脊。","虚无天乐来，僁窣鬼兵役。","丹丘肃朝礼，玉札工䌷绎。","枕中淮南方，床下阜乡舄。","明灯坐遥夜，幽籁听淅沥。","因话近世仙，耸然心神惕。","乃言瞿氏子，骨状非凡格。","往事黄先生，群儿多侮剧。","謷然不屑意，元气贮肝膈。","往往游不归，洞中观博弈。","言高未易信，犹复加诃责。","一旦前致辞，自云仙期迫。","言师有道骨，前事常被谪。","如今三山上，名字在真籍。","悠然谢主人，后岁当来觌。","言毕依庭树，如烟去无迹。","观者皆失次，惊追纷络绎。","日暮山径穷，松风自萧槭。","适逢修蛇见，瞋目光激射。","如严三清居，不使恣搜索。","唯余步纲势，八趾在沙砾。","至今东北隅，表以坛上石。","列仙徒有名，世人非目击。","如何庭庑际，白日振飞翮。","洞天岂幽远，得道如咫尺。","一气无死生，三光自迁易。","因思人间世，前路何狭窄。","瞥然此生中，善祝期满百。","大方播群类，秀气肖翕辟。","性静本同和，物牵成阻厄。","是非鬬方寸，荤血昏精魄。","遂令多夭伤，犹喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安缇绣荣，不悟泥途适。","纷吾本孤贱，世业在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰荐，乡曲缪推择。","居安白社贫，至傲玄𫄸辟。","功名希自取，簪组俟扬历。","书府蚤怀铅，射宫曾发的。","起草香生帐，坐曹乌集柏。","赐燕聆箫韶，侍祠阅琮璧。","尝闻履忠信，可以行蛮貊。","自述希古心，忘恃干时画。","巧言忽成锦，苦志徒食蘗。","平地生峰峦，深心有矛戟。","层波一震荡，弱植忽沦溺。","北渚吊灵均，长岑思亭伯。","祸来昧几兆，事去空叹息。","尘累与时深，流年随漏滴。","才能疑木鴈，报施迷夷跖。","楚奏絷钟仪，商歌劳宁戚。","禀生非悬解，对镜方感激。","自从婴网罗，每事问龟策。","王正降雷雨，环玦赐迁斥。","倘伏夷平人，誓将依羽客。","买山构精舍，领徒开讲席。","冀无身外忧，自有闲中益。","道芽期日就，尘虑乃冰释。","且欲遗姓名，安能慕竹帛。","长生尚学致，一溉岂虚掷。","芝术资糇粮，烟霞拂巾帻。","黄石履看堕，洪崖肩可拍。","聊复嗟蜉蝣，何烦哀虺蜴。","青囊既深味，琼葩亦屡摘。","纵无西山资，犹免长戚戚。"],"theme":"游仙梦幻","theme2":["羁旅思乡"],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["山","江","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["写云","太阳"],"人物":["老师"],"人生":["时光","战争"],"植物":["桃花"]},"theme_conf":0.87},{"uid":"7c5fb4a5-5b1f-4eff-8e7f-a59f35d9d835","title":"九日寄岑参","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["出门复入门，两脚但如旧。","所向泥活活，思君令人瘦。","沈吟坐西轩，饮食错昏昼。","寸步曲江头，难为一相就。","吁嗟呼苍生，稼穑不可救。","安得诛云师，畴能补天漏。","大明韬日月，旷野号禽兽。","君子强逶迤，小人困驰骤。","维南有崇山，恐与川浸溜。","是节东篱菊，纷披为谁秀。","岑生多新诗，性亦嗜醇酎。","采采黄金花，何由满衣袖。"],"theme":"寄赠酬答","theme2":["送别"],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.93},{"uid":"83a52b39-32c7-4394-b619-3ede125ed7fd","title":"春晚宴两相及礼官丽正殿学士探得风字","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["乾道运无穷，恒将人代工。","阴阳调历象，礼乐报玄穹。","介胄清荒外，衣冠佐域中。","言谈延国辅，词赋引文雄。","野霁伊川绿，郊明巩树红。","冕旒多暇景，诗酒会春风。"],"theme":"应制干谒","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":0.92},{"uid":"2e32f511-cc12-47dd-9c32-b3ca629c807f","title":"九日五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧日重阳日，传杯不放杯。","即今蓬鬓改，但媿菊花开。","北阙心长恋，西江首独回。","茱萸赐朝士，难得一枝来。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.73},{"uid":"225f48d3-f1c0-4917-bbee-32aa163d5077","title":"赠张云容舞","author":"杨贵妃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["罗袖动香香不已，红蕖褭褭秋烟里。","轻云岭上乍摇风，嫩柳池边初拂水。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["花","秋"],"cats":{"四季":["秋天"],"天气":["写云"]},"theme_conf":0.93},{"uid":"a90b0985-951f-4afa-8f71-2a618b92d3aa","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 三","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓现，城寨可攻之。","虹（辛本、川本作「蛇」）直入来为病疫，浅虹兵瘴（京本作「青虹兵战」）要须知，移寨避灾宜（京本作「危」）。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"ad02adcf-723b-444d-94eb-ad88a922cb82","title":"赋得寒云轻重色送子恂入京","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无限寒云色，苍茫浅更深。","从龙如有瑞，捧日不成阴。","积翠全低岭，虚明半出林。","帝乡遥在目，铁马又骎骎。"],"theme":"送别","theme2":["咏物"],"style":"雄浑","style2":["幽峭","婉约"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"天气":["写云"]},"theme_conf":0.35},{"uid":"ee06ff18-c97c-41bf-8839-3e628f84df56","title":"春夜峡州田侍御长史津亭留宴","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北斗三更席，西江万里船。","杖藜登水榭，挥翰宿春天。","白发烦多酒，明星惜此筵。","始知云雨峡，忽尽下牢边。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夜","春"],"cats":{"四季":["春天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"1a3d6317-14e6-4974-85bf-696d58458a5e","title":"送严员外","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春风倚櫂阖闾城，水国春寒阴复晴。","细雨湿衣看不见，闲花落地听无声。","日斜江上孤帆影，草绿湖南万里情。","君去若逢相识问，青袍今已误儒生。"],"theme":"送别","theme2":[],"style":"婉约","style2":["清新","豪放"],"mood":"孤寂","mood2":["恬淡"],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写雨"]},"theme_conf":0.649},{"uid":"207b2dcf-2f03-4fe2-8a1d-47e4f41f9325","title":"酬乐天雪中见寄","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["知君夜听风萧索，晓望林亭雪半糊。","撼落不教封柳眼，埽来偏尽附梅株。","敲扶密竹枝犹亚，煦暖寒禽气渐苏。","坐觉湖声迷远浪，回惊云路在长途。","钱塘湖上苹先合，梳洗楼前粉暗铺。","石立玉童披鹤氅，台施瑶席换龙须。","满空飞舞应为瑞，寡和高歌只自娱。","莫遣拥帘伤思妇，且将盈尺慰农夫。","称觞彼此情何异，对景东西事有殊。","镜水遶山山尽白，琉璃云母世间无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"欢愉","mood2":["孤寂","相思"],"scene":["雪","冬","楼"],"cats":{"山水":["西湖"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"da42362f-b22f-4ca6-a18e-69284623c195","title":"横吹曲辞 关山月","author":"长孙佐辅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凄凄还切切，戍客多离别。","何处最伤心？关山见秋月。","关月竟如何？由来远近过。","始经玄兔塞，终绕白狼河。","忽忆秦楼妇，流光应共有。","已得竝蛾眉，还知揽纤手。","去岁照同行，比翼复连形。","今宵照独立，顾影自茕茕。","余晖渐西落，夜夜看如昨。","借问映旌旗，何如鉴帷幕。","拂晓朔风悲，蓬惊雁不飞。","几时征戍罢，还向月中归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["塞外","月","山"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"天气":["写风","月亮"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"410b6c68-3226-47ea-a83c-c93f648d5213","title":"安平公诗","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈人博陵王名家，怜我总角称才华。","华州留语晓至暮，高声喝吏放两衙。","明朝骑马出城外，送我习业南山阿。","仲子延岳年十六，面如白玉欹乌纱。","其弟炳章犹两丱，瑶林琼树含奇花。","陈留阮家诸侄秀，逦迤出拜何骈罗。","府中从事杜与李，麟角虎翅相过摩。","清词孤韵有歌响，击触钟磬鸣环珂。","三月石堤冻销释，东风开花满阳坡。","时禽得伴戏新木，其声尖咽如鸣梭。","公时载酒领从事，踊跃鞍马来相过。","仰看楼殿撮清汉，坐视世界如恒沙。","面热脚掉互登陟，青云表柱白云崖。","一百八句在贝叶，三十三天长雨花。","长者子来辄献盖，辟支佛去空留𫖇。","公时受诏镇东鲁，遣我草诏随车牙。","顾我下笔即千字，疑我读书倾五车。","呜嘑大贤苦不寿，时世方士无灵砂。","五月至止六月病，遽颓泰山惊逝波。","明年徒步吊京国，宅破子毁哀如何。","西风冲户卷素帐，隟光斜照旧燕窠。","古人常叹知己少，况我沦贱艰虞多。","如公之德世一二，岂得无泪如黄河。","沥胆咒愿天有眼，君子之泽方滂沱。"],"theme":"送别","theme2":["悼亡挽歌","民生疾苦"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["山","江"],"cats":{"抒情":["友情","伤感","孤独","悼亡"],"山水":["泰山","黄河"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.431},{"uid":"f5c7c474-4fff-4fec-9f4a-d8e2d1447a77","title":"送翰林张司马南海勒碑","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冠冕通南极，文章落上台。","诏从三殿去，碑到百蛮开。","野馆浓花发，春帆细雨来。","不知沧海上，天遣几时回。"],"theme":"送别","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"],"动物":["写马"]},"theme_conf":0.509},{"uid":"cpe47cfbafe8fffc","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["闷已萦损。","那堪多病。","几曲屏山，伴人昼静。","梁燕催起犹慵。","换熏龙。","新愁旧恨何时尽。","渐凋绿鬓。","小雨知花信。","芳笺寄与何处，绣阁珠栊。","柳阴中。"],"theme":"闺情宫怨","theme2":["送别"],"style":"沉郁","style2":["清新","绮丽"],"mood":"愁怨","mood2":[],"scene":["花","月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"c1280e87-ac81-4f9b-9de5-377d6af38ae8","title":"月夜忆舍弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["戍鼓断人行，秋边一雁声。","露从今夜白，月是故乡明。","有弟皆分散，无家问死生。","寄书长不避，况乃未休兵。"],"theme":"亲情","theme2":["边塞征战","送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["夜","月","秋"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.9},{"uid":"17c5283a-e49e-45e5-afa6-49c2084d50ee","title":"游烂柯山四首 二","author":"李幼卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["巨石何崔嵬，横桥架山顶。","傍通日月过，仰望虹霓迥。","圣者开津梁，谁能度兹岭。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["彩虹"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"359bc72a-6f60-4c69-a4cd-9d579e22fc8e","title":"苦雪四首 四","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孰云久闲旷，本自保知寡。","穷巷独无成，春条秪盈把。","安能羡鹏举，且欲歌牛下。","乃知古时人，亦有如我者。"],"theme":"民生疾苦","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨","孤寂"],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":0.608},{"uid":"7b501b42-fe79-4c87-97bc-7ff610629698","title":"竹窗闻风寄苗发司空曙","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["微风惊暮坐，临牖思悠哉。","开门复动竹，疑是故人来。","时滴枝上露，稍沾堦下苔。","何当一入幌，为拂绿琴埃。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":[],"cats":{"抒情":["友情"],"天气":["写风"],"植物":["竹子"]},"theme_conf":0.91},{"uid":"da41166c-15b3-454a-8abb-da16b0661591","title":"病中对石竹花","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["散点空堦下，闲凝细雨中。","那能久相伴，嗟尔𣨼秋风。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"沉郁","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["雨","花"],"cats":{"天气":["写雨"],"植物":["竹子"]},"theme_conf":0.524},{"uid":"58205c60-2b77-46dd-adb0-2c98a17b1f60","title":"遇风雨作","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["草草理夜装，涉江又登陆。","望路殊未穷，指期今已促。","传呼戒徒驭，振辔转林麓。","阴云拥岩端，沾雨当山腹。","震雷如在耳，飞电来照目。","兽迹不敢窥，马蹄惟务速。","虔心若斋祷，濡体如沐浴。","万窍相怒号，百泉暗奔瀑。","危梁虑足跌，峻坂忧车覆。","问我何以然，前日爱微禄。","转知人代事，缨组乃徽束。","向若家居时，安枕春梦熟。","遵途稍已近，候吏来相续。","晓霁心始安，林端见初旭。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":1.0},{"uid":"731721e5-508d-452f-aaab-5b61f196de4c","title":"秋日二首 二","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["爽气澄兰沼，秋风动桂林。","露凝千片玉，菊散一丛金。","日岫高低影，云空点缀阴。","蓬瀛不可望，泉石且娱心。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"0d07875d-bf3e-4a2e-9139-ba767079c8ad","title":"八哀诗 故秘书少监武功苏公源明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["武功少也孤，徒步客徐衮。","读书东岳中，十载考坟典。","时下莱芜郭，忍饥浮云𪩘。","负米晚为身，每食脸必泫。","夜字照𦶟薪，垢衣生碧藓。","庶以勤苦志，报兹劬劳显。","学蔚醇儒姿，文包旧史善。","洒落辞幽人，归来潜京辇。","射君东堂策，宗匠集精选。","制可题未干，乙科已大阐。","文章日自负，吏禄亦累践。","晨趋阊阖内，足蹋宿昔趼。","一麾出守还，黄屋朔风卷。","不暇陪八骏，虏庭悲所遣。","平生满尊酒，断此朋知展。","忧愤病二秋，有恨石可转。","肃宗复社稷，得无逆顺辨。","范晔顾其儿，李斯忆黄犬。","秘书茂松意，溟涨本末浅。","青荧芙蓉劒，犀兕岂独剸。","反为后辈亵，予实苦怀缅。","煌煌斋房芝，事绝万手搴。","垂之俟来者，正始征劝勉。","不要悬黄金，胡为投乳贙。","结交三十载，吾与谁游衍。","荥阳复冥莫，罪罟已横罥。","呜呼子逝日，始泰则终蹇。","长安米万钱，凋丧尽余喘。","战伐何当解，归帆阻清沔。","尚缠漳水疾，永负蒿里饯。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":[],"cats":{"抒情":["伤感","孤独","悼亡"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.99},{"uid":"2d0385e7-0c72-423f-a538-f66acc9d4c46","title":"横吹曲辞 出塞 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"12ae270e-cab4-4a34-b9a1-0aaa66c16f98","title":"感寓二首 一","author":"梁德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩云呈瑞质，五色发人寰。","独作龙虎状，孤飞天地间。","隐隐临北极，峨峨象南山。","恨在帝乡外，不逢枝叶攀。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","孤独"],"天气":["写云"]},"theme_conf":1.0},{"uid":"013587ae-016b-4a6c-be0c-806ac0bc7a12","title":"村雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雨声传两夜，寒事飒高秋。","挈带看朱绂，开箱覩黑裘。","世情只益睡，盗贼敢忘忧。","松菊新沾洗，茅齐慰远游。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["雨"],"cats":{"天气":["写雨"],"生活":["乡村"]},"theme_conf":0.711},{"uid":"5c81fa14-3388-49bf-af9d-f425ec3b522d","title":"星名诗","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["虚怀何所欲，岁晏聊懒逸。","云翼谢翩翻，松心保贞实。","风秋景气爽，叶落井迳出。","陶然美酒酣，所谓幽人吉。","自当轻尺璧，岂复埽一室。","安用簪进贤，少微斯可必。"],"theme":"闲适隐逸","theme2":[],"style":"豪放","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["秋","酒"],"cats":{"四季":["秋天"],"天气":["星星"]},"theme_conf":0.9},{"uid":"9e60181d-a16b-4261-89b7-a3814a52a107","title":"禁中九日对菊花酒忆元九","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["赐酒盈杯谁共持，宫花满把独相思。","相思只傍花边立，尽日吟君咏菊诗。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["爱情","思念"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"2ae550b6-e1b7-406d-9834-8ffeb33e8824","title":"寒食日出游","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["李花初发君始病，我往看君花转盛。","走马城西惆怅归，不忍千株雪相暎。","迩来又见桃与梨，交开红白如争竞。","可怜物色阻携手，空展霜缣吟九咏。","纷纷落尽泥与尘，不共新妆比端正。","桐华最晚今已繁，君不强起时难更。","关山远别固其理，寸步难见始知命。","忆昔与君同贬官，夜渡洞庭看斗柄。","岂料生还得一处，引袖拭泪悲且庆。","各言生死两追随，直置心亲无貌敬。","念君又署南荒吏，路指鬼门幽且敻。","三公尽是知音人，曷不荐贤陛下圣。","囊空甑倒谁救之，我今一食日还并。","自然忧气损天和，安得康强保天性。","断鹤两翅鸣何哀，絷骥四足气空横。","今朝寒食行野外，绿杨帀岸蒲生迸。","宋玉庭边不见人，轻浪参差鱼动镜。","自嗟孤贱足瑕疵，特见放纵荷宽政。","饮酒宁嫌𧣴底深，题诗尚倚笔锋劲。","明宵故欲相就醉，有月莫愁当火令。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭","清新"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["清明"],"cats":{"抒情":["友情","思念","伤感","孤独"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"59e2fe4b-c925-4b3e-851d-e1c355c43b98","title":"关山月","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高高秋月明，北照辽阳城。","塞迥光初满，风多晕更生。","征人望乡思，战马闻鼙惊。","朔风悲边草，胡沙暗虏营。","霜凝匣中劒，风惫原上旌。","早晚谒金阙，不闻刁斗声。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["塞外","月","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写风","月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.595},{"uid":"2204bcb6-175b-46ba-a5f1-60e7e86f526d","title":"冬月长安雨中见终南雪","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋节新已尽，雨疎露山雪。","西峰稍觉明，残滴犹未绝。","气侵瀑布水，冻著白云穴。","今朝灞浐鴈，何夕潇湘月。","想彼石房人，对雪扉不闭。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","雪","雨","月"],"cats":{"四季":["冬天"],"山水":["瀑布"],"天气":["写雨","写雪","月亮"]},"theme_conf":0.611},{"uid":"26d1a470-54cc-4e65-954b-5ab6eeb7358b","title":"辽城望月","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["玄兔月初明，澄辉照辽碣。","映云光暂隐，隔树花如缀。","魄满桂枝圆，轮亏镜彩缺。","临城却影散，带晕重围结。","驻跸俯九都，停观妖氛灭。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"天气":["月亮"]},"theme_conf":0.65},{"uid":"449c81fd-d52a-40f2-ae8c-9d3fc5ddd290","title":"牵牛织女","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["牵牛出河西，织女处其东。","万古永相望，七夕谁见同。","神光意难候，此事终蒙胧。","飒然精灵合，何必秋遂通。","亭亭新妆立，龙驾具曾空。","世人亦为尔，祈请走儿童。","称家随丰俭，白屋达公宫。","膳夫翊堂殿，鸣玉凄房栊。","曝衣徧天下，曳月扬微风。","蛛丝小人态，曲缀瓜果中。","初筵裛重露，日出甘所终。","嗟汝未嫁女，秉心郁忡忡。","防身动如律，竭力机杼中。","虽无姑舅事，敢昧织作功。","明明君臣契，咫尺或未容。","义无弃礼法，恩始夫妇恭。","小大有佳期，戒之在至公。","方圆苟龃龉，丈夫多英雄。"],"theme":"节令风俗","theme2":["民生疾苦"],"style":"豪放","style2":["清新","旷达"],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"884a25ac-d492-45dc-aeb8-d1e7c987ff0a","title":"燕居","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋斋膏沐暇，旭日照轩墀。","露重芭蕉叶，香凝橘柚枝。","简书随吏散，宝骑与僧期。","报国得何力，流年已觉衰。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"20bfd036-c115-4eef-9a08-927a697c870c","title":"喜雪","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日观卜先征，时巡顺物情。","风行未备礼，云密遽飘霙。","委树寒花发，萦空落絮轻。","朝如玉已会，庭似月犹明。","既覩肤先合，还欣尺有盈。","登封何以报？因此谢功成。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"]},"theme_conf":0.75},{"uid":"a455576e-eadf-4a75-a283-80266e1054fb","title":"杂曲歌辞 行路难五首 二","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见门前柳，荣曜暂时萧索久。","君不见陌上花，狂风吹去落谁家。","谁家思妇见之叹，蓬首不梳心历乱。","盛年夫壻长别离，岁暮相逢色凋换。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["离别","思念"],"天气":["写风"]},"theme_conf":0.668},{"uid":"9c92bbd7-1c25-4ea2-8854-8db8e6de5284","title":"雨四首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["物色岁将晏，天隅人未归。","朔风鸣淅淅，寒雨下霏霏。","多病久加饭，衰容新授衣。","时危觉凋丧，故旧短书稀。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写风","写雨"]},"theme_conf":0.91},{"uid":"48703e8c-71bb-4c72-b21f-9dbde75ee5af","title":"晚至华阴","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["腊尽促归心，行人及华阴。","云霞仙掌出，松柏古祠深。","野渡冰生岸，寒川烧隔林。","温泉看渐近，宫树晚沈沈。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.579},{"uid":"87589e47-69eb-4b30-8204-5678cb0c8636","title":"游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故窠思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰归百年内，唯愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何难哉，北斗不可斟。","夜静星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蟋蟋催寒碪。","立身计几悮，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧罔古今。","胡为不归欤，辜负匣中琴。","腰下是何物，牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山窅岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾宵汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分湮沈。","层城登云韶，王府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"恬淡","mood2":["愁怨","悲怆"],"scene":["秋","江","月","夜","鸟"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.292},{"uid":"31bc78e4-ece6-4a4f-b5bb-a8c00df6c620","title":"杂曲歌辞 鸣雁行","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动地来，吹起沙上声。","闺中有边思，玉筯此时横。","莫怕儿女恨，主人烹不鸣。"],"theme":"羁旅思乡","theme2":["闺情宫怨","亲情"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"],"天气":["写风"],"动物":["写鸟"]},"theme_conf":0.41},{"uid":"41d292d2-b752-4c30-8b6b-7b7380f2f9bd","title":"赋得","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"],"theme":"咏物","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","月","鸟"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.39},{"uid":"002801a4-8a5f-4931-83cd-49a1f94b0e51","title":"元日观百僚朝会","author":"包佶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万国贺唐尧，清晨会百僚。","花冠萧相府，绣服霍嫖姚。","寿色凝丹槛，欢声彻九霄。","御𬬻分兽炭，仙管弄云韶。","日照金觞动，风吹玉佩摇。","都城献赋者，不得共趋朝。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.9},{"uid":"d613d731-0abc-41a1-87dd-aecd74931800","title":"望初月简于吏部","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["泬寥中秋夜，坐见如钩月。","始从西南升，又欲西南没。","全移河上影，暂透林间缺。","纵待三五时，终为千里别。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月","中秋"],"cats":{"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.82},{"uid":"3ceefec8-ea4d-4e8d-9059-9a35acdfa91c","title":"八月灯夕寄游越施秀才","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["四天净色寒如水，八月清辉冷似霜。","想得越人今夜见，孟家珠在镜中央。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["月","江南","夜"],"cats":{"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.91},{"uid":"cb341afc-6306-4758-9cc0-48d26463dd66","title":"韦晤宅听歌","author":"欧阳詹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["服制虹霓鬓似云，萧郎屋里上清人。","等闲逐酒倾杯乐，飞尽虹梁一夜尘。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["酒"],"cats":{"天气":["彩虹"]},"theme_conf":0.799},{"uid":"361a3e5e-ef71-4749-b39a-aa2f5d9180e4","title":"听董大弹胡笳声兼寄语弄房给事","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["蔡女昔造胡笳声，一弹一十有八拍。","胡人落泪沾边草，汉使断肠对归客。","古戍苍苍烽火寒，大荒沈沈飞雪白。","先拂商弦后角羽，四郊秋叶惊摵摵。","董夫子，通神明，深山窃听来妖精。","言迟更速皆应手，将往复旋如有情。","空山百鸟散还合，万里浮云阴且晴。","嘶酸雏鴈失群夜，断绝胡儿恋母声。","川为净其波，鸟亦罢其鸣。","乌孙部落家乡远，逻娑沙尘哀怨生。","幽音变调忽飘洒，长风吹林雨堕瓦。","迸泉飒飒飞木末，野鹿呦呦走堂下。","长安城连东掖垣，凤凰池对青琐门。","高才脱略名与利，日夕望君抱琴至。"],"theme":"题画咏艺","theme2":["送别"],"style":"豪放","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.96},{"uid":"4c91b589-bd48-42db-8034-5b8c236dd885","title":"琴曲歌辞 别鹤","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["分飞共所从，六翮势摧风。","声断碧云外，影孤明月中。","青田归路远，月桂旧巢空。","矫翼知何处，天涯不可穷。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["离别","孤独"],"天气":["月亮"],"动物":["写鸟"]},"theme_conf":0.534},{"uid":"cp645ccc138fd1c2","title":"秦楼月・忆秦娥","author":"范成大","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楼阴缺。","阑干影卧东厢月。","东厢月。","一天风露，杏花如雪。","隔烟催漏金虬咽。","罗帏暗淡灯花结。","灯花结。","片时春梦，江南天阔。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["楼","月"],"cats":{"抒情":["思念","闺怨"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"be2bff30-cbdc-4dde-87d4-ea7021125a4b","title":"古乐府飞龙曲留上陈左相","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["德以精灵降，时膺梦寐求。","苍生谢安石，天子富平侯。","尊俎资高论，岩廊挹大猷。","相门连户牖，卿族嗣弓裘。","豁达云开霁，清明月映秋。","能为吉甫颂，善用子房筹。","阶砌思攀陟，门阑尚阻修。","高山不易仰，大匠本难投。","迹与松乔合，心缘启沃留。","公才山吏部，书癖杜荆州。","幸沐千年圣，何辞一尉休。","折腰知宠辱，廻首见沈浮。","天地庄生马，江湖范蠡舟。","逍遥堪自乐，浩荡信无忧。","去此从黄绶，归欤任白头。","风尘与霄汉，瞻望日悠悠。"],"theme":"应制干谒","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["月","山","园林","清明","江"],"cats":{"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.95},{"uid":"865bf66e-c1ad-4fee-8ab0-45876065155a","title":"同刘晃喜雨","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["节变寒初尽，时和气已春。","繁云先合寸，膏雨自依旬。","飒飒飞平野，霏霏静暗尘。","悬知花叶意，朝夕望中新。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":0.78},{"uid":"cd66d8b3-abe6-4316-ab34-b88a4bb8bb83","title":"杂曲歌辞 北风行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["烛龙栖寒门，光曜犹旦开。","日月照之何不及此，惟有北风怒号天上来。","燕山雪花大如席，片片吹落轩辕台。","幽州思妇十二月，停歌罢笑双蛾摧。","倚门望行人，念君长城苦寒良可哀。","别时提劒救边去，遗此虎文金髀钗。","中有一双白羽箭，蜘蛛结网生尘埃。","箭空在，人今战死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["雪","冬","雨"],"cats":{"抒情":["闺怨"],"山水":["黄河"],"天气":["写风"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.317},{"uid":"cpc4cd8e0d3c721d","title":"摸鱼儿","author":"朱嗣发","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对西风、鬓摇烟碧，参差前事流水。","紫丝罗带鸳鸯结，的的镜盟钗誓。","浑不记、漫手织回文，几度欲心碎。","安花著蒂。","奈雨覆云翻，情宽分窄，石上玉簪脆。","朱楼外。","愁压空云欲坠。","月痕犹照无寐。","阴晴也只随天意。","枉了玉消香碎。","君且醉。","君不见、长门青草春风泪。","一时左计。","悔不早荆钗，暮天修竹，头白倚寒翠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.733},{"uid":"80e19627-4051-46fc-806c-da3defb76cd1","title":"陪王侍御同登东山最高顶宴姚通泉晚携酒泛江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姚公美政谁与俦，不减昔时陈太丘。","邑中上客有柱史，多暇日陪骢马游。","东山高顶罗珍羞，下顾城郭销我忧。","清江白日落欲尽，复携美人登彩舟。","笛声愤怨哀中流，妙舞逶迤夜未休。","灯前往往大鱼出，听曲低昂如有求。","三更风起寒浪涌，取乐喧呼觉船重。","满空星河光破碎，四座宾客色不动。","请公临深莫相违，回船罢酒上马归。","人生欢会岂有极，无使霜过沾人衣。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","酒","山","江","舟"],"cats":{"山水":["江河"],"天气":["星星"],"人物":["女子"],"食物":["写酒"]},"theme_conf":0.407},{"uid":"a8e39b30-119d-4b4f-b557-da792950a2a3","title":"杂曲歌辞 行路难三首 三","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["飞雪断道冰成梁，侯家炽炭雕玉房。","蟠龙吐耀虎喙张，熊蹲豹掷争低昂。","攒峦丛崿射朱光，丹霞翠雾飘奇香。","美人四向回明珰，雪山冰谷晞太阳。","星躔奔走不得止，奄忽双燕栖虹梁。","风台露榭生光饰，死灰弃置参与商。","盛时一去贵反贱，桃笙葵扇安可常。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思乡"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"811a5f9e-0df5-46f1-a587-0d4df7bca5a0","title":"无题四首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["飒飒东风细雨来，芙蓉塘外有轻雷。","金蟾啮鏁烧香入，玉虎牵丝汲井回。","贾氏窥帘韩掾少，宓妃留枕魏王才。","春心莫共花争发，一寸相思一寸灰。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雨","春","花"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.713},{"uid":"954bc2e7-212b-4af0-afc2-f9230822a784","title":"送孙泼赴云中","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄骢少年舞双戟，目视旁人皆辟易。","百战能夸陇上儿，一身复作云中客。","寒风动地气苍茫，横吹先悲出塞长。","敲石军中传夜火，斧冰河畔汲朝浆。","前锋直指阴山外，虏骑纷纷胆应碎。","匈奴破尽人看归，金印酬功如斗大。"],"theme":"送别","theme2":["边塞征战"],"style":"雄浑","style2":["悲慨","幽峭"],"mood":"悲怆","mood2":[],"scene":["塞外","夜"],"cats":{"抒情":["伤感"],"天气":["写云"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.479},{"uid":"f2df70bb-0958-4bc6-bef3-593eae26d678","title":"田家秋日送友","author":"于良史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["苍茫日初宴，遥野云初收。","残雨北山里，夕阳东渡头。","舟依渔溓合，水入田家流。","何意君迷驾，山林应有秋。"],"theme":"山水田园","theme2":["送别"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["太阳"],"生活":["田野"]},"theme_conf":0.412},{"uid":"3d4e85e1-0bed-4e7b-8bb6-81677d9f448d","title":"杂曲歌辞 轻薄行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹏，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沈月上且鬬鸡，醉来莫问天高低。","伯阳道德何涕唾，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"cdc8c314-14e2-4e5d-a692-70986b3a2a25","title":"和李公七夕","author":"任希古","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["落日照高牖，凉风起庭树。","悠悠天宇平，昭昭月华度。","开轩卷绡幕，延首晞云路。","层汉有灵妃，仙居无与晤。","履化悲流易，临川怨迟暮。","昔从九春徂，方此三秋遇。","瑶驾越星河，羽盖凝珠露。","便妍耀井色，窈窕凌波步。","始阅故人新，俄见新人故。","掩泪收机石，衔啼襞纨素。","惆怅何伤已，裴回劳永慕。","无由西北归，空自东南顾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"愁怨","mood2":["惆怅","悲怆"],"scene":["七夕"],"cats":{"抒情":["友情","伤感"],"天气":["月亮","星星"],"节日":["七夕节"]},"theme_conf":0.76},{"uid":"05dda800-bd7b-43f0-b0f4-6edeafa87e5f","title":"酬孟武昌苦雪","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["积[雪]闲山路，有人到庭前。","云是孟武昌，令献苦雪篇。","长吟未及终，不觉为凄然。","古之贤达者，与世竟何异。","不能救时患，讽谕以全意。","知公惜春物，岂非爱时和。","知公苦阴雪，伤彼灾患多。","奸凶正驱驰，不合问君子。","林莺与野兽，无乃怨于此。","兵兴向九岁，稼穑谁能忧。","何时不发卒，何日不杀牛。","耕者日已少，耕牛日已希。","皇天复何忍，更又恐毙之。","自经危乱来，触物堪伤叹。","见君问我意，只益胸中乱。","山禽饥不飞，山木冻皆折。","悬泉化为冰，寒水近不热。","出门望天地，天地皆昏昏。","时见双峰下，雪中生白云。"],"theme":"民生疾苦","theme2":["山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["伤感"],"山水":["瀑布"],"天气":["写雪"]},"theme_conf":0.319},{"uid":"cp4bccf303b04386","title":"女冠子","author":"蒋捷","dynasty":"宋","section":"宋词","form":"词","paragraphs":["蕙花香也。","雪晴池馆如画。","春风飞到，宝钗楼上，一片笙箫，琉璃光射。","而今灯漫挂。","不是暗尘明月，那时元夜。","况年来、心懒意怯，羞与蛾儿争要。","江城人悄初更打。","问繁华谁解，再向天公借。","剔残红灺。","但梦里隐隐，钿车罗帕。","吴笺银粉砑。","待把旧家风景，写成闲话。","笑绿鬟邻女，倚窗犹唱，夕阳西下。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":["欢愉"],"scene":["夜","月","花","雪"],"cats":{"天气":["月亮"]},"theme_conf":0.93},{"uid":"2065dc7a-5ac9-406f-b7cd-285c5b5293df","title":"晚渡渭桥寄示京邑游好","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行背城阙，驱马独悠悠。","寥落百年事，裴回万里忧。","途遥日向夕，时晚鬓将秋。","滔滔俯东逝，耿耿泣西浮。","长虹掩钓浦，落雁下星洲。","草变黄山曲，花飞清渭流。","迸水惊愁鹭，腾沙起狎鸥。","一赴清泥道，空思玄灞游。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["伤感","孤独"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.501},{"uid":"19a657e3-0b2b-4c6b-b69b-14057f346891","title":"从军行","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["丈夫四方志，结发事远游。","远游历燕蓟，独戍边城陬。","西风垅水寒，明月关山悠。","酬恩仗孤剑，十年弊貂裘。","封侯属何人，磋跎雪盈头。","老马思故枥，穷鳞忆深流。","弹铗动深慨，浩歌气横秋。","报国期努力，功名良见收。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"慷慨","mood2":["孤寂"],"scene":["月","秋","雪"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.641},{"uid":"b5cbb21b-6545-4746-995f-b084fca74d5e","title":"寄净虚上人初至云门","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒踪白云里，法侣自提携。","竹径通城下，松门隔水西。","方同沃洲去，不似武陵迷。","仿佛方知处，高峰是会稽。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":0.86},{"uid":"a72f115d-7bd1-4549-a495-dc1043f2a8a6","title":"和韩郎中扬子津玩雪寄严维","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雪深扬子岸，看柳尽成梅。","山色潜知近，潮声只听来。","夜禽惊晓散，春物受寒催。","粉署生新兴，瑶华寄上才。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"天气":["写雪"]},"theme_conf":0.96},{"uid":"b2883592-eaf5-47a2-bd3d-7ded35fda71a","title":"谢友生遗端溪砚瓦","author":"李咸用","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["寻常濡翰次，恨不到端溪。","得自新知己，如逢旧解携。","玩余轻照乘，谢欲等悬黎。","静对胜凡客，闲窥忆好题。","娲天补剩石，昆剑切来泥。","著指痕犹湿，停旬水未低。","呵云润柱础，笔彩饮虹霓。","鹆眼工谙谬，羊肝士乍刲。","连澌光比镜，囚墨腻于䃜。","书信成池黑，吟须到日西。","正夸忧盗窃，将隐怯攀跻。","捧受同交印，矜持过秉珪。","草颠终近旭，嬾癖必无嵇。","用合缘鹦鹉，珍应负会稽。","贞姿还落落，寒韵或凄凄。","风月情相半，烟花思岂迷。","宜从方袋挈，枉把短行批。","浅小金为斗，泓澄玉作堤。","遇人依我惜，想尔与天齐。","□□□□□，行时秪独赍。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":["恬淡"],"scene":[],"cats":{"抒情":["友情","感恩"],"天气":["彩虹"],"人生":["读书"]},"theme_conf":0.748},{"uid":"533e2212-7d88-4b6d-9f5f-a8d42f4d3627","title":"耳聋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["生年鹖冠子，叹世鹿皮翁。","眼复几时暗，耳从前月聋。","猨鸣秋泪缺，雀噪晚愁空。","黄落惊山树，呼儿问朔风。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","冬","山"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.88},{"uid":"42c8db32-a5d6-4d73-869d-36bd63632165","title":"九日五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故里樊川菊，登高素浐源。","他时一笑后，今日几人存。","巫峡蟠江路，终南对国门。","系舟身万里，伏枕泪双痕。","为客裁乌帽，从儿具绿尊。","佳辰对群盗，愁绝更谁论。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"bbad458d-8996-48f7-856d-1931d49f0e2c","title":"咏雨","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["和气吹绿野，梅雨洒芳田。","新流添旧涧，宿雾足朝烟。","雁湿行无次，花沾色更鲜。","对此欣登岁，披襟弄五弦。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"]},"theme_conf":0.504},{"uid":"2c4755aa-a07d-4e0a-97b6-afdf906a3f00","title":"天宝初南曹小司寇舅于我太夫人堂下累土为山一匮盈尺以代彼朽木承诸焚香瓷瓯瓯甚安矣旁植慈竹盖兹数峰嵚岑婵娟宛有尘外数致乃不知兴之所至而作是诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一匮功盈尺，三峰意出群。","望中疑在野，幽处欲生云。","慈竹春阴覆，香炉晓势分。","惟南将献寿，佳气日氛氲。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"恬淡","mood2":["欢愉"],"scene":["山","中秋"],"cats":{"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"],"食物":["写茶"]},"theme_conf":0.784},{"uid":"cp334c6d9b3adb62","title":"月下笛","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感","怀古"],"山水":["西湖"],"天气":["月亮"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.416},{"uid":"68a3e39c-58e3-4b5b-890a-22f1e3f1c185","title":"杂曲歌辞 夜夜曲","author":"王偃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["北斗星移银汉低，班姬愁思凤城西。","青槐陌上人行绝，明月楼前乌夜啼。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮","星星"]},"theme_conf":0.95},{"uid":"c81a3a3f-0eec-4fe0-b482-40c50959b37e","title":"望雪","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冻云宵徧岭，素雪晓凝华。","入牖千重碎，迎风一半斜。","不妆空散粉，无树独飘花。","萦空慙夕照，破彩谢晨霞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":0.531},{"uid":"e848498b-1ab8-48c7-8b3e-e98b5550b855","title":"苏端薛复筵简薛华醉歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["文章有神交有道，端复得之名誉早。","爱客满堂尽豪翰，开筵上日思芳草。","安得健步移远梅，乱插繁花向晴昊。","千里犹残旧冰雪，百壶且试开怀抱。","垂老恶闻战鼓悲，急觞为缓忧心捣。","少年努力纵谈笑，看我形容已枯槁。","坐中薛华善醉歌，歌辞自作风格老。","近来海内为长句，汝与山东李白好。","何刘沈谢力未工，才兼鲍昭愁绝倒。","诸生颇尽新知乐，万事终伤不自保。","气酣日落西风来，愿吹野水添金杯。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","清新"],"mood":"愁怨","mood2":["欢愉","悲怆"],"scene":["酒"],"cats":{"抒情":["伤感"],"天气":["写雪"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"e5060cf4-fac1-454f-b85e-014ec8c2870b","title":"赋得白日半西山","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红轮不暂驻，乌飞岂复停。","岑霞渐渐落，溪阴寸寸生。","藿叶随光转，葵心逐照倾。","晚烟含树色，栖鸟杂流声。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"天气":["太阳"]},"theme_conf":0.587},{"uid":"50cd4ba1-47b5-476b-9b7c-1b3bba01cad6","title":"夏日原西避暑寄吟友","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["热烟疎竹古原西，日日乘凉此杖藜。","闲处雨声随霹雳，旱田人望隔虹霓。","蝉依独树干吟苦，鸟忆平川渴过齐。","别有相招好泉石，瑞花瑶草尽堪携。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂","恬淡"],"scene":["夏"],"cats":{"抒情":["友情","思念","孤独"],"四季":["夏天"],"天气":["彩虹","太阳"]},"theme_conf":0.88},{"uid":"47dbfc92-dd51-458f-859a-1953cde28460","title":"秋日作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居值秋节，此日更愁辛。","寂寞无一事，蒿莱通四邻。","闭门生白发，回首忆青春。","岁月不相待，交游随众人。","云霄何处托，愚直有谁亲。","举酒聊自劝，穷通信尔身。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["秋"],"cats":{"抒情":["思念","伤感","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"人生":["青春"]},"theme_conf":0.9},{"uid":"96b213f7-21b6-47a8-936c-39dde6ca7969","title":"相和歌辞 櫂歌行","author":"徐坚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["写云"]},"theme_conf":0.579},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"3057f1b2-f2c5-482d-a9c8-b4d1a02125e9","title":"追酬故高蜀州人日见寄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自蒙蜀州人日作，不意清诗久零落。","今晨散帙眼忽开，迸泪幽吟事如昨。","呜呼壮士多慷慨，合沓高名动寥廊。","叹我凄凄求友篇，感时郁郁匡君略。","锦里春光空烂熳，瑶墀侍臣已冥莫。","潇湘水国傍鼋鼍，鄠杜秋天失雕鹗。","东西南北更谁论，白首扁舟病独存。","遥拱北辰缠寇盗，欲倾东海洗乾坤。","边塞西蕃最充斥，衣冠南渡多崩奔。","鼓瑟至今悲帝子，曳裾何处觅王门。","文章曹植波澜阔，服食刘安德业尊。","长笛谁能乱愁思，昭州词翰与招魂。"],"theme":"悼亡挽歌","theme2":["节令风俗"],"style":"悲慨","style2":["沉郁","绮丽"],"mood":"愁怨","mood2":[],"scene":["舟","塞外"],"cats":{"抒情":["伤感","悼亡"],"天气":["太阳"]},"theme_conf":0.88},{"uid":"90652c8c-0dbc-4eae-8e27-edd71d621b92","title":"汝坟别业","author":"祖咏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["失路农为业，移家到汝坟。","独愁常废卷，多病久离群。","鸟雀垂窻柳，虹霓出涧云。","山中无外事，樵唱有时闻。"],"theme":"山水田园","theme2":["送别","山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["离别","伤感","孤独"],"天气":["彩虹"]},"theme_conf":0.82},{"uid":"874a0ca3-62ca-4c9f-976b-895b035ac3d6","title":"边城落日","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["紫塞流沙北，黄图灞水东。","一朝辞俎豆，万里逐沙蓬。","候月恒持满，寻源屡凿空。","野昏边气合，烽迥戍烟通。","膂力风尘倦，疆场岁月穷。","河流控积石，山路远崆峒。","壮志凌苍兕，精诚贯白虹。","君恩如可报，龙剑有雌雄。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"慷慨","mood2":[],"scene":["塞外","月"],"cats":{"天气":["太阳"],"人生":["励志","梦想"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"49e8d65c-a254-42eb-9bb6-152ba3d3986e","title":"别韦五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["徒然酌桮酒，不觉散人愁。","相识仍远别，欲归翻旅游。","夏云满郊甸，明月照河洲。","莫恨征途远，东看漳水流。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","月","夏"],"cats":{"抒情":["离别","伤感"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.721},{"uid":"70ea423c-d3c0-4870-885f-4ebadc8b8fcf","title":"久雨期王将军不至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天雨萧萧滞茅屋，空山无以慰幽独。","锐头将军来何迟，令我心中苦不足。","数看黄雾乱玄云，时听严风折乔木。","泉源泠泠杂猿狖，泥泞漠漠饥鸿鹄。","岁暮穷阴耿未已，人生会面难再得。","忆尔腰下铁丝箭，射杀林中雪色鹿。","前者坐皮因问毛，知子历险人马劳。","异兽如飞星宿落，应弦不碍苍山高。","安得突骑只五千，崒然眉骨皆尔曹。","走平乱世相催促，一豁明主正郁陶。","忆昔范增碎玉斗，未使吴兵著白袍。","昏昏阊阖闭氛祲，十月荆南雷怒号。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写雨"],"人生":["梦想"]},"theme_conf":0.558},{"uid":"df4de5cf-ac53-4137-b2be-34b163ec4d73","title":"相和歌辞 子夜冬歌","author":"薛耀","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["朔风扣群木，岩霜凋百草。","借问月中人，安得长不老。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["写风"]},"theme_conf":0.84},{"uid":"a4d6fab0-17cf-448c-97f9-d1345ad69217","title":"青云干吕","author":"王履贞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["异方占瑞气，干吕见青云。","表圣兴中国，来王谒大君。","迎祥殊大乐，叶庆类横汾。","自感明时起，非因触石分。","暎霄难辨色，从吹乍成文。","须使流千载，垂芳在典坟。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"7c1f0ae4-dada-485d-a817-cc932bb685d7","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 六","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹如晕，更复（京本作「或」）似弓形。","有若白虹形断续，兼之五六见城营，皆主血光成（京本作「生」。","京本注：「或见五六月」）。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"24f9e8b4-e32d-49e7-af89-50e05880b662","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行云递崇高，飞雨霭而至。","潺潺石间溜，汩汩松上驶。","亢阳乘秋热，百谷皆已弃。","皇天德泽降，焦卷有生意。","前雨伤卒暴，今雨喜容易。","不可无雷霆，间作鼓增气。","佳声达中宵，所望时一致。","清霜九月天，髣髴见滞穗。","郊扉及我私，我圃日苍翠。","恨无抱瓮力，庶减临江费。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["雨","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"6ecbed64-2409-4f6d-ade3-ccfec85ff92c","title":"梅雨","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅实迎时雨，苍茫值晚春。","愁深楚猿夜，梦断越鸡晨。","海雾连南极，江云暗北津。","素衣今尽化，非为帝京尘。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"125c6392-6a3b-4ba2-a0af-d9520b6b7e6b","title":"咏雪","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["洁野凝晨曜，装墀带夕晖。","集条分树玉，拂浪影泉玑。","色洒妆台粉，花飘绮席衣。","入扇萦离匣，点素皎残机。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"]},"theme_conf":0.738},{"uid":"6113d640-c2f5-4e11-aaae-0368e78f3fb6","title":"七夕","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期人不见，天上喜新秋。","玉珮沾新露，香车渡浅流。","东西一水隔，迢遰两年愁。","别有穿针处，微明月暎楼。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["七夕","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"83e70b6e-ff59-4a3b-8e81-249ab0cda0c3","title":"月下独酌四首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["花间一壶酒，独酌无相亲。","举杯邀明月，对影成三人。","月既不解饮，影徒随我身。","暂伴月将影，行乐须及春。","我歌月裴回，我舞影零乱。","醒时同交欢，醉后各分散。","永结无情游，相期邈云汉。"],"theme":"闲适隐逸","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"食物":["写酒"]},"theme_conf":0.88},{"uid":"18801489-9f1d-4d5d-9618-66e682d3fc54","title":"寄司空曙","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["细雨柴门生远愁，向来诗句若为酬。","林花落处频中酒，海燕飞时独倚楼。","北郭晚晴山更远，南塘春尽水争流。","可能相别还相忆，莫遣杨花笑白头。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["老师"]},"theme_conf":0.92},{"uid":"88e98bed-27fa-4dbe-8d6e-e7cb8c3e4d97","title":"八月十五夜赠张功曹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["纤云四卷天无河，清风吹空月舒波。","沙平水息声影绝，一桮相属君当歌。","君歌声酸辞且苦，不能听终泪如雨。","洞庭连天九疑高，蛟龙出没猩鼯号。","十生九死到官所，幽居默默如藏逃。","下床畏蛇食畏药，海气湿蛰熏腥臊。","昨者州前搥大鼓，嗣皇继圣登夔臯。","赦书一日行万里，罪从大辟皆除死。","迁者追廻流者还，涤瑕荡垢清朝班。","州家申名使家抑，坎轲祗得移荆蛮。","判司卑官不堪说，未免捶楚尘埃间。","同时辈流多上道，天路幽险难追攀。","君歌且休听我歌，我歌今与君殊科。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["月","中秋","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"4d9ab24a-3717-4627-8dce-23f953d6e82d","title":"正月十五夜灯","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千门开锁万灯名，正月中旬动帝京。","三百内人连袖舞，一时天上著词声。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵","夜","月"],"cats":{"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.96},{"uid":"76ea75c2-9fce-4c89-9452-c7f53343d43f","title":"郊庙歌辞 祀风师乐章 亚献终献","author":"包佶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["膋芗备，玉帛陈。","风动物，乐感神。","三献终，百神臻。","草木荣，天下春。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":0.84},{"uid":"4d16ccaa-a7a3-45e6-b0d9-6e94e3e1d99d","title":"缆船苦风戏题四韵奉简郑十三判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚岸朔风疾，天寒鸧鸹呼。","涨沙霾草树，舞雪渡江湖。","吹帽时时落，维舟日日孤。","因声置驿外，为觅酒家垆。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["舟","冬","江"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["写风"]},"theme_conf":0.86},{"uid":"dc52501e-3598-4ebf-bba8-7bf0c3a9a172","title":"归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["化佛示持帚，仲尼称执鞭。","列生御风归，饲豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长绶趋遥泉。","开士行何苦，双瓶胝两肩。","萧寺百余僧，东厨正扬烟。","露足沙石裂，外形巾褐穿。","若其有此身，岂得安稳眠。","独出违顺境，不为寒暑还。","大圣于其中，领我心之虔。","万法常空灭，无生因忍全。","一国一释迦，一灯分百千。","永愿遗世知，现身弥勒前。","潜容偏虚空，灵响不可传。","智慧舍利佛，神通自干连。","阿若楚系简帛陈如，迦叶迦旜延。","左右二菩萨，文殊幷普贤。","身披六铢衣，亿刦为大僊。","宝塔宝楼阁，重簷交梵天。","譬如一明珠，共赞光白圆。","天魔波[旬]等，降伏金刚坚。","野叉罗刹鬼，亦赦尘垢缠。","乃致金翅鸟，吞龙护洪渊。","一十一众中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等无颇偏。","天子事端拱，大臣行其权。","玉堂无蝇飞，五月冰凛筵。","尽力答明主，犹自招罪愆。","九族无白身，百花动婵娟。","神圣恶如此，物华不能妍。","禄山一微胡，驱马来自燕。","宛彼宫阙丽，如何犬羊膻。","苦哉千万人，流血成丹川。","此辈之死后，镬汤所熬煎。","业风吹其魂，猛火烧其烟。","独有丁行者，无忧树枝边。","市头盲老人，长者乞一钱。","韬照多密用，为君吟此篇。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","鸟","中秋","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["哲理"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"982f789a-c377-4b64-808a-56f36abf9ff0","title":"可叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上浮云如白衣，斯须改变如苍狗。","古往今来共一时，人生万事无不有。","近者抉眼去其夫，河东女儿身姓柳。","丈夫正色动引经，酆城客子王季友。","群书万卷常暗诵，孝经一通看在手。","贫穷老瘦家卖屐，好事就之为携酒。","豫章太守高帝孙，引为宾客敬颇久。","闻道三年未曾语，小心恐惧闭其口。","太守得之更不疑，人生反复看亦丑。","明月无瑕岂容易，紫气郁郁犹冲斗。","时危可仗真豪俊，二人得置君侧否。","太守顷者领山南，邦人思之比父母。","王生早曾拜颜色，高山之外皆培𪣻。","用为羲和天为成，用平水土地为厚。","王也论道阻江湖，李也丞疑旷前后。","死为星辰终不灭，致君尧舜焉肯朽。","吾辈碌碌饱饭行，风后力牧长回首。"],"theme":"羁旅思乡","theme2":["亲情"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.523},{"uid":"a61fdeb6-e633-4c36-bb30-d57d1e392c1c","title":"横吹曲辞 雨雪曲","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天山一丈雪，杂雨夜霏霏。","湿马胡歌乱，经烽汉火微。","丁零苏武别，疎勒范羌归。","若著关头过，长榆叶定稀。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雨","雪"],"cats":{"天气":["写雨","写雪"]},"theme_conf":0.819},{"uid":"44b128d9-264f-48b0-83e9-751db7dbb08e","title":"题高云客舍","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤兴日自深，浮云非所仰。","窗中西城峻，树外东川广。","晏起簪葛巾，闲吟倚藜杖。","阮公道在醉，庄子生常养。","五柳转扶疎，千峰恣来往。","清秋香秔获，白露寒菜长。","吴国滞风烟，平陵延梦想。","时人趋缨弁，高鸟违罗网。","世事徒乱纷，吾心方浩荡。","唯将山与水，处处谐真赏。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["山","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.368},{"uid":"8fc09639-9e38-402f-9827-589c1cc161ff","title":"夏日对雨寄朱放拾遗","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才非谷永传，无意谒王侯。","小暑金将伏，微凉麦正秋。","远山欹枕见，暮雨闭门愁。","更忆东林寺，诗家第一流。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["相思"],"scene":["夏","雨"],"cats":{"抒情":["思念","伤感"],"四季":["夏天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"c7166837-c70d-4cfd-bf45-baf6930473bf","title":"酬卫八雪中见寄","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["季冬忆淇上，落日归山樊。","旧宅带流水，平田临古村。","雪中望来信，醉里开衡门。","果得希代宝，缄之那可论。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"98b9c819-c287-4a62-b844-f08172081922","title":"奉和圣制同刘晃喜雨应制","author":"张说","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青气含春雨，知从岱岳来。","行云避师出，洒雨待车廻。","厌浥尘清道，空蒙柳映台。","最宜三五夜，晴月九重开。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"山水":["泰山"],"天气":["写雨"]},"theme_conf":0.98},{"uid":"e34aa8fc-aa37-4d16-bc86-1c9cc6362d68","title":"又得云字","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["何事千年遇圣君，坐令双鬓老如云。","南行更入深山浅，岐路悠悠水自分。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"]},"theme_conf":1.0},{"uid":"cp7c35167f827ea7","title":"风入松","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["听风听雨过清明。","愁草瘗花铭。","楼前绿暗分携路，一丝柳、一寸柔情。","料峭春寒中酒，交加晓梦啼莺。","西园日日扫林亭。","依旧赏新晴。","黄蜂频扑秋千索，有当时、纤手香凝。","惆怅双鸳不到，幽阶一夜苔生。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","清明","楼","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"天气":["写风"],"节日":["清明节"]},"theme_conf":0.446},{"uid":"10ef9dd5-f761-4463-9d90-fa9a426ac89c","title":"横吹曲辞 关山月","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱边歌。","海边漠漠天气白，胡儿夜度黄龙碛。","军中探骑暮出城，伏兵暗处低旌戟。","溪水连地霜草平，野𫘞寻水碛中鸣。","陇头风急雁不下，沙场苦战多流星。","可怜万国关山道，年年战骨多秋草。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","山"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.559},{"uid":"15079155-e95e-4abc-b36e-f6b605848f37","title":"杂曲歌辞 独不见","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家小妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催下叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁知含愁独不见，使妾明月照流黄。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月","秋"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.698},{"uid":"db40b5ca-03a8-4d1f-a4e4-cde477bee05e","title":"横吹曲辞 雨雪曲","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["边声四合殷河流，雨雪飞来徧陇头。","铁岭探人迷鸟道，阴山飞将湿貂裘。","斜飘旌斾过戎帐，半杂风沙入戍楼。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪","雨"],"cats":{"天气":["写雨","写雪"],"生活":["边塞"]},"theme_conf":0.661},{"uid":"de7ae571-5241-4ea9-82f7-0d49eeebd710","title":"月蚀诗效玉川子作","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["元和庚寅斗插子，月十四日三更中。","森森万木夜僵立，寒气屃奰顽无风。","月形如白盘，完完上天东。","忽然有物来噉之，不知是何虫。","如何至神物，遭此狼狈凶。","星如撒沙出，攒集争强雄。","油灯不照席，是夕吐燄如长虹。","玉川子，涕泗下，中庭独行。","念此日月者，为天之眼睛。","此犹不自保，吾道何由行。","尝闻古老言，疑是虾蟆精。","径圆千里纳女腹，何处养女百丑形。","杷沙脚手钝，谁使女解缘青冥。","黄帝有四目，帝舜重其明。","今天祗两目，何故许食使偏盲。","尧呼大水浸十日，不惜万国赤子鱼头生。","女于此时若食日，虽食八九无嚵名。","赤龙黑鸟烧口热，翎鬣倒侧相搪撑。","婪酣大肚遭一饱，饥肠彻死无由鸣。","后时食月罪当死，天罗磕帀何处逃汝刑。","玉川子立于庭而言曰，地行贱臣仝。","再拜敢告上天公，臣有一寸刃。","可刳凶蟆肠，无梯可上天。","天阶无由有臣踪，寄牋东南风。","天门西北祈风通，丁宁附耳莫漏泄。","薄命正值飞廉慵，东方青色龙。","牙角何呀呀，从官百余座。","嚼啜烦官家，月蚀汝不知。","安用为龙窟天河，赤鸟司南方。","尾秃翅觰沙，月蚀于汝头。","汝口开呀呀，虾蟆掠汝两吻过。","忍学省事不以汝觜啄虾蟆，於菟蹲于西。","旗旄卫毵㲚，既从白帝祠。","又食于蜡礼有加，忍令月被恶物食。","枉于汝口插齿牙，乌龟怯奸。","怕寒缩颈，以壳自遮。","终令夸蛾抉汝出，卜师烧锥钻灼满板如星罗。","此外内外官，琐细不足科。","臣请悉埽除，慎勿许语令啾哗。","幷光全耀归我月，盲眼镜净无纤瑕。","弊蛙拘送主府官，帝箸下腹尝其皤。","依前使兔操杵臼，玉阶桂树闲婆娑。","姮娥还宫室，太阳有室家。","天虽高，耳属地。","感臣赤心，使臣知意。","虽无明言，潜喻厥旨。","有气有形，皆吾赤子。","虽忿大伤，忍杀孩穉。","还汝月明，安行于次。","尽释众罪，以蛙磔死。"],"theme":"送别","theme2":["民生疾苦"],"style":"绮丽","style2":["豪放"],"mood":"恬淡","mood2":["孤寂","悲怆"],"scene":["月","夜"],"cats":{"抒情":["伤感","孤独"],"天气":["彩虹","月亮"]},"theme_conf":0.628},{"uid":"c64926d8-1757-4e1f-8096-dd24190f1ba1","title":"送萧十八与房侍御廻还","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常苦古人远，今见斯人古。","澹泊遗声华，周旋必邹鲁。","故交在梁宋，游方出庭户。","匹马鸣朔风，一身济河浒。","辛勤采兰咏，款曲翰林主。","岁月催别离，庭围远风土。","寥寥寒烟静，莽莽夕阴吐。","明发不在兹，青天眇难覩。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["园林","月","冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"c27daaf8-489e-4fdb-8d82-85a074f8fd2e","title":"闻友人入越幕因以诗赠","author":"罗邺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["稽岭春生酒冻销，烟鬟红袖恃娇饶。","岸边丛雪晴香老，波上长虹晚影遥。","正哭阮途归未得，更闻江笔赴嘉招。","人间荣瘁真堪恨，坐想征轩鬓欲凋。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南","雪","春","酒","花"],"cats":{"抒情":["友情"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.9},{"uid":"cp79ac7bfce7f15c","title":"满庭芳","author":"秦观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓色云开，春随人意，骤雨才过还晴。","古台芳榭，飞燕蹴红英。","舞困榆钱自落，秋千外、绿水桥平。","东风里，朱门映柳，低底按小秦筝。","多情。","行乐处，珠钿翠盖，玉辔红缨。","渐酒空金，花困蓬瀛。","豆蔻梢头旧恨，十年梦，屈指堪惊。","凭阑久，疏烟淡日，寂寞下芜城。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"078cc610-552e-4224-8413-3dda0ac3c0f5","title":"夏日联句","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["人皆苦炎热，我爱夏日长。","熏风自南来，殿阁生微凉。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["太阳"]},"theme_conf":0.72},{"uid":"9ad03d65-0953-4326-8d85-9e69bb02b4de","title":"和西川李尚书汉州微月游房太尉西湖","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["木落汉川夜，西湖悬玉钩。","旌旗环水次，舟檝泛中流。","目极想前事，神交如共游。","瑶琴久已绝，松韵自悲秋。"],"theme":"山水田园","theme2":["边塞征战"],"style":"婉约","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感"],"山水":["西湖"],"天气":["月亮"]},"theme_conf":0.545},{"uid":"a7ff247d-a11c-4ca9-a22f-ca420b8c537c","title":"帝京篇十首 三","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["移步出词林，停舆欣武宴。","雕弓写明月，骏马疑流电。","惊雁落虚弦，啼猿悲急箭。","阅赏诚多美，于兹乃忘倦。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"16115ead-7f11-404c-b6c5-1ea87057291a","title":"同崔员外綦毋拾遗九日宴京兆府李士曹","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今日好相见，群贤仍废曹。","晚晴催翰墨，秋兴引风骚。","绛叶拥虚砌，黄花随浊醪。","闭门无不可，何事更登高。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.78},{"uid":"45110b81-0f02-4c85-b72a-f2210d10c12f","title":"八哀诗 赠太子师汝阳郡王琎","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汝阳让帝子，眉宇真天人。","虬须似太宗，色映塞外春。","往者开元中，主恩视遇频。","出入独非时，礼异见群臣。","爱其谨洁极，倍此骨肉亲。","从容听朝后，或在风雪晨。","忽思格猛兽，苑囿腾清尘。","羽旗动若一，万马肃𬳽𬳽。","诏王来射雁，拜命已挺身。","箭出飞鞚内，上又回翠麟。","飜然紫塞翮，下拂明月轮。","胡人虽获多，天笑不为新。","王每中一物，手自与金银。","袖中谏猎书，扣马久上陈。","竟无衔橛虞，圣聪矧多仁。","官免供给费，水有在藻鳞。","匪唯帝老大，皆是王忠勤。","晚年务置醴，门引申白宾。","道大容无能，永怀侍芳茵。","好学尚贞烈，义形必沾巾。","挥翰绮绣扬，篇什若有神。","川广不可溯，墓久狐兔邻。","宛彼汉中郡，文雅见天伦。","何以开我悲，泛舟俱远津。","温温昔风味，少壮已书绅。","旧游易磨灭，衰谢增酸辛。"],"theme":"悼亡挽歌","theme2":["送别","边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["月","塞外","雪"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.99},{"uid":"9c5c45b3-3e85-4eeb-b9de-eba380e530b6","title":"杂歌谣辞 渔父歌 一","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西塞山边白鹭飞，桃花流水鳜鱼肥。","青箬笠，绿蓑衣，春江细雨不须归。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨","塞外"],"cats":{"天气":["写雨"],"人物":["父亲"]},"theme_conf":0.642},{"uid":"cpc94d671a952717","title":"鹧鸪天","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["池上红衣伴倚阑。","栖鸦常带夕阳还。","殷云度雨疏桐落，明月生凉宝扇闲。","乡梦窄，水天宽。","小窗愁黛澹秋山。","吴鸿好为传归信，杨柳阊门屋数间。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"恬淡","mood2":["愁怨"],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"]},"theme_conf":0.649},{"uid":"4b13e5da-48ea-4213-9ede-dd8cec48c7c3","title":"春雪间早梅","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梅将雪共春，彩艳不相因。","逐吹能争密，排枝巧妬新。","谁令香满座，独使净无尘。","芳意饶呈瑞，寒光助照人。","㻏珑开已徧，点缀坐来频。","那是俱疑似，须知两逼真。","荧煌初乱眼，浩荡忽迷神。","未许琼华比，从将玉树亲。","先期迎献岁，更伴占兹晨。","愿得长辉暎，轻微敢自珍。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"df572f9e-bc85-4b4b-bf6a-05b06c3244dc","title":"相和歌辞 凤台曲","author":"王无竞","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤台何逶迤，嬴女管参差。","一旦彩云至，身去无还期。","遗曲此台上，世人多学吹。","一吹一落泪，至今怜玉姿。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["楼"],"cats":{"抒情":["伤感","怀古"],"天气":["写云"]},"theme_conf":0.88},{"uid":"2e1e7ba7-1beb-4430-a7f2-3e5d7241beec","title":"送樊二十三侍御赴汉中判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["威弧不能弦，自尔无宁岁。","川谷血横流，豺狼沸相噬。","天子从北来，长驱振凋敝。","顿兵岐梁下，却跨沙漠裔。","二京陷未收，四极我得制。","萧索汉水清，缅通淮湖税。","使者纷星散，王纲尚旒缀。","南伯从事贤，君行立谈际。","生知七曜历，手画三军势。","冰雪净聪明，雷霆走精锐。","幕府辍谏官，朝廷无此例。","至尊方旰食，仗尔布嘉惠。","补阙暮征入，柱史晨征憩。","正当艰难时，实藉长久计。","回风吹独树，白日照执袂。","恸哭苍烟根，山门万重闭。","居人莽牢落，游子方迢递。","裴回悲生离，局促老一世。","陶唐歌遗民，后汉更列帝。","恨无匡复姿，聊欲从此逝。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.416},{"uid":"4e491c2f-c3c8-487f-8e76-63bd0a811b30","title":"庐山谣寄卢侍御虚舟","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我本楚狂人，凤歌笑孔丘。","手持绿玉杖，朝别黄鹤楼。","五岳寻仙不辞远，一生好入名山游。","庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。","金阙前开二峰长，银河倒挂三石梁。","香炉瀑布遥相望，回厓沓嶂凌苍苍。","翠影红霞映朝日，鸟飞不到吴天长。","登高壮观天地间，大江茫茫去不还。","黄云万里动风色，白波九道流雪山。","好为庐山谣，兴因庐山发。","闲窥石镜清我心，谢公行处苍苔没。","早服还丹无世情，琴心三叠道初成。","遥见仙人彩云里，手把芙蓉朝玉京。","先期汗漫九垓上，愿接卢敖游太清。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":["慷慨"],"scene":["山"],"cats":{"山水":["庐山","长江","瀑布"],"天气":["写云"]},"theme_conf":0.353},{"uid":"cf913d33-9ec7-4d06-a644-07dc1adafde1","title":"题张氏隐居二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春山无伴独相求，伐木丁丁山更幽。","涧道余寒历冰雪，石门斜日到林丘。","不贪夜识金银气，远害朝看糜鹿游。","乘兴杳然迷出处，对君疑是泛虚舟。"],"theme":"闲适隐逸","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","春","舟","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.88},{"uid":"8aab2742-0f6f-4708-8db5-19a81dc35be1","title":"西山兰若试茶歌","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["山僧后檐茶数丛，春来映竹抽新茸。","宛然为客振衣起，自傍芳丛摘鹰觜。","斯须炒成满室香，便酌砌下金沙水。","骤雨松声入鼎来，白云满盌花俳徊。","悠扬喷鼻宿酲散，清峭彻骨烦襟开。","阳崖阴岭各殊气，未若竹下莓苔地。","炎帝虽尝未解煎，桐君有箓那知味。","新芽连拳半未舒，自摘至煎俄顷余。","木兰沾露香微似，瑶草临波色不如。","僧言灵味宜幽寂，采采翘英为嘉客。","不辞缄封寄郡斋，甎井铜炉损标格。","何况蒙山顾渚春，白泥赤印走风尘。","欲知花乳清泠味，须是眠云跂石人。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["幽峭","婉约"],"mood":"孤寂","mood2":[],"scene":["山","花"],"cats":{"天气":["写雨"],"食物":["写茶"]},"theme_conf":0.387},{"uid":"a6250fd5-bdd4-4c24-9074-a3023c832ae4","title":"宿云溪观赋得秋灯引送客","author":"杨衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云房寄宿秋夜客，一灯荧荧照虚壁。","虫声呼客客未眠，几人语话清景侧。","不可离别愁纷多，秋灯秋灯奈别何。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜","元宵"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写云"],"节日":["元宵节"]},"theme_conf":0.466},{"uid":"c28c271b-70b9-422c-8bfd-6a062f40d40c","title":"天育骠骑歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["吾闻天子之马走千里，今之画图无乃是。","是何意态雄且杰，骏尾萧梢朔风起。","毛为绿缥两耳黄，眼有紫燄双瞳方。","矫矫龙性合变化，卓立天骨森开张。","伊昔太仆张景顺，监牧攻驹阅清峻。","遂令大奴守天育，别养骥子怜神俊。","当时四十万匹马，张公叹其材尽下。","故独写真传世人，见之座右久更新。","年多物化空形影，呜呼健步无由骋。","如今岂无騕褭与骅骝，时无王良伯乐死即休。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"天气":["写风"],"节日":["春节"]},"theme_conf":1.0},{"uid":"ff7aca6e-232d-464f-91cf-75f019591e69","title":"酬马八效古见赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["深崖无绿竹，秀色徒氛氲。","时代种桃李，无人顾此君。","奈何冰雪操，尚与蒿莱群。","愿托灵仙子，一声吹入云。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"天气":["写雪"],"动物":["写马"]},"theme_conf":0.86},{"uid":"23aa1422-258b-4783-a800-1f28dc71facd","title":"苦雪四首 三","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蒙蒙洒平陆，淅沥至幽居。","且喜润群物，焉能悲斗储。","故交久不见，鸟雀投吾庐。"],"theme":"咏物","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆","欢愉"],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.66},{"uid":"c56fd82e-2fab-4c3b-b52c-2631132e0ddf","title":"九日奉寄严大夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日应愁思，经时冒险艰。","不眠持汉节，何路出巴山。","小驿香醪嫩，重岩细菊斑。","遥知簇鞍马，回首白云间。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"cpf2a280a2cda3d4","title":"月照梨花・河传","author":"黄升","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼景。","方永。","重帘花影。","好梦犹酣，莺声唤醒。","门外风絮交飞。","送春归。","修蛾画了无人问。","几多别恨。","泪洗残妆粉。","不知郎马何处嘶。","烟草萋迷。","鹧鸪啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","月","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.737},{"uid":"694314d7-c1d5-4b3b-9e0d-b355697cced3","title":"九月九日","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居临玉扆，初律启金商。","凤阙澄秋色，龙闱引夕凉。","野净山气敛，林疎风露长。","砌兰亏半影，岩桂发全香。","满盖荷凋翠，圆花菊散黄。","挥鞭争电烈，飞羽乱星光。","柳空穿石碎，弦虚侧月张。","怯猿啼落岫，惊雁断分行。","斜轮低夕景，归斾拥通庄。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["月","山","重阳"],"cats":{"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"ab4f85b4-93fc-4040-85e4-0c28552e2407","title":"寒食直归遇雨","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食时看度，春游事已违。","风光连日直，阴雨半朝归。","不见红毬上，那论彩索飞。","惟将新赐火，向曙著朝衣。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","雨"],"cats":{"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.88},{"uid":"00a16385-1ebb-4923-a397-23253e7a0498","title":"紫阳真人歌（幷序）","author":"卢象","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见先生耳鼻有仙骨，自号狂生中有物。","金华侍讲三十年，儿戏公卿与簪笏。","青门抗行谢客儿，健笔连羁王献之。","长安素绢书欲徧，主人爱惜常保持。","每叹二疏不足道，复言四皓常枯槁。","去年寝疾弥数旬，神鬼盈庭谋一老。","长男泣血求司命，少女[颦]（频）眉诵《灵宝》。","还如简子复归来，更与洪崖同寿考。","上书北阙言授箓。","税驾东州愿修道。","初闻行路犹未信，果达吾君谓之好。","山阴旧宅作仙坛，湖上闲田种芝草。","镜湖之水含杳冥，会稽仙洞多精灵。","须乘赤鲤游沧海，当以群鹅写道经。","皇恩赠诗四十字，明主赐金三十镒。","供帐倾朝一送归，双童驷马从兹出。","回看紫绶若轻尘，远别青门嗟故人。","鸳鹭差池攀羽盖，虹霓夭矫翊车轮。","田田列侍浮丘伯，曾子荣过朱买臣。","余高若是有先觉，灭迹归根从大朴。","千载悠悠等令威，十洲漫漫思方朔。","归去来，青牛顿足少迟回。","忽然云雾不相见，唯有飘飘香气来。","（见宋孔延之编《会稽掇英总集》卷二）。"],"theme":"送别","theme2":[],"style":"婉约","style2":["豪放","冲淡"],"mood":"恬淡","mood2":["相思","悲怆"],"scene":["江","园林"],"cats":{"抒情":["友情","思念"],"天气":["彩虹"]},"theme_conf":0.441},{"uid":"5afe3c27-812c-4eed-bb30-74e657009e41","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风破南极，朱凤日威垂。","洞庭秋欲雪，鸿雁将安归。","十年杀气盛，六合人烟稀。","吾慕汉初老，时清犹茹芝。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["江","雪","秋","园林","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.65},{"uid":"0c7f80dd-29e4-4c72-b4b5-f967aa52b51a","title":"渔父歌 一","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西塞山前白鹭飞，桃花流水鳜鱼肥。","青篛笠，绿蓑衣，斜风细雨不须归。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","塞外"],"cats":{"天气":["写雨"],"人物":["父亲"]},"theme_conf":0.642},{"uid":"31df356e-d9f2-4984-8f0e-66349cab666e","title":"横吹曲辞 关山月","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["汉月生辽海，曈昽出半晖。","合昏玄兔郡，中夜白登围。","晕落关山迥，光合霜霰微。","将军听晓角，战马欲南归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","塞外","山"],"cats":{"抒情":["思乡"],"天气":["月亮"],"人生":["战争"]},"theme_conf":0.544},{"uid":"efad3f8b-87d3-406e-a916-fc8fb2bdf381","title":"秋日登岳阳楼晴望","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三秋倚练飞金盏，洞庭波定平如刬。","天高云卷绿罗低，一点君山碍人眼。","漫漫万顷铺琉璃，烟波阔远无鸟飞。","西南东北竞无际，直疑侵断青天涯。","屈原回日牵愁吟，龙宫感激致应沈。","贾生憔悴说不得，茫茫烟霭堆湖心。"],"theme":"咏史怀古","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["清新","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","江","秋"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.414},{"uid":"c2e105eb-bf47-46ea-b2d3-fc6e0613e869","title":"冬日有怀李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞书斋里，终朝独尔思。","更寻嘉树传，不忘角弓诗。","短褐风霜入，还丹日月迟。","未因乘兴去，空有鹿门期。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"c5c4e4d0-682a-4c8f-9756-c181dc9a52dc","title":"杂曲歌辞 羽林行","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔雪寒断指，朔风劲裂冰。","胡中射雕者，此日犹不能。","翩翩羽林儿，锦臂飞苍鹰。","挥鞭决白马，走出黄河凌。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","江"],"cats":{"四季":["冬天"],"山水":["黄河"],"天气":["写风"]},"theme_conf":0.509},{"uid":"c1854cf4-5d46-4e9f-b6c2-5d29f71a57cd","title":"奉和幸韦嗣立山庄侍宴应制","author":"李峤","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南洛师臣契，东岩王佐居。","幽情遗绂冕，宸眷属樵渔。","制下峒山跸，恩回灞水舆。","松门驻旌盖，薜幄引簪裾。","石磴平黄陆，烟楼半紫虚。","云霞仙路近，琴酒俗尘疎。","乔木千龄外，悬泉百丈余。","崖深经炼药，穴古旧藏书。","树宿抟风鸟，池潜纵壑鱼。","宁知天子贵，尚忆武侯庐。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"],"天气":["写云"]},"theme_conf":0.98},{"uid":"5561dd82-ac19-4c72-ba0c-a941cec526c8","title":"酬李少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["出塞魂屡惊，怀贤意难说。","谁知吾道间，乃在客中别。","日夕捧琼瑶，相思无休歇。","伊人虽薄宦，举代推高节。","述作凌江山，声华满冰雪。","一登蓟丘上，四顾何惨烈。","来雁无尽时，边风正骚屑。","将从崖谷遁，且与沈浮绝。","君若登青云，余当投魏阙。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雪","冬","塞外"],"cats":{"抒情":["思念"],"天气":["写雪"]},"theme_conf":0.94},{"uid":"cpff779c5996e524","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霁景风软，烟江春涨。","小阁无人，绣帘半上。","花外姊妹相呼。","约樗蒲。","修蛾忘了章台样。","细思一饷。","感事添惆怅。","胸酥臂玉消减，拟觅双鱼。","倩传书。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"惆怅","mood2":["孤寂"],"scene":["花","月","楼","春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"山水":["江河"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"45c8fb06-8bc7-4f39-8874-9d6748c12fb9","title":"杂曲歌辞 凉州 歌第二","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朔风吹叶鴈门秋，万里烟尘昏戍楼。","征马长思青海北，胡笳夜听陇山头。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","楼","夜","冬","山"],"cats":{"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"b881b056-6d92-45e8-9620-4710a375776f","title":"和晋陵陆丞早春游望","author":"杜审言","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光转绿苹。","忽闻歌古调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"b301d20a-9934-4e51-bada-c92bd451baaf","title":"织女词","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["凤梭停织鹊无音，梦忆仙郎夜夜心。","难得相逢容易别，银河争似妾愁深。"],"theme":"送别","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.542},{"uid":"1130a58d-d738-46e6-8052-1252a540540d","title":"江边星月二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江月辞风缆，江星别雾船。","鸡鸣还曙色，鹭浴自清川。","历历竟谁种，悠悠何处圆。","客愁殊未已，他夕始相鲜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["月亮","星星"]},"theme_conf":1.0},{"uid":"cp72c5d65e1c6c79","title":"玉胡蝶・玉蝴蝶","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚雨未摧宫树，可怜闲叶，犹抱凉蝉。","短景归秋，吟思又接愁边。","漏初长、梦魂难禁，人渐老、风月俱寒。","想幽欢。","土花庭，虫网阑干。","无端。","啼蛄搅夜，恨随团扇，苦近秋莲。","一笛当楼，谢娘悬泪立风前。","故园晚、强留诗酒，新雁远、不致寒暄。","隔苍烟。","楚香罗袖，谁伴婵娟。"],"theme":"爱情相思","theme2":["闲适隐逸","边塞征战","哲理悟道"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","园林","楼","夜","中秋","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.8},{"uid":"97c98650-151d-4c52-8504-1e6c66820058","title":"赠裴九侍御昌江草堂弹琴","author":"贾至","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朔风吹疎林，积雪在崖𪩘。","鸣琴草堂响，小涧清且浅。","沈吟东山意，欲去芳岁晚。","怅望黄绮心，白云若在眼。"],"theme":"题画咏艺","theme2":["送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江","冬","雪"],"cats":{"四季":["冬天"],"天气":["写风","写雪"]},"theme_conf":0.41},{"uid":"294a2fee-f9ee-4b2b-9442-f15496b6eb8e","title":"不离西阁二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西阁从人别，人今亦故亭。","江云飘素练，石壁断空青。","沧海先迎日，银河倒列星。","平生耽胜事，吁骇始初经。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","江"],"cats":{"抒情":["离别"],"天气":["星星"]},"theme_conf":1.0},{"uid":"cc5abbb6-01a9-4346-8ba9-29770f446154","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山雨不作埿，江云薄为雾。","晴飞半岭鹤，风乱平沙树。","明灭洲景微，隐见岩姿露。","拘闷出门游，旷绝经目趣。","消中日伏枕，卧久尘及屦。","岂无平肩舆，莫辨望乡路。","兵戈浩未息，蛇虺反相顾。","悠悠边月破，郁郁流年度。","针灸阻朋曹，糠籺对童孺。","一命须屈色，新知渐成故。","穷荒益自卑，飘泊欲谁诉。","虺羸愁应接，俄顷恐违迕。","浮俗何万端，幽人有独步。","庞公竟独往，尚子终罕遇。","宿留洞庭秋，天寒潇湘素。","杖策可入舟，送此齿发暮。"],"theme":"羁旅思乡","theme2":["边塞征战","山水田园","送别"],"style":"清新","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"天气":["写雨"],"人生":["时光"]},"theme_conf":0.356},{"uid":"9d551104-88c1-4011-b24a-2ef8f5e60731","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["如折芙蓉栽旱地，似抛芍药挂高枝。","云埋水隔无人识，唯有南宾太守知。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["月","冬","夏","花","山"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["写云","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.488},{"uid":"cp0421a4bd503827","title":"唐多令","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["何处合成愁。","离人心上秋。","纵芭蕉、不雨也飕飕。","都道晚凉天气好，有明月、怕登楼。","年事梦中休。","花空烟水流。","燕辞归、客尚淹留。","垂柳不萦裙带住，漫长是、系行舟。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"]},"theme_conf":0.551},{"uid":"8d968574-77fb-46e2-9594-d31f60408227","title":"同群公宿开善寺赠陈十六所居","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驾车出人境，避暑投僧家。","裴回龙象侧，始见香林花。","读书不及经，饮酒不胜茶。","知君悟此道，所未搜袈裟。","谈空忘外物，持诫破诸邪。","则是无心地，相看唯月华。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏","花","酒","月"],"cats":{"四季":["夏天"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.72},{"uid":"28968a18-20d9-4c42-91ea-98e53f9e769e","title":"咏雨","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["罩云飘远岫，喷雨泛长河。","低飞昏岭腹，斜足洒岩阿。","泫丛珠缔叶，起溜镜图波。","蒙柳添丝密，含吹织空罗。"],"theme":"咏物","theme2":["山水田园"],"style":"绮丽","style2":["冲淡","雄浑"],"mood":"孤寂","mood2":[],"scene":["雨","山"],"cats":{"天气":["写雨"]},"theme_conf":0.639},{"uid":"5eb98284-b6e8-4232-acf1-47cc896293d1","title":"和中书侍郎院壁画云","author":"李收","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["粉壁画云成，如能上太清。","影从霄汉发，光照掖垣明。","暎筿多幽趣，临轩得野情。","独思作霖雨，流润及生灵。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.649},{"uid":"63aed9a9-4229-4f68-8fe9-e626ae91b5a0","title":"盐州过胡儿饮马泉","author":"李益","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿杨著水草如烟，旧是胡儿饮马泉。","几处吹笳明月夜，何人倚劒白云天。","从来冻合关山路，今日分流汉使前。","莫遣行人照容鬓，恐惊憔悴入新年。"],"theme":"边塞征战","theme2":["山水田园"],"style":"婉约","style2":["清新"],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"天气":["月亮"],"节日":["春节"],"动物":["写马"]},"theme_conf":0.391},{"uid":"cpd4e5b07119f773","title":"临江仙","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["梦后楼台高锁，酒醒帘幕低垂。","去年春恨却来时。","落花人独立，微雨燕双飞。","记得小苹初见，两重心字罗衣。","琵琶弦上说相思。","当时明月在，曾照彩云归。"],"theme":"爱情相思","theme2":["游仙梦幻","题画咏艺","闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","江","楼"],"cats":{"抒情":["爱情","思念","闺怨"],"天气":["写云","月亮"]},"theme_conf":0.292},{"uid":"fae03a94-8286-4f27-87d2-76a614bdb218","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 一","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓现，因雨影东西。","晨现必当雨未止，晚来东现日光辉，术者细观之。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"2516cd79-8ae0-47b0-9bad-0a807c57dbb1","title":"紫参歌","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["远公林下满青苔，春药偏宜间石开。","往往幽人寻水见，时时仙蝶隔云来。","阴阳雕刻花如鸟，对凤连鸡一何小。","春风宛转虎溪傍，紫翼红翘翻霁光。","贝叶经前无住色，莲花会里暂留香。","蓬山才子怜幽性，白云阳春动新咏。","应知仙卉老云霞，莫赏夭桃满蹊迳。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"81c3df1e-6db1-43ab-8b2e-1fa9490f6531","title":"九日杨奉化会白水崔明府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今日潘怀县，同时陆浚仪。","坐开桑落酒，来把菊花枝。","天宇清霜净，公堂宿雾披。","晚酣留客舞，凫舄共差池。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"7066e611-faa5-427c-8fce-e0bf10c55416","title":"杂曲歌辞 盖罗缝 一","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秦时明月汉时关，万里征人尚未还。","但愿龙庭神将在，不教胡马渡阴山。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨","豪放"],"mood":"慷慨","mood2":[],"scene":["山","月"],"cats":{"天气":["月亮"],"生活":["边塞"]},"theme_conf":0.573},{"uid":"cf912dac-30ed-4f16-a951-ddecd90387ed","title":"郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["斋居栽竹北窗边，素壁新开映碧鲜。","青蔼近当行药处，绿阴深到卧帷前。","风惊晓叶如闻雨，月过春枝似带烟。","老子忆山心暂缓，退公闲坐对婵娟。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":["恬淡","相思"],"scene":["夏","中秋","楼","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.464},{"uid":"995a9440-f8e3-4a9b-843d-27a34ea8b671","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伐竹为桥结构同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顾我老非题柱客，知君才是济川功。","合欢却笑千年事，驱石何时到海东。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["冬","江"],"cats":{"四季":["冬天"],"天气":["太阳"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.52},{"uid":"8de88b9b-bb36-4f7e-a2cd-4771ff984a8a","title":"喜雪","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧昏朝合雾，丹卷暝韬霞。","结叶繁云色，凝璚徧雪华。","光楼皎若粉，映幕集疑沙。","泛柳飞飞絮，粧梅片片花。","照璧台圆月，飘珠箔穿露。","瑶洁短长阶，玉藂高下树。","映桐珪累白，萦峰莲抱素。","断续气将沈，徘徊岁云暮。","怀珍媿隐德，表瑞伫丰年。","橤间飞禁苑，鹤处舞伊川。","傥咏幽兰曲，同懽黄竹篇。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","冬"],"cats":{"天气":["写雪"]},"theme_conf":1.0},{"uid":"cfefd449-c8d9-4b64-b391-480f64682615","title":"陪王使君晦日泛江就黄家亭子二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有径金沙软，无人碧草芳。","野畦连蛱蝶，江槛俯鸳鸯。","日晚烟花乱，风生锦绣香。","不须吹急管，衰老易悲伤。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["江","花"],"cats":{"抒情":["爱情","伤感","孤独"],"山水":["江河"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"101844bd-db52-4b7b-a097-c45162545c77","title":"同李九士曹观壁画云作","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["始知帝乡客，能画苍梧云。","秋天万里一片色，只疑飞尽犹氛氲。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写云"]},"theme_conf":0.733},{"uid":"cp593585bc170a9b","title":"御街行","author":"范仲淹","dynasty":"宋","section":"宋词","form":"词","paragraphs":["纷纷堕叶飘香砌。","夜寂静、寒声碎。","真珠帘卷玉楼空，天淡银河垂地。","年年今夜，月华如练，长是人千里。","愁肠已断无由醉。","酒未到、先成泪。","残灯明灭枕头欹。","谙尽孤眠滋味。","都来此事，眉间心上，无计相回避。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["酒","夜"],"cats":{"抒情":["伤感","孤独"],"天气":["月亮"]},"theme_conf":0.9},{"uid":"b3e78cdb-4a2b-439c-99da-34b466fe138e","title":"暮春题瀼西新赁草屋五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩云阴复白，锦树晓来青。","身世双蓬鬓，乾坤一草亭。","哀歌时自短，醉舞为谁醒。","细雨荷锄立，江猨吟翠屏。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽"],"mood":"悲怆","mood2":[],"scene":["雨","春"],"cats":{"四季":["春天"],"天气":["写云","写雨"]},"theme_conf":1.0},{"uid":"c0944f9f-23d3-4187-9968-bf7a253903dd","title":"观竞渡","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三月三日天清明，杨花绕江啼晓莺。","使君未出郡斋内，江上已闻齐和声。","使君出时皆有引，马前已被红旗阵。","两岸罗衣破鼻香，银钗照日如霜刃。","鼓声三下红旗开，两龙跃出浮水来。","擢影斡波飞万劒，鼓声劈浪鸣千雷。","雷声冲急波相近，两龙望标目如瞬。","江上人呼霹雳声，竿头彩挂虹霓晕。","前船抢水已得标，后船失势空挥桡。","疮眉血首争不定，输岸一朋心似烧。","只将标示输赢赏，两岸十舟五来往。","须臾戏罢各东西，竞脱文身请书上。","吾今细观竞渡儿，何殊当路权相持。","不思得所各休去，会到摧舟折楫时。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["舟","清明","花"],"cats":{"抒情":["闺怨"],"天气":["彩虹"],"节日":["清明节"]},"theme_conf":0.568},{"uid":"7e26f9c9-ef6f-4b26-bf34-c683d1e41786","title":"杂曲歌辞 长相思","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日迟，一日肠九回。","妾住洛桥北，君住洛桥南。","十五即相识，今年二十三。","有如女萝草，生在松之侧。","蔓短枝苦高，萦回上不得。","人言人有愿，愿至天必成。","愿作远方兽，步步比肩行。","愿作深山木，枝枝连理生。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","春"],"cats":{"抒情":["爱情","思念"],"四季":["春天","秋天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"189ab60e-c415-4aa2-b883-e6a899426407","title":"乌程水楼留别","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["悠悠千里去，惜此一尊同。","客散高楼上，帆飞细雨中。","山程随远水，楚思在青枫。","共说前期易，沧波处处同。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","雨"],"cats":{"抒情":["离别"],"天气":["写雨"]},"theme_conf":0.561},{"uid":"103a8266-2d76-413d-9cde-e32f15f47d4c","title":"九月九日幸临渭亭登高得秋字","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月正乘秋，三杯兴已周。","泛桂迎尊满，吹花向酒浮。","长房萸早熟，彭泽菊初收。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","月","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.92},{"uid":"09c772f5-e6c7-4b3c-9902-1a0af8e8255c","title":"绝句九首 九","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["设道春来好，狂风大放颠。","吹花随水去，飜却钓鱼船。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["春","舟"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":1.0}];
